import React from 'react';
import '../../styles/Button.scss';

import BackIcon from '../../assets/back_button.svg';
import CloseIcon from '../../assets/close.svg';

const Button = ({ children, className, onClick, style, onMouseOver, onMouseLeave }) => {
  if (typeof className === 'string') {
    className = `Button ${className}`
  } else if (typeof className === 'object') {
    className = ['Button', ...className].join(' ');
  } else {
    className = 'Button';
  }

  if (className.indexOf('back') !== -1) {
    return <button className={className} onClick={onClick} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
      <img alt='back' src={BackIcon} />
      { children }
    </button>;
  }

  if (className.indexOf('next') !== -1) {
    return <button className={className} onClick={onClick} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
      { children }
      <img alt='next' src={BackIcon} />
    </button>;
  }

  if (className.indexOf('close-btn') !== -1) {
    return <button className={className} onClick={onClick} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
      <img alt='close-btn' src={CloseIcon} />
      { children }
    </button>;
  }

  return <button className={className} onClick={onClick} style={style} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
    { children }
  </button>;
}

export default Button;
