import React, { useState, useEffect, useContext } from 'react';

import { useHistory } from 'react-router-dom';

import '../styles/DriveMode.scss';

import Modal from 'react-bootstrap/Modal';
import copy from "clipboard-copy";

import Button from './lib/Button';

import Header from './Header';
import Footer from './Footer';
import PiCamera from './PiCamera';

import { DefaultContext } from '../contexts/DefaultContext';
import { SocketContext } from '../contexts/SocketContext';
import { PiCameraContext } from '../contexts/PiCameraContext';

import DirectionPad from "../assets/drive_directionpad_base_arrows.svg";
import DirectionActive from "../assets/drive_direction_active_witharrow.svg";
import StopUp from "../assets/stop_up.svg";
import StopDown from "../assets/stop_down.svg";
import WheelIcon from "../assets/main_steeringwheel.svg";
import colorIcon from "../assets/drive/color.png";
import bwIcon from "../assets/drive/bw.png";
import faceIcon from "../assets/drive/face.png";
import qrIcon from "../assets/drive/qr.png";
import CameraIcon from '../assets/camera_icon.svg';

const cameraMode = {
  "color": {
    "en": "Color Mode",
    "ko": "색상모드",
    "emoji": colorIcon
  },
  "gray": {
    "en": "Gray Scale",
    "ko": "흑백모드",
    "emoji": bwIcon
  },
  "face": {
    "en": "Face Recognition",
    "ko": "얼굴인식",
    "emoji": faceIcon
  },
  "qr": {
    "en": "QR Code",
    "ko": "QR코드",
    "emoji": qrIcon
  }
};

const animations = {
  "angry": {
    "en": "Angry",
    "ko": "화남",
    "emoji": "😡"
  },
  "awake": {
    "en": "Awake",
    "ko": "깨우기",
    "emoji": "🥱"
  },
  "happy": {
    "en": "Happy",
    "ko": "행복",
    "emoji": "😁"
  },
  "celebrate": {
    "en": "Celebrate",
    "ko": "축하",
    "emoji": "🥳"
  }
}

let _driving;

const DriveMode = (props) => {
  let history = useHistory();
  const { text, currentUser, language } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);
  const { streamingSocket, running, trying, checkCameraConnection, closePiStreaming, closeStreamingSocket } = useContext(PiCameraContext);

  const [isMobile, setIsMobile] = useState(false);

  const [currentCameraMode, setCurrentCameraMode] = useState(cameraMode.color);
  const [lastAnimation, setLastAnimation] = useState(animations.angry);
  const [showCameraModeDropdown, setShowCameraModeDropdown] = useState(false);
  const [showAnimationsDropdown, setShowAnimationsDropdown] = useState(false);
  const [qrMsg, setQrMsg] = useState('');
  const [qrTextCopied, setQrTextCopied] = useState(false);
  const [showTextModal, setShowTextModal] = useState(false);
  const [showCameraModal, setShowCameraModal] = useState(false);
  const [showAnimationsModal, setShowAnimationsModal] = useState(false);
  const [screenText, setScreenText] = useState('');

  const [driving, setDriving] = useState(true);
  const [stopMotorsImg, setStopMotorsImg] = useState(StopUp);
  const [stopCameraImg, setStopCameraImg] = useState(StopUp);

  const [clickArrowUp, setClickArrowUp] = useState(false);
  const [clickArrowLeft, setClickArrowLeft] = useState(false);
  const [clickArrowRight, setClickArrowRight] = useState(false);
  const [clickArrowDown, setClickArrowDown] = useState(false);


  useEffect(() => {
    _driving = true;
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('keyup', handleKeyUp);
    checkCameraConnection();
    return () => {
      _driving = false;
      stopMotors();
      stopCamera();
      closeStreamingSocket();
    }
  }, []);

  
  const handleKeyDown = (e) => {
    if(!_driving) return;

    let handleKey = e.key;
    socket.emit("zumi_direction", handleKey);

    if(handleKey === "ArrowUp") {
      setClickArrowUp(true);
    } else if(handleKey === "ArrowDown") {
      setClickArrowDown(true);
    } else if(handleKey === "ArrowLeft") {
      setClickArrowLeft(true);
    } else if(handleKey === "ArrowRight") {
      setClickArrowRight(true);
    }
  }

  const handleKeyUp = (e) => {
    socket.emit("zumi_stop");
    setClickArrowUp(false);
    setClickArrowDown(false);
    setClickArrowLeft(false);
    setClickArrowRight(false);
  }

  const goToMainPage = () => {
    history.push('/main');
  }

  const openCameraModeDropdown = () => {
    setShowCameraModeDropdown(true);
    setShowAnimationsDropdown(false);
  }

  const changeMode = (modeName) => {
    if(currentCameraMode === 'qr') {
      streamingSocket.removeAllListeners('qr_msg');
    } else {
      if (modeName === 'qr') {
        streamingSocket.on('qr_msg', (data) => {
          setQrMsg(data);
        });
      }
    }
    setCurrentCameraMode(cameraMode[modeName]);
    streamingSocket.emit('change_mode', modeName);
    setShowCameraModal(false);
  }

  const openAnimationsDropdown = () => {
    setShowCameraModeDropdown(false);
    setShowAnimationsDropdown(true);
  }

  const runLastAnimation = () => {
    let eventName = 'zumi_' + lastAnimation["en"].toLowerCase();
    socket.emit(eventName);
  }

  const changeAnimations = (animation) => {
    setLastAnimation(animations[animation]);
    let eventName = 'zumi_' + animation;
    socket.emit(eventName);
  }

  const copyQRText = () => {
    copy(qrMsg);
    setQrTextCopied(true);
    setTimeout(() => {
      setQrTextCopied(false);
    }, 3000);
  }


  const directionMouseUp = (e) => {
    if(!driving) return;
    e.stopPropagation();
    setClickArrowUp(true);
    socket.emit("zumi_direction", "ArrowUp");
  }

  const directionMouseDown = (e) => {
    if(!driving) return;
    e.stopPropagation();
    setClickArrowDown(true);
    socket.emit("zumi_direction", "ArrowDown");
  }

  const directionMouseLeft = (e) => {
    if(!driving) return;
    e.stopPropagation();
    setClickArrowLeft(true);
    socket.emit("zumi_direction", "ArrowLeft");
  }

  const directionMouseRight = (e) => {
    if(!driving) return;
    e.stopPropagation();
    setClickArrowRight(true);
    socket.emit("zumi_direction", "ArrowRight");
  }

  const directionMouseStop = () => {
    socket.emit("zumi_stop");
    setClickArrowUp(false);
    setClickArrowDown(false);
    setClickArrowLeft(false);
    setClickArrowRight(false);
  }

  const stopMotors = () => {
    setDriving(false);
    _driving = false;
    socket.emit('zumi_stop');
    socket.emit('stop_motors');
    document.removeEventListener('keydown', handleKeyDown);
    document.removeEventListener('keyup', handleKeyUp);
  }

  const startMotors = () => {
    setDriving(true);
    _driving = true;
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('keyup', handleKeyUp);
  }

  const stopCamera = () => {
    setCurrentCameraMode(cameraMode['color']);
    closePiStreaming();
  }

  const closeTextModal = () => {
    setShowTextModal(false);
    setScreenText('');
  }

  const onChangeText = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
    }
    const regex = /^[a-zA-Z0-9~@#$^*!%&`()_+=[\]{}|\\,.?: -']*$/;
    let value = e.target.value;
    if (!regex.test(e.target.value)) {
      value = value.replace(
        /[^A-Za-z0-9~@#$^*!%&`()_+=[\]{}|\\,.?: -']/gi,
        ""
      );
    }
    if (value.length > 40) {
      value = value.split("").slice(0, 40).join("");
    }
    setScreenText(value);
  }

  const clearText = () => {
    socket.emit('display_text', '');
  }

  const displayText = () => {
    socket.emit('display_text', screenText);
  }



  const displayTextModal = (
    <Modal className='display-text' show={showTextModal} onHide={closeTextModal}>
      <Modal.Header closeButton>
        <Modal.Title>{text.drive_display_text_btn}</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <p>{text.drive_display_text_body}</p>
        <input value={screenText} onChange={onChangeText} placeholder={text.drive_display_text_placeholder}/>
      </Modal.Body>
      <Modal.Footer>
        <Button className="clear-btn" onClick={clearText}>
          {text.drive_btn_clear}
        </Button>
        <Button className="display-btn" onClick={displayText}>
          {text.drive_btn_display}
        </Button>
      </Modal.Footer>
    </Modal>
  );

  const cameraModal = (
    <Modal className='camera-modal' show={showCameraModal} onHide={() => setShowCameraModal(false)}>
      <Modal.Header closeButton>
        <Modal.Title>{text.drive_camera_mode_title}</Modal.Title>
      </Modal.Header>
      <Modal.Body className='row'>
        <Button
          className={currentCameraMode === cameraMode.color ? "current": ""}
          onClick={() => changeMode('color')}
        >
          <img src={cameraMode.color.emoji} alt="color"/>
          <span>{cameraMode.color[language]}</span>
        </Button>
        <Button
          className={currentCameraMode === cameraMode.gray ? "current": ""}
          onClick={() => changeMode('gray')}
        >
          <img src={cameraMode.gray.emoji} alt="bw"/>
          <span>{cameraMode.gray[language]}</span>
        </Button>
        <Button
          className={currentCameraMode === cameraMode.face ? `current small-font ${language}`: `small-font ${language}`}
          onClick={() => changeMode('face')}
        >
          <img src={cameraMode.face.emoji} alt="face"/>
          <span>{cameraMode.face[language]}</span>
        </Button>
        <Button
          className={currentCameraMode === cameraMode.qr ? "current": ""}
          onClick={() => changeMode('qr')}
        >
          <img src={cameraMode.qr.emoji} alt="qr"/>
          <span>{cameraMode.qr[language]}</span>
        </Button>
      </Modal.Body>
    </Modal>
  );

  const animationsModal = (
    <Modal className='animations-modal' show={showAnimationsModal} onHide={() => setShowAnimationsModal(false)}>
      <Modal.Header closeButton>
        <Modal.Title>{text.drive_animations_title}</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <Button
          className={ lastAnimation === animations.angry ? "animations-btn last": "animations-btn"}
          onClick={() => changeAnimations('angry')}
        >
          <span>{animations.angry.emoji}</span>
          <span>{animations.angry[language]}</span>
        </Button>
        <Button
          className={ lastAnimation === animations.awake ? "animations-btn last": "animations-btn"}
          onClick={() => changeAnimations('awake')}
        >
          <span>{animations.awake.emoji}</span>
          <span>{animations.awake[language]}</span>
        </Button>
        <Button
          className={ lastAnimation === animations.happy ? "animations-btn last": "animations-btn"}
          onClick={() => changeAnimations('happy')}
        >
          <span>{animations.happy.emoji}</span>
          <span>{animations.happy[language]}</span>
        </Button>
      </Modal.Body>
    </Modal>
  );

  return (
    <div className='DriveMode'>
      <Header/>
      { displayTextModal }
      { cameraModal }
      { animationsModal }

      <div className='back-btn'>
        <Button className='back' onClick={goToMainPage}>
          <p>{text.btn_back}</p>
        </Button>
      </div>

      <div className="container row">
        <div className="mode-div desktop">
          <div className="camera-mode">
            <p>{text.drive_camera_mode_title}</p>
            <div>
              <Button className={currentCameraMode === cameraMode.face ? `current small-font ${language}`: `current ${language}` }>
                <img src={currentCameraMode.emoji} alt="color"/>
                <span>{currentCameraMode[language]}</span>
              </Button>
              <div className={running? "arrow" : "arrow deactivate"} onClick={running ? openCameraModeDropdown : null}></div>
              <div
                className="dropdown"
                style={{display: showCameraModeDropdown? "": "none"}}
                onClick={() => setShowCameraModeDropdown(false)}
              >
                <Button
                  className={currentCameraMode === cameraMode.color ? "current": ""}
                  onClick={() => changeMode('color')}
                >
                  <img src={cameraMode.color.emoji} alt="color"/>
                  <span>{cameraMode.color[language]}</span>
                </Button>
                <Button
                  className={currentCameraMode === cameraMode.gray ? "current": ""}
                  onClick={() => changeMode('gray')}
                >
                  <img src={cameraMode.gray.emoji} alt="bw"/>
                  <span>{cameraMode.gray[language]}</span>
                </Button>
                <Button
                  className={currentCameraMode === cameraMode.face ? `current small-font ${language}`: `small-font ${language}`}
                  onClick={() => changeMode('face')}
                >
                  <img src={cameraMode.face.emoji} alt="face"/>
                  <span>{cameraMode.face[language]}</span>
                </Button>
                <Button
                  className={currentCameraMode === cameraMode.qr ? "current": ""}
                  onClick={() => changeMode('qr')}
                >
                  <img src={cameraMode.qr.emoji} alt="qr"/>
                  <span>{cameraMode.qr[language]}</span>
                </Button>
              </div>
            </div>
          </div>

          <div className="animations">
            <p>{text.drive_animations_title}</p>
            <div>
              <Button className="last" onClick={runLastAnimation}>
                <span>{lastAnimation.emoji}</span>
                <span>{lastAnimation[language]}</span>
              </Button>
              <div className="arrow" onClick={openAnimationsDropdown}></div>
              <div
                className="dropdown"
                style={{display: showAnimationsDropdown? "": "none"}}
                onClick={() => setShowAnimationsDropdown(false)}
              >
                <Button
                  className={ lastAnimation === animations.angry ? "animations-btn last": "animations-btn"}
                  onClick={() => changeAnimations('angry')}
                >
                  <span>{animations.angry.emoji}</span>
                  <span>{animations.angry[language]}</span>
                </Button>
                <Button
                  className={ lastAnimation === animations.awake ? "animations-btn last": "animations-btn"}
                  onClick={() => changeAnimations('awake')}
                >
                  <span>{animations.awake.emoji}</span>
                  <span>{animations.awake[language]}</span>
                </Button>
                <Button
                  className={ lastAnimation === animations.happy ? "animations-btn last": "animations-btn"}
                  onClick={() => changeAnimations('happy')}
                >
                  <span>{animations.happy.emoji}</span>
                  <span>{animations.happy[language]}</span>
                </Button>
              </div>
            </div>
          </div>

          <Button className='display-btn' onClick={() => setShowTextModal(true)}>
            {text.drive_display_text_btn}
          </Button>
        </div>

        <div className='camera-div'>
          <PiCamera />
          {!running && !trying && (
            <div className='camera-btn'>
              <Button onClick={checkCameraConnection}>
                <img alt='camera' src={CameraIcon}/>
              </Button>
              <p>{text.drive_label_camera_on}</p>
            </div>
          )}
          {running && (
            <div className='camera-btn'>
              <img alt="stop-icon" className='stop-icon'
                onMouseDown={() => setStopCameraImg(StopDown)}
                onMouseUp={() => setStopCameraImg(StopUp)}
                src={stopCameraImg}
                onClick={stopCamera}
              />
              <p>{text.drive_stop}</p>
            </div>
          )}
        </div>

        <div className="control-motors-div">
          <div className={`qr-copied ${language}`} style={{display: qrTextCopied? "": "none"}}>{text.drive_msg_copied_qr_text}</div>
          <Button className='qr-msg' style={{display: currentCameraMode === cameraMode.qr ? '': 'none'}} onClick={copyQRText}>{text.drive_btn_copy_qr_code_text}</Button>
          <div className="control-div">
            <div className="row mx-auto card direction-pad">
              <img alt="direction pad" className="card-img" src={DirectionPad}/>
              <div className="card-img-overlay">
                <div className="row mx-auto">
                  <img alt=""
                    className="direction-btn top"
                    src={DirectionActive}
                    style={{opacity: clickArrowUp ? '' : '0'}}
                    onTouchStart={directionMouseUp}
                    onTouchEnd={directionMouseStop}
                    onTouchMove={directionMouseStop}
                    onMouseDown={isMobile? null: directionMouseUp}
                    onMouseUp={isMobile? null: directionMouseStop}
                    onContextMenu={(e)=> e.preventDefault()}
                  />
                </div>

                <div className="row mx-auto">
                  <img alt=""
                    className="direction-btn left"
                    src={DirectionActive}
                    style={{opacity: clickArrowLeft ? '' : '0'}}
                    onTouchStart={directionMouseLeft}
                    onTouchEnd={directionMouseStop}
                    onTouchMove={directionMouseStop}
                    onMouseDown={isMobile? null: directionMouseLeft}
                    onMouseUp={isMobile? null: directionMouseStop}
                    onContextMenu={(e)=> e.preventDefault()}
                  />
                  <img alt=""
                    className="direction-btn right"
                    src={DirectionActive}
                    style={{opacity: clickArrowRight ? '' : '0'}}
                    onTouchStart={directionMouseRight}
                    onTouchEnd={directionMouseStop}
                    onTouchMove={directionMouseStop}
                    onMouseDown={isMobile? null: directionMouseRight}
                    onMouseUp={isMobile? null: directionMouseStop}
                    onContextMenu={(e)=> e.preventDefault()}
                  />
                </div>

                <div className="row mx-auto">
                  <img alt=""
                    className="direction-btn bottom"
                    src={DirectionActive}
                    style={{opacity: clickArrowDown ? '' : '0'}}
                    onTouchStart={directionMouseDown}
                    onTouchEnd={directionMouseStop}
                    onTouchMove={directionMouseStop}
                    onMouseDown={isMobile? null: directionMouseDown}
                    onMouseUp={isMobile? null: directionMouseStop}
                    onContextMenu={(e)=> e.preventDefault()}
                  />
                </div>
              </div>
            </div>
          </div>

          {driving && (
            <div className="motor-btn">
              <div className="txt">{text.drive_stop_motors}</div>
              <div className="row mx-auto">
                <img alt="stop-icon"
                  onMouseDown={() => setStopMotorsImg(StopDown)}
                  onMouseUp={() => setStopMotorsImg(StopUp)}
                  src={stopMotorsImg}
                  onClick={stopMotors}
                />
              </div>
            </div>
          )}
          {!driving && (
            <div className="motor-btn">
              <div className="txt">{text.drive_start_motors}</div>
              <div className="row mx-auto">
                <Button
                  className='wheel'
                  onClick={startMotors}
                >
                  <img alt="camera-on" src={WheelIcon} />
                </Button>
              </div>
            </div>
          )}
          <Button className="calibrate" onClick={() => socket.emit("recalibrate")}>{text.drive_btn_recalibrate}</Button>
        </div>
        <div className="mode-div mobile">
          <div className="camera-mode">
            <p>{text.drive_camera_mode_title}</p>
            <div>
              <Button className='emoji current'>
                <img src={currentCameraMode.emoji} alt="color"/>
              </Button>
              <Button className={running ? 'open' : 'open deactivate'} onClick={() => running? setShowCameraModal(true) : null}>
                <span>&nbsp;·&nbsp;&nbsp;·&nbsp;&nbsp;·</span>
              </Button>
            </div>
          </div>

          <div className="animations">
            <p>{text.drive_animations_title}</p>
            <div>
              <Button className="emoji last" onClick={runLastAnimation}>
                <span>{lastAnimation.emoji}</span>
              </Button>
              <Button className="open" onClick={() => setShowAnimationsModal(true)}>
                <span>&nbsp;·&nbsp;&nbsp;·&nbsp;&nbsp;·</span>
              </Button>
            </div>
          </div>

          <Button className='display-btn' onClick={() => setShowTextModal(true)}>
            {text.drive_display_text_btn}
          </Button>
        </div>
      </div>

      <Footer />
    </div>
  )
}

export default DriveMode;