import React, { useState, useEffect, useContext } from 'react';
import { useHistory } from 'react-router-dom';

import Plotly from 'plotly.js-gl3d-dist';
import createPlotlyComponent from 'react-plotly.js/factory';
import copy from "clipboard-copy";

import Button from '../../lib/Button';
import PiCamera from '../../PiCamera';
import Canvas from './Canvas';
import LoadingScreen from '../../LoadingScreen/LoadingScreen';

import { DefaultContext } from '../../../contexts/DefaultContext';
import { SocketContext } from '../../../contexts/SocketContext';
import { PiCameraContext } from '../../../contexts/PiCameraContext';

import '../../../styles/Knn.scss';

import closeImg from '../../../assets/close.svg';
import cameraBtn from '../../../assets/camera_icon.svg';
import checkIcon from '../../../assets/check.svg';
import readingColorsImg from "../../../assets/learning-color/reading_colors.svg";
import trainingColorsImg from "../../../assets/learning-color/training_colors.svg";
import hsvCubeImg from "../../../assets/learning-color/hsv_cube.png";
import zumiHappyFace from '../../../assets/zumiface_happy.svg';
import cluster1 from "../../../assets/learning-color/cluster1-1.svg";
import cluster2 from "../../../assets/learning-color/cluster5-1.svg";
import cluster3 from "../../../assets/learning-color/cluster8.svg";
import cluster4 from "../../../assets/learning-color/cluster4.svg";
import cluster5 from "../../../assets/learning-color/cluster7.svg";
import cluster6 from "../../../assets/learning-color/cluster3-1.svg";
import cluster7 from "../../../assets/learning-color/cluster6-1.svg";
import cluster8 from "../../../assets/learning-color/cluster2.svg";

const Plot = createPlotlyComponent(Plotly);

const order = ["First", "Second", "Third", "Fourth", "Fifth", "Sixth", "Seventh", "Eighth"];
const number = ["one", "two", "three", "four", "five", "six", "seven", "eight"];
const order_ko = ["첫번째", "두번째", "세번째", "네번째", "다섯번째", "여섯번째", "일곱번째", "여덟번째"];
const number_ko = ["한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟"];
const clusters = [cluster1, cluster2, cluster3, cluster4, cluster5, cluster6, cluster7, cluster8];

let predictInterval;

const Knn = (props) => {
  let history = useHistory();

  const { text, language } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);
  const { setRunningDemo, running, checkCameraConnection, closePiStreaming } = useContext(PiCameraContext);

  const [ page, setPage ] = useState(0);
  const [ showFirstColor, setShowFirstColor ] = useState(false);
  const [ modelIsSaved, setModelIsSaved ] = useState(false);
  const [ navbarCircles, setNavbarCircles ] = useState(false);
  const [ labelList, setLabelList ] = useState(
    [
      { id: 1, order: order[0], name: "", total: 0},
      { id: 2, order: order[1], name: "", total: 0},
      { id: 3, order: order[2], name: "", total: 0},
    ]
  );
  const [ cardNumber, setCardNumber ] = useState(number[2]);
  const [ currentDataId, setCurrentDataId] = useState(1);
  const [ lastDataList, setLastDataList ] = useState([null, null, null]);
  const [ isTraining, setIsTraining ] = useState(true);
  const [ currentTestLabel, setCurrentTestLabel ] = useState('');
  const [ labelNumber, setLabelNumber ] = useState(3);
  const [ plotXList, setPlotXList ] = useState([]);
  const [ plotYList, setPlotYList ] = useState([]);
  const [ plotZList, setPlotZList ] = useState([]);
  const [ modelName, setModelName ] = useState('');
  const [ random, setRandom ] = useState(0);
  const [ testPlotX, setTestPlotX ] = useState([]);
  const [ testPlotY, setTestPlotY ] = useState([]);
  const [ testPlotZ, setTestPlotZ ] = useState([]);

  useEffect(() => {
    document.body.style = 'background-color: #f4f1ff';
    if (language.includes("ko")) {
      setLabelList([
        { id: 1, order: order_ko[0], name: "", total: 0},
        { id: 2, order: order_ko[1], name: "", total: 0},
        { id: 3, order: order_ko[2], name: "", total: 0},
      ]);
      setCardNumber(number_ko[2]);
    }
    setRunningDemo(true);
    checkCameraConnection();
    return ( () => {
      document.body.style = 'background-color: #ccf5f1';
      removeAllListeners();
      setRunningDemo(false);
      closePiStreaming();
    })
  }, []);

  const removeAllListeners = () => {
    clearInterval(predictInterval);
    socket.removeAllListeners('add_color_data_result');
    socket.removeAllListeners('color_predict');
  }

  const changeLabelName = (e) => {
    let currentLabelNumber = parseInt(e.target.id);
    let newLabelName = {name: e.target.value};
    let newLabelList = labelList.map(
      label => currentLabelNumber === label.id
        ? { ...label, ...newLabelName }
        : label
    );
    setLabelList(newLabelList);
  }

  const addLabel = () => {
    let order2 = language.includes("ko") ? order_ko[labelNumber] : order[labelNumber];
    let cardNumber = language.includes("ko") ? number_ko[labelNumber] : number[labelNumber];
    let newLabelList = labelList.concat({id: labelNumber+1, order: order2, name: "", total: 0});
    let newLastDataList = lastDataList;
    newLastDataList.push(null);
    setLabelList(newLabelList);
    setCardNumber(cardNumber);
    setLabelNumber(labelNumber + 1);
    setLastDataList(newLastDataList);
  }

  const addColorData = () => {
    let newLabelList = labelList.map(
      label => currentDataId === label.id
        ? { total: label.total++, ...label }
        : label
    );
    setLabelList(newLabelList);
    let labelName = newLabelList.filter(label => label.id === currentDataId)[0].name;
    socket.emit("add_color_data", labelName);
    socket.on("add_color_data_result", getAddDataResult);
  }

  const getAddDataResult = (data) => {
    socket.removeAllListeners("add_color_data_result");
    if(data) {
      drawCanvas();
      setPlotXList(plotXList.concat(data[0]));
      setPlotYList(plotYList.concat(data[1]));
      setPlotZList(plotZList.concat(data[2]));
    } else {
      let newLabelList = labelList.map(
        label => currentDataId === label.id
        ? { total: label.total--, ...label }
        : label
      );
      setLabelList(newLabelList);
    }
  }

  const drawCanvas = () => {
    let img = document.getElementById("pi-streaming");
    img.crossOrigin = "Anonymous";
    let canvas = document.createElement('canvas');
    let ctx = canvas.getContext('2d');
    canvas.width = 320;
    canvas.height = 240;
    ctx.drawImage(img, 0, 0);
    let lastData = ctx.getImageData(0, 0, 320, 240);
    let newLastDataList = lastDataList;
    newLastDataList.splice(currentDataId-1, 1, lastData);
    setLastDataList(newLastDataList);
  }


  const goToGetYourCard = () => {
    let newLabelList = [];
    labelList.map(label => newLabelList.push(label.name));
    socket.emit("learning_color_label_list", newLabelList);
    setPage(2);
    setShowFirstColor(true);
    setNavbarCircles(["done", "", "", "", ""]);
  }

  const goToTrain = () => {
    socket.emit("color_train");
    setShowFirstColor(false);
    setPage(5);
    setIsTraining(true);
    setNavbarCircles(["done", "done", "active", "", ""]);

    setTimeout(() => {
      setIsTraining(false)
    }, 3000);

    setTimeout(() => {
      socket.emit("knn_fit_hsv");
      setPage(6);
      setNavbarCircles(["done", "done", "done", "", ""])
    }, 6000);
  }

  const goToTryOutModel = () => {
    setPage(7);
    setNavbarCircles(["done", "done", "done", "active", ""]);
    predictInterval = setInterval(() => {
      socket.emit("color_predict");
    }, 2000);
    socket.on("color_predict", getPredictResult);
  }

  const getPredictResult = (data) => {
    setTestPlotX([data.feature[0]]);
    setTestPlotY([data.feature[1]]);
    setTestPlotZ([data.feature[2]]);
    setCurrentTestLabel(data.label);
  }

  const startOver = () => {
    removeAllListeners();
    window.location.reload();
  }

  const close = () => {
    removeAllListeners();
    history.push('/explore');
  }

  const goToSaveThisModel = () => {
    removeAllListeners();
    setPage(8);
    setNavbarCircles(["done", "done", "done", "done", "active"]);
  }

  const changeModelName = (e) => {
    let newModelName = e.target.value;
    const regex = /^[a-zA-Z0-9+_-]*$/;
    if(regex.test(newModelName)) {
      setModelName(newModelName);
    } else {
      setModelName(newModelName.replace(/[^A-Za-z0-9+_-]/gi, ''));
    }
  }

  const openFileLocation = () => {
    let fileLocation =
      window.location.protocol +
      "//" +
      window.location.hostname +
      ":5555/tree/Data/color-classifier/" + modelName;
    window.open(fileLocation, "_blank");
  }

  const saveModel = () => {
    socket.emit("knn_save_model", modelName);
    setModelIsSaved(true);
  }

  const goToLesson = () => {
    if (language.includes("ko")) {
      let jupyterLesson =
        window.location.protocol +
        "//" +
        window.location.hostname +
        ":5555/notebooks/Zumi_Content_ko/Lesson/Chapter Demo-01 색상 배우기.ipynb";
      window.open(jupyterLesson, "_blank");
    } else {
      let jupyterLesson =
        window.location.protocol +
        "//" +
        window.location.hostname +
        ":5555/notebooks/Zumi_Content_en/Lesson/5.1 Color Classification.ipynb";
      window.open(jupyterLesson, "_blank");
    }
  }

  return (
    <div className={`Demo Knn ${language}`}>
      { page === 0 && (
        <Button className='close-btn center' onClick={close}>
          <p>{text.demo_btn_close}</p>
        </Button>
      )}

      { page === 0 && (
        <div className='page0 container'>
          <div className="title">{text.demo_color_intro_header}</div>
          <div className="description">
            {text.demo_color_intro_body && (
              text.demo_color_intro_body.split("<b>").map((item,i) => {
                if(i !== 0) {
                  let temp = item.split("</b>");
                  return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}
          </div>
          <img src={readingColorsImg} alt="reading-colors"/>
          <Button onClick={() => {
            socket.emit('start_learning_color');
            setPage(1);
            setNavbarCircles(["active", "", "", "", ""])
          }}>{text.demo_btn_play}</Button>
        </div>
      )}

      { page !== 0 && (
        <div className="nav row">
          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[0]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            
            <div className="nav-txt">{text.demo_color_navbar_create}</div>
          </div>

          <div className="arrow col">
            <div className="line"></div>
            <div className="triangle"></div>
          </div>

          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[1]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="nav-txt">{text.demo_color_navbar_show}</div>
          </div>

          <div className="arrow col">
            <div className="line"></div>
            <div className="triangle"></div>
          </div>

          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[2]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="nav-txt">{text.demo_color_navbar_train}</div>
          </div>

          <div className="arrow col">
            <div className="line"></div>
            <div className="triangle"></div>
          </div>

          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[3]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="nav-txt">{text.demo_color_navbar_test}</div>
          </div>

          <div className="arrow col">
            <div className="line"></div>
            <div className="triangle"></div>
          </div>

          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[4]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="nav-txt">{text.demo_color_navbar_save}</div>
          </div>
        </div>
      )}

      { page === 1 && (
        <div className='page1 container'>
          <div className="title">
            {text.demo_color_create_header && (
              text.demo_color_create_header.split("<b>").map((item,i) => {
                if(i === 1) {
                  let temp = item.split("</b>");
                  return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}
          </div>
          <div className="description">
            {text.demo_color_create_body && (
              text.demo_color_create_body.split("<b>").map((item,i) => {
                if(i !== 0) {
                  let temp = item.split("</b>");
                  return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}
          </div>
          <div className="labels">
            { labelList.map(label => {
              return <div key={label.id} className="label">
                <label htmlFor={label.id}>{label.order} {text.demo_color_create_label_color}</label>
                <input
                  id={label.id}
                  value={label.name}
                  onChange={changeLabelName}
                />
              </div>
            })}
            { labelList.length <= 7 && (
              <div className="label">
                <label> </label>
                <div className="dotted"></div>
              </div>
            )}
          </div>
          <div className="btns">
            <Button className="back" onClick={() => {
              setPage(0);
              setNavbarCircles(["", "", "", "", ""])
            }}>
              {text.btn_back}
            </Button>
            <Button onClick={labelList.length <= 7 ? addLabel: null}>{text.demo_color_create_btn_add}</Button>
            <Button
              className={labelList.filter(label => label.name === "").length === 0 ? "next" : "next deactivate"}
              onClick={labelList.filter(label => label.name === "").length === 0 ? goToGetYourCard: null}
            >
              {text.btn_next}
            </Button>
          </div>
        </div>
      )}

      { page === 2 && (
        <div className='page2 container'>
          <div className="title">{text.demo_color_ready_header}</div>
          <div className="description">
            {text.demo_color_ready_body && (
              text.demo_color_ready_body.split("<b>").map((item,i) => {
                if(i !== 0) {
                  let temp = item.split("</b>");
                  if (temp[0] === "cardNumber") {
                    return <span key={i}><b>{cardNumber}</b>{temp[1]}</span>
                  } else {
                    return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                  }
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}
          </div>
          <div className="labels">
            { labelList.map(label => {
              return <div key={label.id} className="label"><span>{label.name}</span></div>
            })}
          </div>
          <img alt="training-colors" src={trainingColorsImg} />
          <div className="btns">
            <Button className="back" onClick={() => {
              setPage(1)
              setNavbarCircles(["active", "", "", "", ""])
            }}>
              {text.btn_back}
            </Button>
            <Button className="next" onClick={() => {
              setPage(3)
              setNavbarCircles(["done", "active", "", "", ""])
            }}>
              {text.demo_color_ready_btn_start}
            </Button>
          </div>
        </div>
      )}

      { page === 3 && (
        <div className="page3 container">
          { showFirstColor && (
            <div className="title">
              {text.demo_color_train_first_header_1} “<b>{labelList.filter(label => label.id === currentDataId)[0].name}</b>” {text.demo_color_train_first_header_2}
            </div>
          )}
          { !showFirstColor && (
            <div className="title">
              {text.demo_color_train_color_header_1} “<b>{labelList.filter(label => label.id === currentDataId)[0].name}</b>” {text.demo_color_train_color_header_2}
            </div>
          )}
          { showFirstColor && (
            <div className="description">
              {text.demo_color_train_first_body && (
                text.demo_color_train_first_body.split("<b>").map((item,i) => {
                  let labelName = labelList.filter(label => label.id === currentDataId)[0].name;
                  if(i !== 0) {
                    let temp = item.split("</b>");
                    if (temp[0] === "labelName") {
                      return <span key={i}><b>{labelName}</b>{temp[1]}</span>
                    } else {
                      return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                    }
                  } else {
                    return <span key={i}>{item}</span>
                  }
                })
              )}
            </div>
          )}
          { !showFirstColor && (
            <div className="description">
              {text.demo_color_train_color_body && (
                text.demo_color_train_color_body.split("<b>").map((item,i) => {
                  let labelName = labelList.filter(label => label.id === currentDataId)[0].name;
                  if(i !== 0) {
                    let temp = item.split("</b>");
                    if (temp[0] === "labelName") {
                      return <span key={i}><b>{labelName}</b>{temp[1]}</span>
                    } else {
                      return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                    }
                  } else {
                    return <span key={i}>{item}</span>
                  }
                })
              )}
            </div>
          )}
          <div className="content row">
            <div className="col-6">
              <PiCamera className={showFirstColor? '': 'small'} />
              { running && (
                <Button className={showFirstColor? "camera-btn right": "camera-btn left"} onClick={addColorData}>
                  <img src={cameraBtn} alt="camera" />
                </Button>
              )}
            </div>
            <div className={showFirstColor? "col-6 plot-div small": "col-6 plot-div"}>
              <Plot
                data={[
                  {
                    x: plotXList,
                    y: plotYList,
                    z: plotZList,
                    mode: 'markers',
                    type: 'scatter3d',
                    marker: {
                      color: 'rgb(23, 190, 207)',
                      size: 2
                    }
                  }, {
                    alphahull: 7,
                    opacity: 0.1,
                    type: 'mesh3d',
                    x: plotXList,
                    y: plotYList,
                    z: plotZList
                  }
                ]}
                layout={{width: showFirstColor? 280: 400,
                  height: showFirstColor? 157: 240,
                  margin: {
                    l: 20,
                    r: 15,
                    b: 15,
                    t: 15,
                    pad: 0
                  },
                  scene: {
                    aspectratio: {
                      x: 1,
                      y: 1,
                      z: 1
                    },
                    camera: {
                      center: {
                        x: 0,
                        y: 0,
                        z:0
                      },
                      eye: {
                        x: 1.25,
                        y: 1.25,
                        z: 1.25
                      },
                      up: {
                        x: 0,
                        y: 0,
                        z: 1
                      }
                    },
                    xaxis: {
                      type: 'linear',
                      zeroline: false
                    },
                    yaxis: {
                      type: 'linear',
                      zeroline: false
                    },
                    zaxis: {
                      type: 'linear',
                      zeroline: false
                    }
                }}
              }/>
              { showFirstColor && (
                <div className="msg">
                  <p>{text.demo_color_first_msg_1}</p>
                  <p>{text.demo_color_first_msg_2}</p>
                </div>
              )}
            </div>
          </div>
          <div className="labels row">
            {labelList.map( label => {
              return <div key={label.id} className="label col-3">
                        <div className={currentDataId === label.id ? "name active": "name"}>{label.name}</div>
                        <Canvas imgSrc={lastDataList[label.id-1]} number={label.id} />
                        <p>{label.total} {text.demo_color_train_label_examples}</p>
                      </div>
            })}
          </div>
          { showFirstColor && (
            <div className="btns">
              <Button className="back" onClick={() => {
                setPage(2)
                setShowFirstColor(false)
                setNavbarCircles(["done", "", "", "", ""])
              }}>
                {text.btn_back}
              </Button>
              <Button
                className={labelList[0].total < 30? "next deactivate": "next"}
                onClick={labelList[0].total < 30? null: () => setPage(4)}
              >
                {text.demo_color_btn_next_color}
              </Button>
            </div>
          )}
          { !showFirstColor && (
            <div className="btns">
              <Button className="back" onClick={currentDataId === 2 ? () => {
                setPage(4)
                setShowFirstColor(false)
                setCurrentDataId(1)
              }: () => setCurrentDataId(currentDataId - 1)}>
                {text.btn_back}
              </Button>
              {currentDataId === labelList.length ? (
                <Button
                  className={labelList.filter(label => label.total < 30).length === 0 ? "next train": "next train deactivate"}
                  onClick={labelList.filter(label => label.total < 30).length === 0 ? goToTrain: null}
                >
                  {text.demo_color_train_color_btn_start}
                </Button>
              ) : (
                <Button
                  className={labelList[currentDataId-1].total < 30? "next deactivate": "next"}
                  onClick={labelList[currentDataId-1].total < 30? null: () => setCurrentDataId(currentDataId + 1)}
                >
                  {text.demo_color_btn_next_color}
                </Button>
              )}
            </div>
          )}
        </div>
      )}

      { page === 4 && (
        <div className="page4 container">
          <div className="title">{text.demo_color_graph_header}</div>
          <div className="description">
            {text.demo_color_graph_body && (
              text.demo_color_graph_body.split("<b>").map((item,i) => {
                if(i !== 0) {
                  let temp = item.split("</b>");
                  return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}
          </div>
          <div className="row">
            <div className="col-1"></div>
            <div className="col-4">
              <img src={hsvCubeImg} alt="hsv-cube" />
            </div>
            <div className="col-6">
              <div className="hue">
                <div className="name">{text.demo_color_graph_label_hue}</div>
                <div className="explanation">
                  {text.demo_color_graph_explanation_hue}
                </div>
              </div>
              <div className="saturation">
                <div className="name">{text.demo_color_graph_label_saturation}</div>
                <div className="explanation">
                  {text.demo_color_graph_explanation_saturation}
                </div>
              </div>
              <div className="value">
                <div className="name">{text.demo_color_graph_label_value}</div>
                <div className="explanation">
                  {text.demo_color_graph_explanation_value}
                </div>
              </div>
            </div>
            <div className="col-1"></div>
          </div>
          <div className="btns">
            <Button className="back" onClick={() => {
              setShowFirstColor(true);
              setPage(3);
            }}>
              {text.btn_back}
            </Button>
            <Button className="next" onClick={() => {
              setPage(3);
              setShowFirstColor(false);
              setCurrentDataId(2);
            }}>
              {text.demo_color_graph_btn_go}
            </Button>
          </div>
        </div>
      )}

      { page === 5 && (
        <div className="page5 container">
          {isTraining && (
            <div className="title">{text.demo_color_training_header}</div>
          )}
          {!isTraining && (
            <div className="title">{text.demo_color_done_header}</div>
          )}
          {isTraining && (
            <LoadingScreen />
          )}
          {!isTraining && (
            <div>
              <img alt="happy face" src={zumiHappyFace} className="happy-face"/>
              <p>{text.demo_color_done_body}</p>
            </div>
          )}
        </div>
      )}

      { page === 6 && (
        <div className="page6 container">
          <div className="title">{text.demo_color_model_ready_header}</div>
          <div className="description">
            <p>
              {text.demo_color_model_ready_body_1 && (
                text.demo_color_model_ready_body_1.split("<b>").map((item,i) => {
                  if(i !== 0) {
                    let temp = item.split("</b>");
                    return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                  } else {
                    return <span key={i}>{item}</span>
                  }
                })
              )}
            </p>
            <p>{text.demo_color_model_ready_body_2}</p>
          </div>
          <div className="labels">
            { labelList.map(label => {
              return <div key={label.id} className="label">
                <div className="label-name"><span>{label.name}</span></div>
                <img src={clusters[label.id-1]} alt={`cluster${label.id}`}/>
                <div>{label.total} {text.demo_color_train_label_examples}</div>
              </div>
            })}
          </div>
          <div className="btns">
            <Button className="back" onClick={() => {
              setPage(3);
              setShowFirstColor(false);
              setNavbarCircles(["done", "done", "active", "", ""]);
            }}>
              {text.btn_back}
            </Button>
            <Button className='try' onClick={goToTryOutModel}>
              {text.demo_color_model_ready_btn_try}
            </Button>
          </div>
        </div>
      )}

      { page === 7 && (
        <div className="page7 container">
          <div>
            <Plot
              data={[
                {
                  x: plotXList,
                  y: plotYList,
                  z: plotZList,
                  mode: 'markers',
                  type: 'scatter3d',
                  marker: {
                    color: 'rgb(23, 190, 207)',
                    size: 2
                  }
                }, {
                  alphahull: 7,
                  opacity: 0.1,
                  type: 'mesh3d',
                  x: plotXList,
                  y: plotYList,
                  z: plotZList
                },
                {
                  x: testPlotX,
                  y: testPlotY,
                  z: testPlotZ,
                  mode: 'markers',
                  type: 'scatter3d',
                  marker: {
                    color: 'red',
                    size: 4
                  }
                }
              ]}
              layout={{width: 768, height: 440,
                margin: {
                  l: 20,
                  r: 15,
                  b: 15,
                  t: 15,
                  pad: 0,
                  autoexpand: false
                },
                scene: {
                  aspectratio: {
                    x: 1,
                    y: 1,
                    z: 1
                  },
                  camera: {
                    center: {
                      x: 0,
                      y: 0,
                      z:0
                    },
                    eye: {
                      x: 1.25,
                      y: 1.25,
                      z: 1.25
                    },
                    up: {
                      x: 0,
                      y: 0,
                      z: 1
                    }
                  },
                  xaxis: {
                    type: 'linear',
                    zeroline: false
                  },
                  yaxis: {
                    type: 'linear',
                    zeroline: false
                  },
                  zaxis: {
                    type: 'linear',
                    zeroline: false
                  }
              }}
            }/>
            <div className="label">
              <p>{text.demo_color_test_label_label}</p>
              <div>"{currentTestLabel}"</div>
            </div>
            <PiCamera />
          </div>
          <p className="msg-1">{text.demo_color_test_body}</p>
          <div className="btns">
            <Button className="start-over-btn" onClick={startOver}>
              {text.demo_color_test_btn_start_over}
            </Button>
            <Button className='gray-close' onClick={close}>{text.demo_btn_close}</Button>
            <Button className='save' onClick={goToSaveThisModel}>{text.demo_color_test_btn_save}</Button>
          </div>
        </div>
      )}

      { page === 8 && (
        <div className="page8 container">
          { modelIsSaved && (
            <div className="title">{text.demo_color_saved_header}</div>
          )}
          { !modelIsSaved && (
            <div className="title">{text.demo_color_save_header}</div>
          )}
          <div className="description">
            {text.demo_color_save_body}
          </div>
          <div className="labels">
            { labelList.map(label => {
              return <div key={label.id} className="label">
                <div className="label-name"><span>{label.name}</span></div>
                <img src={clusters[label.id-1]} alt={`cluster${label.id}`}/>
                <div>{label.total} {text.demo_color_train_label_examples}</div>
              </div>
            })}
          </div>
          { modelIsSaved && (
            <div className="saved-msg"><b>{text.demo_color_saved_name}</b></div>
          )}
          { !modelIsSaved && (
            <div><b>{text.demo_color_save_name}</b></div>
          )}
          <div className="model-name">
            { modelIsSaved && (
              <div className="saved-model-name">{modelName}</div>
            )}
            { !modelIsSaved && (
              <input
                id="modelName"
                value={modelName}
                onChange={changeModelName}
              />
            )}

            { modelIsSaved && (
              <Button onClick={() => copy(modelName)}>{text.demo_color_btn_copy}</Button>
            )}
            { modelIsSaved && (
              <Button className="open-btn" onClick={openFileLocation}>{text.demo_color_btn_open_file_location}</Button>
            )}
            { !modelIsSaved && (
              <Button
                className={modelName.length < 1 ? "deactivate": ""}
                onClick={modelName.length < 1 ? null: saveModel}
              >
                {text.demo_color_btn_save}
              </Button>
            )}
          </div>
          <div className="btns">
            <Button className="start-over-btn" onClick={startOver}>
              {text.demo_color_test_btn_start_over}
            </Button>
            <Button className="gray-close" onClick={close}>{text.demo_btn_close}</Button>
            <Button
              className={modelIsSaved? "lets-use": "lets-use deactivate"}
              onClick={modelIsSaved? goToLesson: null}
            >
              {text.demo_color_save_btn_lets}
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

export default Knn;