import React, { useState, useEffect, useContext } from 'react';
import socketIOClient from "socket.io-client";

import { DefaultContext } from '../../../contexts/DefaultContext';
import { SocketContext } from '../../../contexts/SocketContext';
import { PiCameraContext } from '../../../contexts/PiCameraContext';

import '../../../styles/Demo.scss';
import '../../../styles/MeetsFamily.scss';

import PiCamera from '../../PiCamera';
import Button from '../../lib/Button';
import LoadingScreen from '../../LoadingScreen/LoadingScreen';

import CameraIcon from '../../../assets/camera_icon.svg';

const MeetsFamily = (props) => {
  const { socket } = useContext(SocketContext);
  const { streamingSocket, setStreamingSocket, setRunningDemo, running } = useContext(PiCameraContext);

  const [page, setPage] = useState(0);
  const [currentLabelNum, setCurrentLabelNum] = useState(0);
  const [countList, setCountList] = useState([0, 0, 0]);
  const [label, setLabel] = useState(['', '', '']);
  
  useEffect(() => {
    setRunningDemo(true);
    document.body.style = 'background-color: #f4f1ff';
    return(() => {
      document.body.style = 'background-color: #ccf5f1';
      setRunningDemo(false);
    });
  }, []);

  useEffect(() => {
    if (running) {
      // let s = socketIOClient('http://192.168.219.107:3456');
      let s = socketIOClient(`${window.location.protocol}//${window.location.hostname}:3456`)
      setStreamingSocket(s);
      s.on('count', (data) => setCountList(data));
    }
  }, [running]);

  const collectData = () => {
    if(!running) return;
    streamingSocket.emit('collect', label, label[currentLabelNum]);
  }

  const training = () => {
    socket.emit('train_face_recognition');
    setPage(3);
    setTimeout(() => {
      setPage(4);
      if(running) streamingSocket.emit('change_mode', 'demo_face_recognition');
    }, 60000);
  }

  const recognition = () => {
    if(!running) return;
    streamingSocket.emit('change_mode', 'demo_face_recognition');
  }

  const onChangeLabel = (e, i) => {
    let changedLabel = [...label];
    changedLabel[i] = e.target.value;
    setLabel(changedLabel);
  }

  return (
    <div className="Demo MeetsFamily">
      { page === 0 && (
        <div className='page0 container'>
          <div className='title'>Zumi meets your family</div>
          <Button onClick={() => setPage(1)}>Training</Button>
          <Button onClick={() => {
            setPage(4);
            if (running) streamingSocket.emit('change_mode', 'demo_face_recognition');
          }}>Play demo</Button>
        </div>
      )}

      { page === 1 && (
        <div className='page1 container'>
          <div className='title'>Add Label</div>
          <div className='list'>
            <div className='name'>
              <span>First : </span>
              <input value={label[0]} onChange={(e) => onChangeLabel(e, 0)}/>
            </div>
            <div className='name'>
              <span>Second : </span>
              <input value={label[1]} onChange={(e) => onChangeLabel(e, 1)}/>
            </div>
            <div className='name'>
              <span>Third : </span>
              <input value={label[2]} onChange={(e) => onChangeLabel(e, 2)}/>
            </div>
          </div>
          <Button onClick={() => setPage(2)}>Next</Button>
        </div>
      )}

      { page === 2 && (
        <div className='page2 container'>
          <div className='title'>Show me {label[currentLabelNum]}!</div>
          <PiCamera />
          {running && (
            <Button className='camera-btn' onClick={collectData}>
              <img src={CameraIcon} alt="camera" />
            </Button>
          )}
          {running && (
            <div>{countList[currentLabelNum]}</div>
          )}
          {currentLabelNum === 2 ? (
            <Button className='next' onClick={training}>Training</Button>
          ) : (
            <Button className='next' onClick={() => setCurrentLabelNum(currentLabelNum+1)}>Next</Button>
          )}
        </div>
      )}

      { page === 3 && (
        <div className='page3 container'>
          <div className='title'>training</div>
          <LoadingScreen />
        </div>
      )}

      { page === 4 && (
        <div className='page4 container'>
          <div className='title'>Test</div>
          <PiCamera />
          {running && (
            <div>
              <Button onClick={recognition}>Start Demo</Button>
              <div>Loading trained model takes around 1 minute. Please wait</div>
            </div>
          )}
          
          
        </div>
      )}
    </div>
  )
}

export default MeetsFamily;