import React, { useState, useContext, useEffect } from 'react';
import '../styles/ConnectNetwork.scss';
import Modal from "react-bootstrap/Modal";
import Button from './lib/Button';

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';

import tryConnect from "../assets/try_connect.gif";
import connectedImg from "../assets/connected.png";
import ZumiSadFace from '../assets/zumiface_sad.svg';


const ConnectNetwork = () => {
  const { text } = useContext(DefaultContext);
  const { showConnectNetwork, tryingToConnectNetwork, succeededConnectingNetwork,
    networkName, tryAgain, disconnectWiFi } = useContext(NetworkContext);
  
  return (
    <Modal className='ConnectNetwork' show={showConnectNetwork} onHide={null}>
      <Modal.Body>
      
      {/* trying to connect network */}
      {tryingToConnectNetwork && (
        <div className='trying'>
          <img alt='trying to connect wifi' src={tryConnect} />
          <p>{text.attempt_connect_msg}</p>
        </div>
      )}

      {/* succeeded connecting network */}
      {!tryingToConnectNetwork && succeededConnectingNetwork && (
        <div className='succeeded'>
          <img alt='succeeded' src={connectedImg} />
          <p>{text.network_connected_msg}<br/><b>{networkName}</b></p>
        </div>
      )}

      {/* failed connecting network */}
      {!tryingToConnectNetwork && !succeededConnectingNetwork && (
        <div className='failed'>
          <img alt='sad face' src={ZumiSadFace} />
          <p>{text.network_failed_msg}</p>
          <Button onClick={tryAgain}>{text.network_failed_btn_try_again}</Button>
          <a onClick={disconnectWiFi}>{text.network_failed_link_offline_mode}</a>
        </div>
      )}
      </Modal.Body>
    </Modal>
  )
}

export default ConnectNetwork;