import React, { useContext, useState, useEffect } from 'react';

import { useHistory } from 'react-router-dom';

import '../styles/Login.scss';

import Dropdown from 'react-bootstrap/Dropdown';
import Modal from 'react-bootstrap/Modal';
import LoadingScreen from './LoadingScreen/LoadingScreen';

import Button from './lib/Button';

import Header from './Header';
import Footer from './Footer';

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';
import { SocketContext } from '../contexts/SocketContext';

import noUserBG from '../assets/user_disabled_screen.svg';
import userBG from '../assets/user_general_icon.svg';
import dotMenu from '../assets/dot_menu.svg';
import happyEyes from "../assets/zumiface_happy_eyes.svg";

let getUsersInterval = null;
let updatingUserContentInterval = null;

const Login = (props) => {
  let history = useHistory();
  const { text, currentUser, setCurrentUser, setShowOverlay } = useContext(DefaultContext);
  const { online, checkingInternet, isLastNetwork } = useContext(NetworkContext);
  const { socket } = useContext(SocketContext);

  const [userList, setUserList] = useState([]);
  const [showUserList, setShowUserList] = useState(true);
  const [newUser, setNewUser] = useState('');
  const [addUserModalShow, setAddUserModalShow] = useState(false);
  const [completeAddUserModalShow, setCompleteAddUserModalShow] = useState(false);
  const [editUserModalShow, setEditUserModalShow] = useState(false);
  const [deleteUserModalShow, setDeleteUserModalShow] = useState(false);
  const [userNameDuplicated, setUserNameDuplicated] = useState(false);
  const [currentUserIndex, setCurrentUserIndex] = useState(-1);
  const [tryToLogin, setTryToLogin] = useState(false);
  const [userContentUpdating, setUserContentUpdating] = useState(false);

  useEffect(() => {
    if (currentUser && currentUser !== "") {
      login(currentUser);
      return;
    }
    socket.emit("get_users");
    socket.on("get_users", getUserList);
    getUsersInterval = setInterval(() => {
      socket.emit("get_users");
    }, 15000);

    return(() => {
      socket.removeAllListeners("get_users");
      socket.removeAllListeners("need_update_user_content");
      clearInterval(getUsersInterval);
      clearInterval(updatingUserContentInterval);
    })
  }, []);

  const getUserList = (data) => {
    socket.removeAllListeners("get_users");
    clearInterval(getUsersInterval);
    setUserList(data);
  }

  const addUser = () => {
    if (!userList.includes(currentUser)) {
      if(currentUser.length !== 0) {
        let addedUserList = [...userList, currentUser];
        setUserList(addedUserList);
        socket.emit('add_user', currentUser);
        setCompleteAddUserModalShow(true);
        setAddUserModalShow(false);
        setCurrentUser('');
        setTimeout(() => {
          setCompleteAddUserModalShow(false);
        }, 2500)
      }
    } else {
      setUserNameDuplicated(true);
    }
  };

  const handleKeyForNewUser = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      addUser();
    }
    const regex = /^[a-zA-Z0-9+_-]*$/;
    let userName = document.getElementById("new-user-name").value;
    if (regex.test(userName)) {
      setCurrentUser(userName);
    } else {
      document.getElementById("new-user-name").value = userName.replace(
        /[^A-Za-z0-9+_-]/gi,
        ""
      );
    }
  };

  const editUser = () => {
    if (!userList.includes(newUser)) {
      if (newUser.length !== 0) {
        let editedUserList = [...userList];
        editedUserList[currentUserIndex] = newUser;
        setUserList(editedUserList);
        socket.emit("change_user_name", [currentUser, newUser]);
        closeModal();
      }
    } else {
      setUserNameDuplicated(true);
    }
  }

  const showEditUserModal = (currentUserName, indexToEdit) => {
    setEditUserModalShow(true);
    setCurrentUser(currentUserName);
    setCurrentUserIndex(indexToEdit);
  }

  const handleKeyForEditUser = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      editUser();
    }
    const regex = /^[a-zA-Z0-9+_-]*$/;
    let newUserName = document.getElementById("edit-user-name").value;
    if (regex.test(newUserName)) {
      setNewUser(newUserName)
    } else {
      document.getElementById("edit-user-name").value = newUserName.replace(
        /[^A-Za-z0-9+_-]/gi,
        ""
      );
    }
  };

  const deleteUser = () => {
    let deletedUserList = [...userList].filter((userName) => userName !== currentUser);
    setUserList(deletedUserList);
    socket.emit("delete_user", currentUser);
    closeModal();
  }

  const showDeleteUserModal = (currentUserName) => {
    setDeleteUserModalShow(true);
    setCurrentUser(currentUserName);
  }

  const login = (userName) => {
    socket.emit("start_user", userName);
    socket.on("need_update_user_content", checkUserContentUpdate);
    setCurrentUser(userName);
    setShowUserList(false);
    setTryToLogin(true);
  }

  const checkUserContentUpdate = (needUpdate) => {
    if (needUpdate) {
      setTryToLogin(false);
      setUserContentUpdating(true);
      setShowOverlay(true);
      socket.emit('check_update_user_content_done');
      updatingUserContentInterval = setInterval(() => {
        socket.emit('check_update_user_content_done');
      }, 5000);
      socket.on('check_update_user_content_done', checkIfUpdatingUserContentDone);
    } else {
      setTimeout(() => {
        history.push('/main');
      }, 3000);
    }
  }

  const checkIfUpdatingUserContentDone = (data) => {
    if (data) {
      clearInterval(updatingUserContentInterval);
      setShowOverlay(false);
      setTimeout(() => {
        history.push('/main');
      }, 3000);
    }
  }

  const closeModal = () => {
    setCurrentUser('');
    setNewUser('');
    setCurrentUserIndex(-1);
    setAddUserModalShow(false);
    setCompleteAddUserModalShow(false);
    setEditUserModalShow(false);
    setDeleteUserModalShow(false);
    setUserNameDuplicated(false);
  }

  const LoadingScreenOverlay = (
    <div className='LoadingScreenOverlay' style={{display: isLastNetwork && checkingInternet? "": "none"}}>
      <LoadingScreen />
    </div>
  );

  return (
    <div className='Login'>
      {LoadingScreenOverlay}
      <Header />
      <Modal 
        centered 
        className='login-modal' 
        show={addUserModalShow} 
        onHide={closeModal}
      >
        <div className='login-modal-content'>
          <Modal.Header closeButton>
            <div className='user-card mx-auto'>
              <div className='card'>
                <img alt='user' className='card-img' src={userBG} />
                <div className='card-img-overlay mx-auto'>
                  <div className='card-name'>
                    {currentUser.length > 8 
                      ? currentUser.substring(0, 8)+'...'
                      : currentUser}
                  </div>
                </div>
              </div>
            </div>
          </Modal.Header>

          <Modal.Body>
            <p className='login-modal-title'>
              {text.create_user_modal_header}
            </p>
            <input
              type='text'
              className='user-modal-input'
              id='new-user-name'
              maxLength='20'
              onKeyUp={handleKeyForNewUser}
            />
            <p
              className='user-name-duplicate'
              style={{
                display: userNameDuplicated ? '' : 'none',
              }}
            >
              {text.error_duplicate_name}
            </p>
          </Modal.Body>

          <Modal.Footer>
            <Button
              className='login-modal-btn mx-auto'
              onClick={addUser}
            >
              {text.create_user_modal_btn_create_user}
            </Button>
          </Modal.Footer>
        </div>
      </Modal>

      <Modal 
        centered 
        className='login-modal' 
        show={completeAddUserModalShow} 
        onHide={closeModal}
      >
        <div className='login-modal-content user-created'>
          <Modal.Header closeButton></Modal.Header>
          <div className='body-footer-overlay'>
          <Modal.Body>
            <div className='login-modal-happy'>
              <img alt='Yay!' src={happyEyes}/>
            </div>
          </Modal.Body>

          <Modal.Footer>
            <div className='login-completed-title mx-auto'>
              {text.create_user_modal_created}
            </div>
          </Modal.Footer>
          </div>
        </div>
      </Modal>

      <Modal 
        centered
        className='login-modal'
        show={editUserModalShow}
        onHide={closeModal}
      >
        <div className='login-modal-content'>
          <Modal.Header closeButton>
            <div className='user-card mx-auto'>
              <div className='card'>
                <img alt='user' className='card-img' src={userBG} />
                <div className='card-img-overlay mx-auto'>
                  <div className='card-name'>
                    {newUser.length > 8 
                      ? newUser.substring(0, 8)+'...'
                      : newUser}
                  </div>
                </div>
              </div>
            </div>
          </Modal.Header>

          <Modal.Body>
            <p className='login-modal-title'>
              {text.change_user_modal_header}
            </p>
            <input
              type='text'
              className='user-modal-input'
              id='edit-user-name'
              maxLength='20'
              onKeyUp={handleKeyForEditUser}
            />
            <p
              className='user-name-duplicate'
              style={{
                display: userNameDuplicated ? '' : 'none',
              }}
            >
              {text.error_duplicate_name}
            </p>
          </Modal.Body>

          <Modal.Footer>
            <Button
              className='login-modal-btn mx-auto'
              onClick={editUser}
            >
              {text.change_user_modal_btn_confirm}
            </Button>
          </Modal.Footer>
        </div>
      </Modal>

      <Modal
        centered
        className="login-modal"
        show={deleteUserModalShow}
        onHide={closeModal}
      >
        <div className='login-modal-content'>
          <Modal.Header closeButton></Modal.Header>

          <Modal.Body>
            <p className='login-modal-title'>
              {text.delete_user_modal_header}
            </p>
            <p className='delete-modal-text'>
              {text.delete_user_modal_msg}
            </p>
          </Modal.Body>

          <Modal.Footer>
            <Button
              className='login-modal-btn-no mx-auto'
              onClick={closeModal}
            >
              {text.delete_user_modal_btn_no}
            </Button>
            <Button
              className='login-modal-btn-yes mx-auto'
              onClick={deleteUser}
            >
              {text.delete_user_modal_btn_yes}
            </Button>
          </Modal.Footer>
        </div>
      </Modal>

      <div
        className="user-need-update-content"
        style={{
          display: userContentUpdating ? "initial" : "none",
        }}
      >
        <div className="container">
          <div className="user-card-modal mx-auto">
            <div className="card mx-auto">
              <img alt="" className="card-img" src={userBG} />
              <div className="card-img-overlay mx-auto">
                <div className="user-name-modal">
                  {currentUser.length > 8 
                  ? currentUser.substring(0, 8) + "..." 
                  : currentUser}
                </div>
              </div>
            </div>
          </div>
          <div className="login-modal-title">{text.sign_in_user_update_title}</div>
          <div className="login-modal-text">
            {text.sign_in_user_update_body}
          </div>
        </div>
      </div>

      <div
        className="try-to-login"
        style={{ display: tryToLogin ? "initial" : "none" }}
      >
        <div className="container">
          <div className="user-card-modal mx-auto">
            <div className="card mx-auto">
              <img alt="" className="card-img" src={userBG} />
              <div className="card-img-overlay mx-auto">
                <div className="user-name-modal">
                  {currentUser.length > 8 
                  ? currentUser.substring(0, 8) + "..." 
                  : currentUser}
                </div>
              </div>
            </div>
          </div>
          <div className="login-modal-title">
            {text.sign_in_user_signing_in} {currentUser}...
          </div>
        </div>
      </div>

      <div style={{ display: showUserList ? "" : "none" }}>
        <div className='container'>
          <h3>{text.sign_in_user_msg}</h3>
          <Button 
            className='add'
            onClick={()=>setAddUserModalShow(true)}
          >
            + {text.sign_in_user_btn_add_user}
          </Button>
          { userList.length === 0 ? (
              <div className='row'>
                <div className='card'><img alt='no user' src={noUserBG}/></div>
                <div className='card'><img alt='no user' src={noUserBG}/></div>
                <div className='card'><img alt='no user' src={noUserBG}/></div>
              </div>
          ) : (
            <div className='row'>
              { userList.map((userName, i) => (
                <div className='card' key={i}>
                  <img alt='user' className='card-img' src={userBG} />
                  <div className='card-img-overlay'>
                    <Dropdown>
                      <Dropdown.Toggle>
                        <img alt='user menu' src={dotMenu} />
                      </Dropdown.Toggle>
                      <Dropdown.Menu>
                        <div className='dropdown-tooltip'></div>
                        <Dropdown.Item onClick={() => showEditUserModal(userName, i)}>
                          {text.sign_in_user_edit}
                        </Dropdown.Item>
                        <Dropdown.Item onClick={() => showDeleteUserModal(userName)}>
                          {text.sign_in_user_delete}
                        </Dropdown.Item>
                      </Dropdown.Menu>
                    </Dropdown>
                    <div
                      className="user-go-to-dashboard"
                      onClick={() => login(userName)}
                    ></div>
                    <p>{userName.length > 8 ? userName.substring(0, 8) + "..." : userName}</p>
                  </div>
                </div>
              ))}
              <div className='card'><img alt='no user' src={noUserBG}/></div>
              {userList.length === 1 ? <div className='card'><img alt='no user' src={noUserBG}/></div> : null}
            </div>
          )}
        </div>
      </div>
      <Footer/>
    </div>
  );
}

export default Login;
