import React, { useState, useEffect, useContext } from 'react';

import { useHistory } from 'react-router-dom';

import '../styles/CodeMode.scss';

import Dropdown from 'react-bootstrap/Dropdown';
import Modal from 'react-bootstrap/Modal';

import Button from './lib/Button';

import Header from './Header';
import Footer from './Footer';

import { DefaultContext } from '../contexts/DefaultContext';
import { SocketContext } from '../contexts/SocketContext';

import backButton from '../assets/back_button.svg';
import blockIcon from '../assets/codemode_block_icon.svg';
import codeIcon from '../assets/codemode_code_icon.svg';
import dotIcon from '../assets/dot_menu.svg';

const CodeMode = (props) => {
  let history = useHistory();
  const { text, currentUser } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);
  
  const [createJupyterModalShow, setCreateJupyterModalShow] = useState(false);
  const [createBlocklyModalShow, setCreateBlocklyModalShow] = useState(false);
  const [deleteCodeModalShow, setDeleteCodeModalShow] = useState(false);
  const [editAction, setEditAction] = useState(false);
  const [fileNameDuplicated, setFileNameDuplicated] = useState(false);
  const [currentFile, setCurrentFile] = useState({fileType: '', displayName: ''});
  const [oldFileDisplayName, setOldFileDisplayName] = useState('');
  const [filesArray, setFilesArray] = useState([]);

  useEffect(() => {
    document.body.style = 'background-color: rgba(236,183,1,0.2);';
    document.querySelector('.background').style = 'background-color: rgba(236,183,1, 0);';

    if (currentUser === "") {
     history.push('/login');
     return;
    }

    socket.emit("code_mode", currentUser);
    socket.on("code_mode", populateProjectList);

    return (() => {
      document.body.style = 'background-color: #ccf5f1;';
      document.querySelector('.background').style = 'background-color: #ccf5f1;';
      socket.removeAllListeners("code_mode");
    })
  }, [])

  const populateProjectList = (data) => {
    socket.removeAllListeners('code_mode');
    if(data.length !== 0) {
      let jupyterArray = data["jupyter"].map(x => {
        let newJupyterObj = {'fileType': 'jupyter', 'displayName':x};
        return newJupyterObj
      });
      let blocklyArray = data["blockly"].map(x => {
        let newBlocklyObj = {'fileType': 'blockly', 'displayName':x.replace('.xml','')};
        return newBlocklyObj
      });
      let filesArray = jupyterArray.concat(blocklyArray);
      setFilesArray(filesArray);
    }
  }

  const showNewJupyterModal = (editAction) => {
    setEditAction(editAction);
    setCurrentFile({fileType: 'jupyter', displayName: ''});
    setCreateJupyterModalShow(true);
  }

  const handleKeyForNewJupyterFile = (e) => {
    if (e.key === "Enter" && !editAction) {
      e.preventDefault();
      newJupyterProject();
    }
    else if (e.key === "Enter" && editAction) {
      e.preventDefault();
      renameJupyterFile();
    }
    const regex = /^[a-zA-Z0-9+_-]*$/;
    var fileName = document.getElementById("new-jupyter-file-name").value;
    if(regex.test(fileName)){
      setCurrentFile({fileType: 'jupyter', displayName: fileName});
    } else {
      document.getElementById("new-jupyter-file-name").value = fileName.replace(/[^A-Za-z0-9+_-]/gi, '');
    }
  }

  const newJupyterProject = () => {
    if(!(filesArray.some(e => e.displayName === currentFile.displayName))) {
     if(currentFile.displayName.length !== 0) {
        let newProjectName = currentFile.displayName;
        socket.emit('create_jupyter', currentUser, currentFile.displayName);
        setTimeout(() => {
          let jupyterNewProject = window.location.protocol + "//" + window.location.hostname+":5555/notebooks/My_Projects/Jupyter/" + newProjectName + ".ipynb";
          window.open(jupyterNewProject, "_blank");
        }, 2000);
        filesArray.push(currentFile);
        closeModal();
      }
    } else {
      setFileNameDuplicated(true);
    }
  }

  const openJupyterProject = (selectedProject) => {
    let jupyterNewProject = window.location.protocol + "//" + window.location.hostname+":5555/notebooks/My_Projects/Jupyter/"+selectedProject.displayName+".ipynb";
    window.open(jupyterNewProject, "_blank");
  }

  const renameJupyterFile = () => {
    if(!(filesArray.some(e => e.displayName === currentFile.displayName))) {
     if(currentFile.displayName.length !== 0) {
       socket.emit("rename_jupyter", currentUser, oldFileDisplayName, currentFile.displayName);
       setTimeout(() =>{
            closeModal();
         }, 1000);
        socket.emit("code_mode", currentUser);
     }
    } else {
      setFileNameDuplicated(true);
    }
  }

  const editJupyterModal = (oldFileDisplayName) => {
    setOldFileDisplayName(oldFileDisplayName);
    showNewJupyterModal(true);
  }

  const deleteJupyterFile = (project) => {
    socket.emit('delete_jupyter', currentUser, project.displayName);
    socket.emit('code_mode', currentUser);
    closeModal();
  }

  const showNewBlocklyModal = (editAction) => {
    setEditAction(editAction);
    setCurrentFile({fileType: 'blockly', displayName: ''});
    setCreateBlocklyModalShow(true);
  }

  const handleKeyForNewBlocklyFile = (e) => {
    if (e.key === "Enter"  && !editAction) {
      e.preventDefault();
      newBlocklyProject();
    }
    else if (e.key === "Enter" && editAction) {
      e.preventDefault();
      renameBlocklyFile();
    }
    const regex = /^[a-zA-Z0-9+_-]*$/;
    var fileName = document.getElementById("new-blockly-file-name").value;
    if(regex.test(fileName)) {
      setCurrentFile({fileType: 'blockly', displayName: fileName})
    } else {
      document.getElementById("new-blockly-file-name").value = fileName.replace(/[^A-Za-z0-9+_-]/gi, '');
    }
  }

  const newBlocklyProject = () => {
    if(!(filesArray.some(e => e.displayName === currentFile.displayName))) {
     if(currentFile.displayName.length !== 0) {
       socket.emit('create_blockly', currentUser, currentFile.displayName);
       setTimeout(() => {
           let blocklyUrl = window.location.protocol + "//" + window.location.hostname+"/blockly?u="+currentUser+"&p="+document.getElementById("new-blockly-file-name").value;
           window.open(blocklyUrl, "_blank");
            closeModal();
         }, 500);
       filesArray.push(currentFile);
     }
    } else {
      setFileNameDuplicated(true);
    }
  }

  const openBlocklyProject = (selectedProject) => {
    setTimeout(() => {
        let blocklyUrl = window.location.protocol + "//" + window.location.hostname+"/blockly?u="+currentUser+"&p="+selectedProject.displayName;
        window.open(blocklyUrl, "_blank");
    }, 1000);
  }

  const renameBlocklyFile = () => {
    if(!(filesArray.some(e => e.displayName === currentFile.displayName))) {
     if(currentFile.displayName.length !== 0) {
       socket.emit('rename_blockly', currentUser, oldFileDisplayName, currentFile.displayName);
       setTimeout(() => {
            closeModal();
         }, 1000);
         socket.emit('code_mode', currentUser);
     }
    } else {
      setFileNameDuplicated(true);
    }
  }

  const editBlocklyModal = (oldFileDisplayName) => {
    setOldFileDisplayName(oldFileDisplayName);
    showNewBlocklyModal(true);
  }

  const deleteBlocklyFile = (project) => {
    socket.emit('delete_blockly', currentUser, project.displayName);
    socket.emit('code_mode', currentUser);
    closeModal();
  }

  const closeModal = () => {
    socket.emit('code_mode', currentUser);
    socket.on('code_mode', populateProjectList);
    setCurrentFile({fileType: '', displayName: ''});
    setFileNameDuplicated(false);
    setCreateJupyterModalShow(false);
    setCreateBlocklyModalShow(false);
    setDeleteCodeModalShow(false);
  }

  const showDeleteCodeModal = (currentFile) => {
    setCurrentFile(currentFile);
    setDeleteCodeModalShow(true);
  }

  const goToMainPage = () => {
    history.push('./main');
  }


  return (
    <div className='CodeMode'>
      <Header/>

      <Modal
        centered
        className="jupyter-modal" 
        show={createJupyterModalShow}
        onHide={closeModal}
      >
        <div className="jupyter-modal-content">
          <Modal.Header closeButton>
            <div className="jupyter-file-div mx-auto text-center">
              <img alt="" className="code-icon" src={codeIcon}/>
              <p className="jupyter-file-name">
                {currentFile.displayName.length > 12 && (
                  currentFile.displayName.substring(0,10) + "..."
                )}
                {currentFile.displayName.length <= 12 && (
                  currentFile.displayName
                )}
                </p>
            </div>
          </Modal.Header>

          <Modal.Body className="text-center">
            {editAction && <p className="jupyter-edit-modal-title">{text.code_mode_modal_edit_header}</p>}
            {!editAction && <p className="jupyter-modal-title">{text.new_notebook_modal_header}</p>}
            <input
              type="text"
              className="file-modal-input text-center"
              id="new-jupyter-file-name"
              maxLength="20"
              pattern="[a-zA-Z0-9]+_-"
              onKeyUp={handleKeyForNewJupyterFile}
            />
            <p
              className="file-name-duplicate"
              style={{display: fileNameDuplicated ? "" : "none"}}
            >
              {text.error_duplicate_name}
            </p>
          </Modal.Body>

          <Modal.Footer>
            {!editAction &&
              <Button
                  className="jupyter-modal-btn mx-auto"
                  onClick={newJupyterProject}
                >
                  {text.new_notebook_modal_btn_create}
              </Button>}
            {editAction &&
              <Button
                  className="jupyter-modal-btn mx-auto"
                  onClick={renameJupyterFile}
                >
                  {text.code_mode_btn_rename}
              </Button>}
          </Modal.Footer>
        </div>
      </Modal>

      <Modal 
        centered
        className="blockly-modal" 
        show={createBlocklyModalShow}
        onHide={closeModal}
      >
        <div className="blockly-modal-content">
          <Modal.Header closeButton>
            <div className="blockly-file-div mx-auto text-center">
              <img alt="" className="block-icon" src={blockIcon}/>
              <p className="blockly-file-name">
                {currentFile.displayName.length > 12 && (
                  currentFile.displayName.substring(0,10) + "..."
                )}
                {currentFile.displayName.length <= 12 && (
                  currentFile.displayName
                )}
              </p>
            </div>
          </Modal.Header>

          <Modal.Body className="text-center">
            {!editAction &&  <p className="blockly-modal-title">{text.new_blockly_modal_header}</p>}
            {editAction && <p className="blockly-edit-modal-title">{text.code_mode_modal_edit_header}</p>}
            <input
              type="text"
              className="file-modal-input text-center"
              id="new-blockly-file-name"
              maxLength="20"
              pattern="[a-zA-Z0-9]+_-"
              onKeyUp={handleKeyForNewBlocklyFile}
            />
            <p
              className="file-name-duplicate"
              style={{display: fileNameDuplicated? "" : "none"}}
            >
              {text.error_duplicate_name}
            </p>
          </Modal.Body>

          <Modal.Footer className="modal-footer">
            {!editAction &&
              <Button
                  className="blockly-modal-btn mx-auto"
                  onClick={newBlocklyProject}
                >
                  {text.new_blockly_modal_btn_create}
              </Button>}
            {editAction &&
              <Button
                  className="blockly-modal-btn mx-auto"
                  onClick={renameBlocklyFile}
                >
                  {text.code_mode_btn_rename}
              </Button>}
          </Modal.Footer>
        </div>
      </Modal>

      <Modal 
        centered
        className="code-delete-modal" 
        show={deleteCodeModalShow}
        onHide={closeModal}
      >
        <div className="code-delete-modal-content">
          <Modal.Header closeButton>
            <div className="code-delete-modal-title mx-auto">{text.code_mode_modal_delete_header}</div>
          </Modal.Header>

          <Modal.Body className="text-center">
            {currentFile.fileType === "jupyter" && (
              <div className="code-file-div mx-auto text-center">
                <img alt="" className="code-icon" src={codeIcon}/>
                <p className="code-file-name">
                  {currentFile.displayName.length > 12 && (
                    currentFile.displayName.substring(0,10) + "..."
                  )}
                  {currentFile.displayName.length <= 12 && (
                    currentFile.displayName
                  )}
                  </p>
              </div>
            )}

            {currentFile.fileType === "blockly" && (
              <div className="block-file-div mx-auto text-center">
                <img alt="" className="block-icon" src={blockIcon}/>
                <p className="block-file-name">
                  {currentFile.displayName.length > 12 && (
                    currentFile.displayName.substring(0,10) + "..."
                  )}
                  {currentFile.displayName.length <= 12 && (
                    currentFile.displayName
                  )}
                </p>
              </div>
            )}

            <p className="code-delete-txt">{text.code_mode_modal_delete_body} <b>{currentFile.displayName}</b>?</p>
          </Modal.Body>

          <Modal.Footer>
            <Button
              className="code-delete-modal-no-btn mx-auto"
              onClick={closeModal}
            >
              {text.btn_no}
            </Button>
            <Button
              className="code-delete-modal-yes-btn mx-auto"
              onClick={() => {
                if(currentFile.fileType === "jupyter") {
                  deleteJupyterFile(currentFile);
                } else if(currentFile.fileType === "blockly") {
                  deleteBlocklyFile(currentFile);
                }
            }}>
              {text.btn_yes}
            </Button>
          </Modal.Footer>
        </div>
      </Modal>

      <div className="code-fixed">
        <Button
          className="back-btn"
          onClick={goToMainPage}
        >
          <img alt="back" src={backButton}/> <p>{text.btn_back}</p>
        </Button>
        <div className="code-header">
          <p className="title">{text.code_mode_header}</p>
          <p className="content" >{text.code_mode_body}</p>
        </div>
        <Button
          className="new-jupyter-btn"
          onClick={() => showNewJupyterModal(false)}
        >
          + {text.code_mode_btn_new_notebook}
        </Button>
        <Button
          className="new-blockly-btn"
          onClick={() => showNewBlocklyModal(false)}
        >
          + {text.code_mode_btn_new_blockly}
        </Button>
      </div>

      <div className="container">
        <div className="row files-div">
          <div className="row files-inner">
            {filesArray.map((item, i) => {
              return <div className="col-lg-3 col-md-4 col-sm-6 col-xs-12 file-div" key={i}>
                {item.fileType === "jupyter" &&
                  <div className="code-file-div mx-auto">
                    <Dropdown>
                      <Dropdown.Toggle>
                        <img alt=""
                          className="file-dot"
                          src={dotIcon}
                        />
                      </Dropdown.Toggle>
                      <Dropdown.Menu>
                        <div className="dropdown-menu-triangle mx-auto"></div>
                        <Dropdown.Item onClick={() => editJupyterModal(item.displayName)}>
                          {text.code_mode_dropdown_edit}
                        </Dropdown.Item>
                        <Dropdown.Item onClick={() => showDeleteCodeModal(item)}>
                          {text.code_mode_dropdown_delete}
                        </Dropdown.Item>
                      </Dropdown.Menu>
                    </Dropdown>
                    <div 
                      className="open-div" 
                      onClick={() => openJupyterProject(item)}
                    >
                      <img alt="code" src={codeIcon}/>
                      <p className="code-file-name">{item.displayName}</p>
                    </div>
                  </div>
                }
                {item.fileType === "blockly" &&
                  <div className="block-file-div mx-auto">
                    <Dropdown>
                      <Dropdown.Toggle>
                        <img alt=""
                          className="file-dot"
                          src={dotIcon}
                        />
                      </Dropdown.Toggle>
                      <Dropdown.Menu>
                        <div className="dropdown-menu-triangle mx-auto"></div>
                        <Dropdown.Item onClick={() => editBlocklyModal(item.displayName)}>
                          {text.code_mode_dropdown_edit}
                        </Dropdown.Item>
                        <Dropdown.Item onClick={() => showDeleteCodeModal(item)}>
                          {text.code_mode_dropdown_delete}
                        </Dropdown.Item>
                      </Dropdown.Menu>
                    </Dropdown>
                    <div className="open-div" onClick={() => openBlocklyProject(item)}>
                      <img alt="blockly" src={blockIcon}/>
                      <p className="block-file-name">{item.displayName}</p>
                    </div>
                  </div>
                }
              </div>
            })}
            <div className="col-lg-3 col-md-4 col-sm-6 col-xs-12 file-div">
              <div className="extra-file-div mx-auto"></div>
            </div>
          </div>
        </div>
      </div>

      <Footer />
    </div>
  )
}

export default CodeMode;