import React, { createContext, useContext, useEffect, useState } from 'react';
import { useHistory } from 'react-router-dom';

import { DefaultContext } from './DefaultContext';
import { NetworkContext } from './NetworkContext';
import { SocketContext } from './SocketContext';

export const UpdateContext = createContext();

let checkUpdateContentInterval;

const UpdateContextProvider = (props) => {
  let history = useHistory();
  
  const { currentUser, setShowOverlay } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);
  const { canUpdateContent, setCanUpdateDashboard, setCanUpdateContent, setFromSwitchingLanguage, setUpdating, setShowUpdate,
    setOfflineContentMissing, networkName, fromSwitchingLanguage } = useContext(NetworkContext);

  const [checkMissingContent, setCheckMissingContent] = useState(false);

  useEffect(() => {
    if(checkMissingContent) {
      checkContentMissing();
    }
    return () => {
      
    }
  }, [checkMissingContent]);

  const checkContentMissing = () => {
    socket.emit('check_content_missing');
    socket.on('check_content_missing', onCheckContentMissing);
  }

  const onCheckContentMissing = (missing) => {
    setCheckMissingContent(false);
    socket.removeAllListeners('check_content_missing');
    if (networkName !== "") { // online mode
      if (missing) { // no base content
        setCanUpdateContent('No_content');
        setCanUpdateDashboard(false);
        setShowUpdate(true);
        setFromSwitchingLanguage(true);
        if(fromSwitchingLanguage) updateContent();
      } else { // no user content
        if (currentUser !== "") {
          socket.emit('check_user_content_missing');
          socket.on('check_user_content_missing', (userContentMissing) => {
            socket.removeAllListeners('check_user_content_missing');
            if (userContentMissing) {
              history.push('/login');
            }
          });
        }
      }
    } else { //offline mode
      if (missing) {
        setFromSwitchingLanguage(true);
        setOfflineContentMissing(true);
      } else {
        // offline , base image exist, user logged in, check user content
        if (currentUser !== "") {
          socket.emit('check_user_content_missing');
          socket.on('check_user_content_missing', (userContentMissing) => {
            socket.removeAllListeners('check_user_content_missing');
            if (userContentMissing) {
              history.push('/login');
            }
          });
        }
      }
    }
  }

  const updateContent = () => {
    if (canUpdateContent === 'No_content') {
      setCanUpdateDashboard(false);
    }
    setUpdating(true);
    setTimeout(() => {
      setShowOverlay(true);
      socket.emit("update_content");
      checkUpdateContentInterval = setInterval(() => {
        socket.emit("check_update_content");
      }, 15000);
      socket.on("check_update_content", onUpdateContentFinish);
    }, 3000);
  }

  const onUpdateContentFinish = (data) => {
    if (data) {
      setShowUpdate(false);
      setFromSwitchingLanguage(false);
      setUpdating(false);
      clearInterval(checkUpdateContentInterval);
      socket.removeAllListeners('check_update_content');
      setShowOverlay(false);
      setCanUpdateContent(false);
      if (currentUser !== '') {
        history.push('/login');
      }
    }
  }

  return (
    <UpdateContext.Provider value={{ updateContent, checkMissingContent, setCheckMissingContent, checkContentMissing }}>
      {props.children}
    </UpdateContext.Provider>
  )
}

export default UpdateContextProvider;