import React, { useContext } from 'react';
import '../styles/Update.scss';
import Modal from "react-bootstrap/Modal";
import Button from './lib/Button';

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';
import { SocketContext } from '../contexts/SocketContext';

import ZumiFaceSad from '../assets/zumiface_sad.svg';

const OfflineContentMissing = () => {
  const { text } = useContext(DefaultContext); 
  const { offlineContentMissing, setOfflineContentMissing, setShowSelectNetwork, wifiListSocket } = useContext(NetworkContext);
  const { socket } = useContext(SocketContext); 

  const close = () => {
    setOfflineContentMissing(false);
  }

  const openSelectNetwork = () => {
    setOfflineContentMissing(false);
    wifiListSocket();
    setShowSelectNetwork(true);
  }
  
  return (
    <Modal className='OfflineMissingContent' show={offlineContentMissing} onHide={close}>
      <Modal.Header closeButton onClick={close}></Modal.Header>
      <Modal.Body>
        <img alt="zumi-face" src={ZumiFaceSad} className="zumi-sad-face"/>
        <p className="msg-1">{ text.missing_content_header }</p>
        <p className="msg-2">{ text.missing_content_offline_msg }</p>
        <Button onClick={openSelectNetwork}>{text.btn_connect_network_for_content}</Button>
      </Modal.Body>
    </Modal>
  )
}

export default OfflineContentMissing;