import React, { createContext, useState, useEffect } from 'react';

export const DefaultContext = createContext();

const DefaultContextProvider = (props) => {
  const [language, setLanguage] = useState('en');
  const [text, setText] = useState({});
  const [zumiName, setZumiName] = useState('');
  const [dashboardVersion, setDashboardVersion] = useState('');
  const [loading, setLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState('');
  const [isJupyterRunning, setIsJupyterRunning] = useState(false);
  const [showOverlay, setShowOverlay] = useState(true);

  useEffect(() => {
    // setLoading(false);
  }, []);

  useEffect(() => {
    const fetchText = async() => {
      const response = await fetch(`zumidashboard_${language}.json`);
      const data = await response.json();
      setText(data);
    }
    fetchText();
  }, [language]);

  const firstSetLanguage = async() => {
    const localData = localStorage.getItem('language');
    if (localData) {
      setLanguage(localData);
      return;
    }
    let _language = window.navigator.language.includes('ko') ? 'ko' : 'en';
    setLanguage(_language);
    localStorage.setItem('language', _language);
  }

  const fetchZumiName = async() => {
    const response = await fetch('hostname.json');
    const data = await response.text();
    setZumiName(data);
  }

  const fetchDashboardVersion = async() => {
    const response = await fetch('data.json');
    const data = await response.json();
    setDashboardVersion(data.libVersion);
  }

  const firstSetup = async() => {
    await firstSetLanguage();
    await fetchZumiName();
    await fetchDashboardVersion();

    setLoading(false);
  }

  return (
    <DefaultContext.Provider value={{ currentUser, language, text, zumiName, dashboardVersion, showOverlay, setShowOverlay,
                                        loading, setCurrentUser, setLanguage, firstSetup, isJupyterRunning, setIsJupyterRunning }}>
      {props.children}
    </DefaultContext.Provider>
  )
}

export default DefaultContextProvider;