import React, { useState, useEffect, useContext } from 'react';
import socketIOClient from "socket.io-client";

import { SocketContext } from '../../../contexts/SocketContext';
import { PiCameraContext } from '../../../contexts/PiCameraContext';

import '../../../styles/Demo.scss';
import '../../../styles/MeetsFamily.scss';

import PiCamera from '../../PiCamera';
import Button from '../../lib/Button';


const SmileDrive = (props) => {
  const { socket } = useContext(SocketContext);
  const { streamingSocket, setStreamingSocket, setRunningDemo, running } = useContext(PiCameraContext);

  const [page, setPage] = useState(0);
  
  useEffect(() => {
    setRunningDemo(true);
    document.body.style = 'background-color: #f4f1ff';
    return(() => {
      document.body.style = 'background-color: #ccf5f1';
      setRunningDemo(false);
    });
  }, []);

  useEffect(() => {
    if (running) {
      // let s = socketIOClient('http://zumidashboard.ai:3456');
      let s = socketIOClient(`${window.location.protocol}//${window.location.hostname}:3456`);
      setStreamingSocket(s);
      setTimeout(() => {
        s.emit('change_mode', 'smile');
      }, 2000);
    }
  }, [running]);


  return (
    <div className="Demo MeetsFamily">
      { page === 0 && (
        <div className='page0 container'>
          <div className='title'>Smile and Drive</div>
          <Button onClick={() => setPage(1)}>Play demo</Button>
        </div>
      )}

      { page === 1 && (
        <div className='page1 container'>
          <div className='title'>How to use?</div>
          <div>When you smile at Zumi Camera,<br/>Zumi detects your smile and forward to you.</div>
          <Button className='next' onClick={() => setPage(2)}>Next</Button>
        </div>
      )}

      { page === 2 && (
        <div className='page3 container'>
          <div className='title'>Smile and Drive</div>
          <PiCamera />
          <div></div>
        </div>
      )}
    </div>
  )
}

export default SmileDrive;