import React, { useContext } from 'react';

import '../App.scss';

import LoadingScreen from './LoadingScreen/LoadingScreen';

import { DefaultContext }  from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';
import { SocketContext } from '../contexts/SocketContext';

const LostConnection = (props) => {

	const { text, zumiName, showOverlay } = useContext(DefaultContext);
	const { tryingToConnectNetwork } = useContext(NetworkContext);
	const { connected } = useContext(SocketContext);

  return (
    <div className='lost-connection' style={{display: connected || !showOverlay ? 'none': ''}}>
			<div className='content'>
				<LoadingScreen />
				<p className='label'>
					{text.lost_connection_modal_msg? text.lost_connection_modal_msg: "You might have lost connection with"}
						&nbsp;"{zumiName? zumiName:"Zumi"}"
				</p>
				{tryingToConnectNetwork && (
					<p className='label-2'>
						This happens sometimes when connecting to a new network.<br/>
						Check your device’s WiFi list again to make sure you’re connected to “{zumiName? zumiName:"Zumi"}”.
					</p>
				)}
			</div>
    </div>
  );
}

export default LostConnection;