import React, { useState, useEffect, useContext } from 'react';
import { useHistory } from 'react-router-dom';

import Plotly from 'plotly.js-basic-dist';
import createPlotlyComponent from 'react-plotly.js/factory';

import LoadingScreen from '../LoadingScreen/LoadingScreen';
import Button from '../lib/Button';

import { DefaultContext } from '../../contexts/DefaultContext';
import { SocketContext } from '../../contexts/SocketContext';

import '../../styles/LinearRegression.scss';

import coverImg from '../../assets/regression/regression_cover.svg';
import checkIcon from '../../assets/check.svg';
import rulerImg from '../../assets/regression/lineup.svg';
import rulerImg2 from '../../assets/regression/topdown_lineup.svg';
import tableImg from '../../assets/regression/graph.svg';
import steeringWheel from '../../assets/steeringwheel.svg';
import forwardImg from '../../assets/regression/forward.svg';
import zumiHappyFace from '../../assets/zumiface_happy.svg';

const Plot = createPlotlyComponent(Plotly);
const plotDataX = [0.5, 0.6, 0.7, 0.8, 0.9, 1.0, 1.1, 1.2, 1.3, 1.4, 1.5, 1.6, 1.7, 1.8, 1.9, 2.0];

const LinearRegression = (props) => {
  let history = useHistory();

  const { text, language } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);

  const [page, setPage] = useState(0);
  const [navbarCircles, setNavbarCircles] = useState(['', '', '']);
  const [plotDataY, setPlotDataY] = useState(new Array(16).fill(0));
  const [isCm, setIsCm] = useState(false);
  const [showTooltip, setShowToolTip] = useState(false);
  const [isTraining, setIsTraining] = useState(false);
  const [slope, setSlope] = useState(0);
  const [intercept, setIntercept] = useState(0);
  const [testPlotY, setTestPlotY] = useState([0.5, 2]);
  const [tryoutData, setTryoutData] = useState(0);

  useEffect(() => {
    document.body.style = 'background-color: #f4f1ff';

    if (language.indexOf('en') !== -1) setIsCm(true);

    return ( () => {
      document.body.style = 'background-color: #ccf5f1';
    })
  }, []);

  const downloadPDF = () => {
    let pdfUrl = window.location.protocol + "//" + window.location.hostname+"/Ruler.pdf";
    window.open(pdfUrl, "_blank");
  }

  const drive = (seconds) => {
    socket.emit('drive_regression', seconds);
  }

  const updateData = (e) => {
    let index = plotDataX.indexOf(parseFloat(e.target.name));
    let newPlotDataY = plotDataY.concat();
    let value = e.target.value ? e.target.value : 0;
    if (value >= 1) value = value.replace(/(^0+)/, "");
    newPlotDataY[index] = value;
    setPlotDataY(newPlotDataY);
  }

  const recalibrate = () => {
    socket.emit('recalibrate');
  }

  const train = () => {
    setPage(5);
    setIsTraining(true);
    setNavbarCircles(['done', 'done', 'active']);
    calculate();

    setTimeout(() => {
      setIsTraining(false);
    }, 3000);

    setTimeout(() => {
      setPage(6);
      setNavbarCircles(['done', 'done', 'done']);
    }, 6000);
  }

  const calculate = () => {
    let y = [...plotDataY];
    let x = [...plotDataX];
    let lr = {};
    let n = y.length;
    let [sum_x, sum_y, sum_xy, sum_xx, sum_yy] = [0, 0, 0, 0, 0];

    for (var i = 0; i < y.length; i++) {
        sum_x += x[i];
        sum_y += parseFloat(y[i]);
        sum_xy += (x[i]*parseFloat(y[i]));
        sum_xx += (x[i]*x[i]);
        sum_yy += (parseFloat(y[i])*parseFloat(y[i]));
    }

    lr['slope'] = (n * sum_xy - sum_x * sum_y) / (n*sum_xx - sum_x * sum_x);
    lr['intercept'] = (sum_y - lr.slope * sum_x)/n;
    lr['r2'] = Math.pow((n*sum_xy - sum_x*sum_y)/Math.sqrt((n*sum_xx-sum_x*sum_x)*(n*sum_yy-sum_y*sum_y)),2);

    setSlope(lr['slope']);
    setIntercept(lr['intercept']);
    setTestPlotY([0.5 * lr['slope'] + lr['intercept'], 2 * lr['slope'] + lr['intercept']]);
  }

  const updateTryOutData = (e) => {
    let value = e.target.value ? e.target.value : 0;
    if (value >= 1) value = value.replace(/(^0+)/, "");
    setTryoutData(value);
  }

  const move = () => {
    const seconds = (tryoutData - intercept) / slope;
    socket.emit("drive_regression", seconds);
  }

  const goToLesson = () => {
    if (language.includes("ko")) {
      let jupyterLesson =
        window.location.protocol +
        "//" +
        window.location.hostname +
        ":5555/notebooks/Zumi_Content_ko/Lesson/Chapter Demo-02 거리 주행 배우기.ipynb";
      window.open(jupyterLesson, "_blank");
    } else {
      let jupyterLesson =
        window.location.protocol +
        "//" +
        window.location.hostname +
        ":5555/notebooks/Zumi_Content_en/Lesson/6.2 Regression and Calculating Distance.ipynb";
      window.open(jupyterLesson, "_blank");
    }
  }

  const recalibrateDiv = (
    <div className="recalibrate">
      <div className="tri_tooltip" style={{display: showTooltip ? "" : "none"}}>
        <div className="tri"></div>
        <div className="content">
          {text.demo_regression_recalibrate_explaination}
        </div>
      </div>
      <Button
        onClick={recalibrate}
        onMouseOver={() => setShowToolTip(true)}
        onMouseLeave={() => setShowToolTip(false)}
      >
        {text.demo_regression_drive_btn_recalibrate}
      </Button>
    </div>
  );

  const measureDiv = (
    <div className="switch-unit">
      <span className="in">in</span>
      <label className="toggle-switch">
        <input type="checkbox" checked={isCm} onChange={ () => setIsCm(!isCm)}/>
        <span className="toggle-switch-slider"></span>
      </label>
      <span className="cm">cm</span>
    </div>
  );

  return (
    <div className={`Demo LinearRegression ${language}`}>
      { page === 0 && (
        <Button className='close-btn' onClick={() => history.push('/explore')}>
          <p>{text.demo_btn_close}</p>
        </Button>
      )}
      { page === 0 && (
        <div className='page0 container'>
          <div className='title'>{text.demo_regression_intro_header}</div>
          <div className='row'>
            <div className='col-6 description'>
              {text.demo_regression_intro_body && (
                text.demo_regression_intro_body.split("<i>").map((item,i) => {
                  if(i === 1) {
                    let txt = item.split("</i>")[0];
                    let tmp = item.split("</i>")[1].split("<b>").map((item2, j) => {
                      if(j === 1) {
                        let temp = item2.split("</b>");
                        return <span key={j+2}><b>{temp[0]}</b>{temp[1]}</span>
                      } else {
                        return <span key={j+2}>{item2}</span>
                      }
                    })
                    return <span key={i}><i>{txt}</i>{tmp}</span>
                  } else {
                    return <span key={i}>{item}</span>
                  }
                })
              )}
            </div>
            <div className='col-6 cover'>
              <img alt="cover" src={coverImg}/>
            </div>
          </div>
          <Button onClick={() => {
            setPage(1);
            setNavbarCircles(['active', '', '']);
          }}>{text.demo_btn_play}</Button>
        </div>
      )}

      { page !== 0 && (
        <div className="nav row">
          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[0]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            
            <div className="nav-txt">{text.demo_regression_navbar_setup}</div>
          </div>

          <div className="arrow col">
            <div className="line"></div>
            <div className="triangle"></div>
          </div>

          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[1]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="nav-txt">{text.demo_regression_navbar_measure}</div>
          </div>

          <div className="arrow col">
            <div className="line"></div>
            <div className="triangle"></div>
          </div>

          <div className="current-page col">
            <span className={["circle"].concat(navbarCircles[2]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="nav-txt">{text.demo_regression_navbar_calculate}</div>
          </div>
        </div>
      )}

      { page === 1 && (
        <div className='page1 container'>
          <div className='title'>{text.demo_regression_get_ruler_header}</div>
          <div className='description'>
            {text.demo_regression_get_ruler_body && (
              text.demo_regression_get_ruler_body.split('\\n').map((item, i) => {
                return (<p key={i}> {item} </p>);
              })
            )}
          </div>
          <div><img alt="ruler" src={rulerImg} /></div>
          <Button className='download' onClick={downloadPDF}>{text.demo_regression_btn_download}</Button>
          <div className='btns'>
            <Button className='back' onClick={() => setPage(0)}><p>{text.btn_back}</p></Button>
            <Button className='next' onClick={() => setPage(2)}><p>{text.btn_next}</p></Button>
          </div>
        </div>
      )}

      { page === 2 && (
        <div className='page2 container'>
          <div className="row">
            <div className="col-4">
              <img className="ruler-img" alt="ruler" src={rulerImg2} />
            </div>
            <div className="col-8">
              <div className="title">{text.demo_regression_line_up_header}</div>
              <div className="description">
                {text.demo_regression_line_up_body && (
                  text.demo_regression_line_up_body.split("<b>").map((item,i) => {
                    if(i === 1) {
                      let temp = item.split("</b>");
                      return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                    } else {
                      return <span key={i}>{item}</span>
                    }
                  })
                )}
              </div>
              <div><img className="graph-img" alt="graph" src={tableImg} /></div>
            </div>
          </div>
          <div className="btns">
            <Button className="back" onClick={() => setPage(1)}>
              <p>{text.btn_back}</p>
            </Button>
            <Button className="next" onClick={() => {
              setPage(3);
              setNavbarCircles(['done', 'active', '']);
            }}>
              <p>{text.btn_next}</p>
            </Button>
          </div>
        </div>
      )}

      { page === 3 && (
        <div className='page3 container'>
          <div className="title">{text.demo_regression_how_far_header}</div>
          <div className="description">
            <p>
              {text.demo_regression_how_far_body && (
                text.demo_regression_how_far_body.split("<b>").map((item,i) => {
                  if(i === 1) {
                    let temp = item.split("</b>");

                    return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                  } else {
                    return <span key={i}>{item}</span>
                  }
                })
              )}
            </p>
            <Button className="drive">
              <img alt="drive" src={steeringWheel} />
              <p>{text.demo_regression_how_far_btn_drive}</p>
            </Button>
            <p>
              {text.demo_regression_how_far_body2 && (
                text.demo_regression_how_far_body2.split("<b>").map((item,i) => {
                  if(i === 1) {
                    let temp = item.split("</b>");

                    return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                  } else {
                    return <span key={i}>{item}</span>
                  }
                })
              )}
            </p>
            <p>{text.demo_regression_how_far_body3}</p>
          </div>
          <div><img alt="forard" src={forwardImg} /></div>
          <div className="row">
            <div className="col-1"></div>
            <div className="col-3">
              <Button className="drive" onClick={() => drive(0.5)}>
                <img alt="drive" src={steeringWheel} />
                <p>{text.demo_regression_how_far_btn_drive}</p>
              </Button>
            </div>
            <div className="col-7">
              <table>
                <thead>
                  <tr>
                    <th>{text.demo_regression_how_far_duration}</th>
                    <th>{text.demo_regression_how_far_distance}</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>0.5 {text.demo_regression_how_far_seconds}</td>
                    <td>
                      <input type="number" onChange={updateData} name={plotDataX[0]} value={plotDataY[plotDataX.indexOf(0.5)]} />
                      <p>{isCm ? "cm": "inches"}</p>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
            <div className="col-1"></div>
          </div>
          <div className="btns">
            <Button className="back" onClick={() => {
              setPage(2);
              setNavbarCircles(['active', '', '']);
            }}>
              <p>{text.btn_back}</p>
            </Button>
            { recalibrateDiv }
            { measureDiv }
            <Button className="next" onClick={() => setPage(4)}>
              <p>{text.btn_next}</p>
            </Button>
          </div>
        </div>
      )}

      { page === 4 && (
        <div className="page4 container">
          <div className="row">
            <div className="col-5">
              <table>
                <thead>
                  <tr>
                    <th></th>
                    <th>{text.demo_regression_how_far_duration}</th>
                    <th>{text.demo_regression_how_far_distance}</th>
                  </tr>
                </thead>
                <tbody>
                  {plotDataX.map((x,i) => (
                    <tr key={x}>
                      <th>
                        <div className="drive-circle" onClick={() => this.drive(x)}>
                          <img src={steeringWheel} alt="drive"/>
                        </div>
                      </th>
                      <th>{x} {text.demo_regression_how_far_seconds_short}</th>
                      <th>
                        <input type="number" onChange={updateData} name={x} value={plotDataY[i]} />
                        <p>{isCm ? "cm": "in"}</p>
                      </th>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="col-7">
              <div className="title">{text.demo_regression_drive_header}</div>
              <div className="description">
              <div>{text.demo_regression_drive_body}</div>
              <div>
                  <span className="msg-1">{text.demo_regression_drive_body2_1}</span>
                  <div className="drive-circle">
                    <img src={steeringWheel} alt="drive"/>
                  </div>
                  <span className="msg-2">{text.demo_regression_drive_body2_2}</span>
              </div>
              </div>
              <Plot
                data={[
                  {
                    x: plotDataX,
                    y: plotDataY,
                    mode:  'markers',
                    type: 'scatter'
                  }
                ]}
                layout={{
                  width: 385, 
                  height: 205,
                  margin: {
                    l: 20,
                    r: 15,
                    b: 15,
                    t: 15,
                    pad: 0
                  }
                }}
              />
              <img className="forward-img" src={forwardImg} alt="forward" />
            </div>
          </div>
          <div className="btns">
              <Button className="back" onClick={() => setPage(3)}>
                <p>{text.btn_back}</p>
              </Button>
              { recalibrateDiv }
              { measureDiv }
              <Button
                className={plotDataY.indexOf(0) === -1 ? "calculate" : "calculate deactive"}
                onClick={plotDataY.indexOf(0) === -1 ? train : null}
              >
                {text.demo_regression_navbar_calculate}
              </Button>
            </div>
        </div>
      )}

      { page === 5 && (
        <div className="page5 container">
          {isTraining && (
            <div className="training">
              <div className="title">{text.demo_regression_calculating}</div>
              <LoadingScreen />
            </div>
          )}
          {!isTraining && (
            <div className="done">
              <div className="title">{text.demo_regression_done_header}</div>
              <img alt="happy-face" src={zumiHappyFace}/>
              <p>{text.demo_regression_done_body}</p>
            </div>
          )}
        </div>
      )}

      { page === 6 && (
        <div className="page6 container">
          <div className="title">{text.demo_regression_test_header}</div>
          <div className="description">
            {text.demo_regression_test_body && (
              text.demo_regression_test_body.split("<b>").map((item,i) => {
                if(i === 1 || i === 2) {
                  let temp = item.split("</b>");
                  return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}&nbsp;
            “{text.demo_regression_test_body_2} 6.5 {isCm ? "centimeters": "inches"}”.
          </div>
          <div className="row">
            <div className="col-8">
              <Plot
                data={[
                  {
                    x: plotDataX,
                    y: plotDataY,
                    mode:  'markers',
                    type: 'scatter',
                    hovertext: ''
                  },
                  {
                    x: [0.5, 2],
                    y: testPlotY,
                    mode: 'lines',
                    type: 'scatter',
                    hovertext: ''
                  }
                ]}
                layout={{
                  width: 385, 
                  height: 205,
                  margin: {
                    l: 20,
                    r: 0,
                    b: 15,
                    t: 15,
                    pad: 0,
                    autoexpand: false
                  }
                }}
              />
              <div className="try-out-drive">
                <span>{text.demo_regression_test_try_out}</span>
                <input type="number" onChange={updateTryOutData} name="tryOutData" value={tryoutData} />
                <span>{isCm ? "centimeters": "inches"} </span>
                <Button className="drive" onClick={move}>
                  <img alt="drive" src={steeringWheel} />
                  <p>{text.demo_regression_how_far_btn_drive}</p>
                </Button>
              </div>
            </div>
            <div className="col-4">
              <p>{text.demo_regression_test_slope}</p>
              <div className="value">{slope}</div>
              <p>{text.demo_regression_test_intercept}</p>
              <div className="value">{intercept}</div>
            </div>
          </div>
          <div className="btns">
            <Button className="back" onClick={() => {
              setPage(4);
              setNavbarCircles(['done', 'active', '']);
            }}>
              <p>{text.btn_back}</p>
            </Button>
            <Button onClick={goToLesson}>{text.demo_regression_test_btn_lets_use_it}</Button>
            <Button onClick={() => history.push('/explore')}>{text.demo_btn_close}</Button>
          </div>
        </div>
      )}
    </div>
  )
}

export default LinearRegression;

