import React, { useState, useContext, useEffect } from 'react';
import '../styles/Update.scss';
import Modal from "react-bootstrap/Modal";
import Button from './lib/Button';
import LoadingScreen from './LoadingScreen/LoadingScreen';

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';
import { SocketContext } from '../contexts/SocketContext';
import { UpdateContext } from '../contexts/UpdateContext';

import ZumiFaceSad from '../assets/zumiface_sad.svg';
import ZumiFaceHappy from '../assets/zumiface_happy.svg';


let counterInterval = null;
let c = 5;

const Update = () => {
  const { text, currentUser } = useContext(DefaultContext); 
  const { canUpdateDashboard, canUpdateContent, latestDashboardVersion, setCanUpdateDashboard, setCanUpdateContent, 
    showUpdate, setShowUpdate, fromSwitchingLanguage, setFromSwitchingLanguage, updating, setUpdating } = useContext(NetworkContext);
  const { socket } = useContext(SocketContext); 
  const { updateContent, checkContentMissing } = useContext(UpdateContext);

  const [showSecondUpdateMsg, setShowSecondUpdateMsg] = useState(false);

  const [counter, setCounter] = useState(5);
  const [waitScreen, setWaitScreen] = useState(false);
  const [failed, setFailed] = useState(false);

  const updateDashboard = () => {
    socket.off("disconnect");
    counterInterval = setInterval(() => {
      if (c < 1) {
        clearInterval(counterInterval);
        setWaitScreen(true);
        return;
      }
      c -= 1;
      setCounter(c);
    }, 1000);
    setUpdating(true);

    setTimeout(() => {
      setShowSecondUpdateMsg(true);
    }, 8000);

    setTimeout(() => {
      sessionStorage.clear();
      if (canUpdateContent) {
        socket.emit("update_everything");
        console.log('update everything');
      } else {
        socket.emit("update_firmware");
        console.log('update dashboard');
      }
    }, 10000);
  }
  
  const close = () => {
    socket.emit("update_false");
    setShowUpdate(false);
    if (canUpdateContent !== "No_content") checkContentMissing();
  }

  const skipDownloadingContent = () => {
    socket.emit("update_false");
    setShowUpdate(false);
  }

  const openDashboard = () => {
    let dashboardUrl =
      window.location.protocol +
      "//" +
      window.location.hostname;
    window.location.replace(dashboardUrl);
  }

  const tryAgain = () => {
    setUpdating(false);
    setFailed(false);
  }
  
  return (
    <Modal className='Update' show={showUpdate} onHide={updating? null : close}>
      { updating && (
        <Modal.Header></Modal.Header>
      )}
      { !updating && (
        <Modal.Header closeButton onClick={close}></Modal.Header>
      )}
      <Modal.Body>
      {!updating && !failed && (canUpdateDashboard || canUpdateContent) && (
        <div>
          { !canUpdateDashboard && canUpdateContent === "No_content" ? (
            <img alt="sad Zumi" src={ZumiFaceSad} className="zumi-face"/>
          ) : (
            <LoadingScreen />
          )}

          { canUpdateDashboard
            && (<p className="msg-1">
                {text.can_update_version} v
                <span>{latestDashboardVersion}</span>
              </p>)
          }
          {!canUpdateDashboard && canUpdateContent === true && (
            <p className="msg-1">
              {text.can_update_content}
            </p>
          )}
          {!canUpdateDashboard && canUpdateContent === "No_content" && (
            <p className="msg-1">{ text.missing_content_header }</p>
          )}

          { canUpdateDashboard
            && (<p className="msg-2">
                {text.can_update_msg}
              </p>)
          }
          {!canUpdateDashboard && canUpdateContent === true && (
            <p className="msg-2">
              {text.can_update_msg}
            </p>
          )}
          {!canUpdateDashboard && canUpdateContent === "No_content" && (
            <p className="msg-2">{ text.missing_content_msg }</p>
          )}
          
          <Button onClick={canUpdateDashboard? updateDashboard: updateContent}>
            {canUpdateDashboard && text.can_update_btn_update_zumi}
            {!canUpdateDashboard && canUpdateContent === "No_content" && text.btn_download_content}
            {!canUpdateDashboard && canUpdateContent === true && text.can_update_btn_update_content}
          </Button>

          { canUpdateDashboard && (
            <div>
              <div className="skip" onClick={close}>
                {text.can_update_link_skip}
              </div>
            </div>
          )}
          {!canUpdateDashboard && canUpdateContent === true && (
            <div>
              <div className="skip" onClick={close}>
                {text.can_update_link_skip}
              </div>
            </div>
          )}
          {!canUpdateDashboard && canUpdateContent === "No_content" && (
            <div>
              <div className="skip" onClick={skipDownloadingContent}>
                {text.link_skip_download_content}
              </div>
            </div>
          )}
        </div>
      )}

      {!updating && !failed && !canUpdateDashboard && (canUpdateContent === false) && (
        <div>
          <img src={ZumiFaceHappy} alt="happy zumi" className='zumi-face' />
          <div className="msg-1">I’m already up-to-date</div>
        </div>
      )}

      {updating && (
        <div>
          <LoadingScreen />
          {canUpdateDashboard && !waitScreen && (
            <div>
              <div className="msg-1">
                {text.reboot_for_update_msg && (
                  text.reboot_for_update_msg.split('\\n').map((item, i) => {
                    return (<p key={i}> {item} </p>);
                  })
                )}
                <b>{counter}</b>
              </div>
            </div>
          )}
          {canUpdateDashboard && waitScreen && (
            <div className="msg-1">
              <p>{text.can_update_wait_msg}</p>
              {showSecondUpdateMsg && (
                <div>
                  <p>{text.can_update_wait_msg2}</p>
                  <Button onClick={openDashboard}>{text.can_update_wait_btn}</Button>
                </div>
              )}
            </div>
          )}
          {!canUpdateDashboard && canUpdateContent === true && (
            <p className="msg-1">{text.can_update_updating_content_msg}</p>
          )}
          {!canUpdateDashboard && canUpdateContent === "No_content" && (
            <p className="msg-1">
              { fromSwitchingLanguage ? text.can_download_content_msg2: text.can_download_content_msg}
            </p>
          )}
        </div>
      )}

      {failed && (
        <div>
          <img src={ZumiFaceSad} alt="sad Zumi" className='zumi-face'/>
          <p className="msg-1">
            {text.can_update_fail_msg}
          </p>
          <Button onClick={tryAgain}>
            {text.network_failed_btn_try_again}
          </Button>
        </div>
      )}
        
      </Modal.Body>
    </Modal>
  )
}

export default Update;