import React, { useState, useEffect, useContext } from 'react';

import { DefaultContext } from '../contexts/DefaultContext';
import { SocketContext } from '../contexts/SocketContext';
import { PiCameraContext } from '../contexts/PiCameraContext';

import LoadingScreen from './LoadingScreen/LoadingScreen';

import '../styles/PiCamera.scss';

import ZumiXXEyes from '../assets/zumiface_xx_eyes.svg';
import ZumiClosedEyes from '../assets/zumiface_closed_eyes.svg';

let checkCameraConnectionInterval = null;
let checkRunningInterval = null;

const PiCamera = ({ className }) => {
  if (className) {
    className = `PiCamera ${className}`
  } else {
    className = 'PiCamera'
  }
  const { text } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);
  const { url, runningDemo, connected, trying, running, setConnected, setTrying, setRunning } = useContext(PiCameraContext);

  return (
    <div className={className}>
      {!connected && (
        <div className='disconnected'>
          <div>
            <img src={ZumiXXEyes} alt='x_x' />
            <div>
              {text.zumi_cam_disconnected && text.zumi_cam_disconnected.split('\\n').map((item, i) => {
                return <p key={i}>{item}</p>;
              })}
            </div>
          </div>
        </div>
      )}
      {connected && !running && trying && (
        <div className='loading'>
          <div>
            <LoadingScreen />
            <p>{text.zumi_cam_loading}</p>
          </div>
        </div>
      )}
      {connected && running && !trying && (
        <img src={url} alt='pi-camera' className='pi-streaming' id='pi-streaming' />
      )}
      {connected && !running && !trying && (
        <div className='closed'>
          <div>
            <img src={ZumiClosedEyes} alt='closed' />
            <p>{text.zumi_cam_turned_off}</p>
          </div>
        </div>
      )}
    </div>
  )
}

export default PiCamera;