import React, { createContext, useState, useContext } from 'react';
import socketIOClient from "socket.io-client";

import { SocketContext } from './SocketContext';

export const PiCameraContext = createContext();

let checkCameraConnectionInterval;
let checkRunningInterval;

const PiCameraContextProvider = (props) => {

  const { socket } = useContext(SocketContext);

  // let socketUrl = `${window.location.protocol}//192.168.219.100:3456`
  let socketUrl = `${window.location.protocol}//${window.location.hostname}:3456`;
  const [url, setUrl] = useState(socketUrl + '/video_feed');
  const [streamingSocket, setStreamingSocket] = useState(null);
  const [runningDemo, setRunningDemo] = useState(false);
  const [connected, setConnected] = useState(true);
  const [trying, setTrying] = useState(true);
  const [running, setRunning] = useState(false);

  const openStreamingSocket = () => {
    setStreamingSocket(socketIOClient(socketUrl));
  }

  const closeStreamingSocket = () => {
    try {
      streamingSocket.close();
      setStreamingSocket(null);
    } catch (e) {
      return;
    }    
  }

  const checkCameraConnection = () => {
    setTrying(true);
    setRunning(false);
    socket.emit('check_camera_connection');
    checkCameraConnectionInterval = setInterval(() => {
      socket.emit('check_camera_connection');
    }, 15000);
    socket.on('check_camera_connection', onCheckCameraConnection);
  }

  const onCheckCameraConnection = (data) => {
    clearInterval(checkCameraConnectionInterval);
    socket.removeAllListeners('check_camera_connection');
    if(data) {
      openStreamingServer(); 
    }
    setConnected(data);
  }

  const openStreamingServer = () => {
    socket.emit('open_pi_streaming');
    socket.emit('check_streaming_server');
    checkRunningInterval = setInterval(() => {
      socket.emit('check_streaming_server');
    }, 5000);
    socket.on('check_streaming_server', onCheckStreamingServer);
    setTrying(true);
  }

  const onCheckStreamingServer = (data) => {
    if(data) {
      clearInterval(checkRunningInterval);
      socket.removeAllListeners('check_streaming_server');
      if(window.location.pathname === '/drive-mode') openStreamingSocket();
      setTimeout(() => {
        setRunning(true);
        setTrying(false);
      }, 5000);
    }
  }

  const closePiStreaming = () => {
    socket.emit("camera_stop");
    socket.removeAllListeners('check_camera_connection');
    socket.removeAllListeners('check_streaming_server');
    clearInterval(checkCameraConnectionInterval);
    clearInterval(checkRunningInterval);
    setTrying(false);
    setRunning(false);
  }


  return (
    <PiCameraContext.Provider value={{ streamingSocket, setStreamingSocket, connected, setConnected, url, 
      trying, setTrying, running, setRunning, runningDemo, setRunningDemo, checkCameraConnection, closePiStreaming, closeStreamingSocket }}>
      {props.children}
    </PiCameraContext.Provider>
  )
}

export default PiCameraContextProvider;