import React, { useState, useEffect, useContext } from 'react';
import { useLocation } from 'react-router-dom';
import socketIOClient from "socket.io-client";

import * as tf from '@tensorflow/tfjs';
import * as tfd from '@tensorflow/tfjs-data';
import Dropdown from 'react-bootstrap/Dropdown';

import { ControllerDataset } from './ControllerDataset';
import Canvas from './Canvas';
import LoadingScreen from '../../LoadingScreen/LoadingScreen';
import Button from '../../lib/Button';
import PiCamera from '../../PiCamera';

import { DefaultContext } from '../../../contexts/DefaultContext';
import { PiCameraContext } from '../../../contexts/PiCameraContext';

import '../../../styles/Gesture.scss';

import gestureIllustration from "../../../assets/gesture/gesture_illustration.svg";
import zumiImg from "../../../assets/gesture/top_rendering_360.png";
import nextButton from "../../../assets/back_button.svg";
import happyFace from "../../../assets/zumiface_happy.svg";
import cameraIcon from "../../../assets/camera_icon.svg";
import checkIcon from "../../../assets/check.svg";
import xxEyes from "../../../assets/zumiface_xx_eyes.svg";
import closedEyes from "../../../assets/zumiface_closed_eyes.svg";
import closeIcon from "../../../assets/close.svg";
import stopExampleImg from "../../../assets/gesture_stop.svg";
import infoIcon from "../../../assets/info.svg";

const CONTROLS = ['forward', 'stop', 'left', 'right'];
const NUM_CLASSES = 4;

let isPredicting = false;
let photoInt;
let socket;
let checkCameraConnectionInterval;
let checkRunningInterval;
let _isDriving = false;
let currentClassId = -1

const useQuery = () => {
  return new URLSearchParams(useLocation().search);
}

const Gesture = (props) => {
  let id = 0;
  let query = useQuery();

  const { text, setLanguage } = useContext(DefaultContext);

  const { setConnected, setTrying, setRunning } = useContext(PiCameraContext);

  const [webcam, setWebcam] = useState('no webcam yet');
  const [truncatedMobileNet, setTruncatedMobileNet] = useState(null);
  const [controllerDataset, setControllerDataset] = useState(null);
  // const [model, setModel] = useState(null);
  const [loadedModel, setLoadedModel] = useState(false);
  const [paramValue, setParamValue] = useState([1, 2, 1, 1]);
  const [learningRate, setLearningRate] = useState(0.0001);
  const [batchSizeFraction, setBatchSizeFraction] = useState(0.4);
  const [epochs, setEpochs] = useState(20);
  const [hiddenUnits, setHiddenUnits] = useState(100);
  const [trainStatus, setTrainStatus] = useState('');
  const [trainingTimeout, setTrainingTimeout] = useState(null);
  const [label, setLabel] = useState('');
  const [confidence, setConfidence] = useState('');
  const [needToReload, setNeedToReload] = useState(false);
  const [dataName, setDataName] = useState(''); 
  const [canvasList, setCanvasList] = useState([]);
  const [navbarCircles, setNavbarCircles] = useState(['', '', '', '']);
  const [collectPageInfo, setCollectPageInfo] = useState({name: '', emoji: ''});
  const [isDriving, setIsDriving] = useState(false);
  // const [isPredicting, setIsPredicting] = useState(false);
  const [isEnoughData, setIsEnoughData] = useState(false);
  const [isRunningTestWebcam, setIsRunningTestWebcam] = useState(false);
  const [activateNextButton, setActivateNextButton] = useState(false);
  const [showIntroPage, setShowIntroPage] = useState(true);
  const [showCollectPage, setShowCollectPage] = useState(false);
  const [showCollectStop, setShowCollectStop] = useState(false);
  const [showDataPage, setShowDataPage] = useState(false);
  const [showParamPage, setShowParamPage] = useState(false);
  const [showTrainingPage, setShowTrainingPage] = useState(false);
  const [showTestPage, setShowTestPage] = useState(false);
  const [showLRInfo, setShowLRInfo] = useState(false);
  const [showBSInfo, setShowBSInfo] = useState(false);
  const [showEpochsInfo, setShowEpochsInfo] = useState(false);
  const [showHUInfo, setShowHUInfo] = useState(false);
  const [random, setRandom] = useState(0);

  // let isPredicting = false;
  let model = null;

  const filterCanvasList = canvasList.filter(item => item.label === dataName);
  const displayCanvasList = filterCanvasList.reverse().map(item => 
    (<Canvas key={id++} imgSrc={item.imgSrc} />)
  );

  /* componentDidMount and componentWillUnmount*/
  useEffect(() => {
    let language = query.get('language');
    if(!language) {
      language = 'en';
    }
    setLanguage(language);
    socket = socketIOClient(`${window.location.protocol}//${window.location.hostname}:8443`);
    // socket = socketIOClient(`https://192.168.219.100:8443`);
    document.body.style = 'background-color: #f4f1ff';
    setControllerDataset(new ControllerDataset(NUM_CLASSES));

    return ( () => {
      document.body.style = 'background-color: #ccf5f1';
      socket.emit("zumi_stop");
      // setIsPredicting(false);
      isPredicting = false;
      closePiStreaming();
      socket = null;
    })
  }, [])

  /* Check if there's enough image data */
  useEffect(() => {
    checkEnoughData();
    checkEnoughStopData();
  }, [canvasList]);

  const checkCameraConnection = () => {
    setTrying(true);
    setRunning(false);
    socket.emit('check_camera_connection');
    checkCameraConnectionInterval = setInterval(() => {
      socket.emit('check_camera_connection');
    }, 15000);
    socket.on('check_camera_connection', onCheckCameraConnection);
  }

  const onCheckCameraConnection = (data) => {
    clearInterval(checkCameraConnectionInterval);
    socket.removeAllListeners('check_camera_connection');
    if(data) {
      openStreamingServer(); 
    }
    setConnected(data);
  }

  const openStreamingServer = () => {
    socket.emit('open_pi_streaming');
    socket.emit('check_streaming_server');
    checkRunningInterval = setInterval(() => {
      socket.emit('check_streaming_server');
    }, 5000);
    socket.on('check_streaming_server', onCheckStreamingServer);
    setTrying(true);
  }

  const onCheckStreamingServer = (data) => {
    if(data) {
      clearInterval(checkRunningInterval);
      socket.removeAllListeners('check_streaming_server');
      setTimeout(() => {
        setRunning(true);
        setTrying(false);
      }, 5000);
    }
  }

  const closePiStreaming = () => {
    socket.emit("camera_stop");
    socket.removeAllListeners('check_camera_connection');
    socket.removeAllListeners('check_streaming_server');
    clearInterval(checkCameraConnectionInterval);
    clearInterval(checkRunningInterval);
    setTrying(false);
    setRunning(false);
  }

  const takePhoto = async () => {
    const currentLabel = CONTROLS.indexOf(dataName);
    let img = await getImage();
    controllerDataset.addExample(truncatedMobileNet.predict(img), currentLabel);
    addCanvasList(img);
    if (dataName !== '' && dataName !== 'stop') {
      drawThumb(img, currentLabel);
    }
    await tf.nextFrame();
  }

  const takePhotoHandler = () => {
    photoInt = setInterval(takePhoto, 50);
  }

  const getImage = async () => {
    try {
      let currentWebcam = webcam;
      let img = await currentWebcam.capture();
      let processedImg = tf.tidy(() => img.expandDims(0).toFloat().div(127).sub(1));
      img.dispose();
      return processedImg;
    } catch(e) {
      console.log(e);
    }
  }

  const addCanvasList = (img) => {
    let newData = { imgSrc: img, label: dataName };
    setCanvasList(prevCanvasList => prevCanvasList.concat({ ...newData }));
  }

  const predict = async() => {
    while (isPredicting) {
      let img = await getImage();
      let embeddings = truncatedMobileNet.predict(img);
      let predictions = model.predict(embeddings);
      const predictedClass = predictions.as1D().argMax();
      const classId = (await predictedClass.data())[0];
      let currentConfidence = (predictions.dataSync()[classId] * 100).toFixed(2);
      setConfidence(currentConfidence);
      if (currentClassId !== classId && _isDriving) {
        socket.emit("zumi_stop");
        socket.emit("gesture_move", classId);
      }
      currentClassId = classId;
      img.dispose();
      setupPredictLabel(classId);
    }
  }

  const checkEnoughData = () => {
    let [forward_num, left_num, right_num] = [0, 0, 0];
    for (let i = 0; i < canvasList.length; i++) {
      if (canvasList[i].label === 'forward') {
        forward_num += 1;
      } else if (canvasList[i].label === 'left') {
        left_num += 1;
      } else if (canvasList[i].label === 'right') {
        right_num += 1;
      }
    }

    if (forward_num !== 0 && left_num !== 0 && right_num !== 0) {
      setActivateNextButton(true);
    }
  }

  const checkEnoughStopData = () => {
    let stop_num = 0;
    for (let i = 0; i < canvasList.length; i++) {
      if (canvasList[i].label === 'stop') {
        stop_num +=1 ;
      }
    }

    if (stop_num >= 10) {
      setIsEnoughData(true);
    }
  }

  const draw = async(image, canvas) => {
    let [width, height] = [224, 224];
    let ctx = canvas.getContext('2d');
    let imageData = new ImageData(width, height);
    let data = image.dataSync();

    for (let i = 0; i < height * width; i++) {
      let j = i * 4;
      imageData.data[j + 0] = (data[i * 3 + 0] + 1) * 127;
      imageData.data[j + 1] = (data[i * 3 + 1] + 1) * 127;
      imageData.data[j + 2] = (data[i * 3 + 2] + 1) * 127;
      imageData.data[j + 3] = 255;
    }
    await ctx.putImageData(imageData, 0, 0);
  }

  const drawThumb = (img, label) => {
    let thumbCanvas = document.getElementById(CONTROLS[label] + '-thumb');
    draw(img, thumbCanvas);
  }

  const clearCanvas = async (canvas) => {
    let ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, 224, 224);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
    await ctx.fillRect(0, 0, 224, 224);
  }

  const drawCanvasOutline = () => {
    let upThumbCanvas = document.getElementById('forward-thumb');
    let leftThumbCanvas = document.getElementById('left-thumb');
    let rightThumbCanvas = document.getElementById('right-thumb');
    clearCanvas(upThumbCanvas);
    clearCanvas(leftThumbCanvas);
    clearCanvas(rightThumbCanvas);
  }

  const loadTruncatedMobileNet = async () => {
    let mobilenet = await tf.loadLayersModel(window.location.protocol + "//" + window.location.hostname + ":8443/models/model.json");
    // let mobilenet = await tf.loadLayersModel(window.location.protocol + "//" + window.location.hostname + ":3000/models/model.json");
    let layer = mobilenet.getLayer('conv_pw_13_relu');
    setLoadedModel(true);
    return tf.model({inputs: mobilenet.inputs, outputs: layer.output});
  }

  const webcamInit = async () => {
    let currentWebcam;
    try {
      currentWebcam = await tfd.webcam(document.getElementById('webcam'));
      setWebcam(currentWebcam);
    } catch (e) {
      console.log(e);
    }

    let currentTruncatedMobileNet = await loadTruncatedMobileNet();
    setTruncatedMobileNet(currentTruncatedMobileNet);
    let screenShot = await currentWebcam.capture();
    currentTruncatedMobileNet.predict(screenShot.expandDims(0));
    screenShot.dispose();
  }

  const openWebcam = async () => {
    let currentWebcam;
    try {
      currentWebcam = await tfd.webcam(document.getElementById('webcam2'));
      setWebcam(currentWebcam);
    } catch (e) {
      console.log(e);
    }
    let screenShot = await currentWebcam.capture();
    truncatedMobileNet.predict(screenShot.expandDims(0));
    screenShot.dispose();
  }

  const setupPredictLabel = (classId) => {
    if(classId === 0) {
      setLabel("go forward");
    } else if(classId === 1) {
      setLabel("stop");
    } else if(classId === 2) {
      setLabel("turn left");
    } else if(classId === 3) {
      setLabel("turn right");
    } else {
      setLabel("");
    }
  }

  const train = async () => {
    if (controllerDataset.xs === null) {
      throw new Error('Add some examples before training!');
    }

    let trained_model = await tf.sequential({
      layers: [
        tf.layers.flatten({
          inputShape: truncatedMobileNet.outputs[0].shape.slice(1)
        }),
        tf.layers.dense({
          units: hiddenUnits,
          activation: 'relu',
          kernelInitializer: 'varianceScaling',
          useBias: true
        }),
        tf.layers.dense({
          units: NUM_CLASSES,
          kernelInitializer: 'varianceScaling',
          useBias: false,
          activation: 'softmax'
        })
      ]
    });

    let optimizer = await tf.train.adam(learningRate);
    await trained_model.compile({optimizer: optimizer, loss: 'categoricalCrossentropy', metrics: ['accuracy']});

    let batchSize = Math.floor(controllerDataset.xs.shape[0] * batchSizeFraction);
    if (!(batchSize > 0)) {
      throw new Error(`Batch size is 0 or NaN. Please choose a non-zero fraction.`);
    }

    await trained_model.fit(controllerDataset.xs, controllerDataset.ys, {
      batchSize,
      epochs: epochs,
      callbacks: {
        onBatchEnd: async (batch, logs) => {
          setTrainStatus('Loss: ' + logs.loss.toFixed(5));
        }
      }
    });
    // await setModel(trained_model);
    model = trained_model;

    checkCameraConnection();
    setTrainStatus('Done!');
    setTimeout(() => {
      clearTimeout(trainingTimeout);
      if (!isRunningTestWebcam) {
        openWebcam();
        setIsRunningTestWebcam(true);
      }
      changePages("test");
      // setIsPredicting(true);
      isPredicting = true;
      predict();
    },3000);
  }

  const changePages = (pageName) => {
    switch(pageName) {
      case 'intro': 
        setShowIntroPage(true);
        setShowCollectPage(false);
        setShowDataPage(false);
        setShowParamPage(false);
        setShowTrainingPage(false);
        setShowTestPage(false);
        setShowCollectStop(false);
        // setIsPredicting(false);
        isPredicting = false;
        break;

      case 'collect':
        setShowIntroPage(false);
        setShowCollectPage(true);
        setShowDataPage(false);
        setShowParamPage(false);
        setShowTrainingPage(false);
        setShowTestPage(false);
        setShowCollectStop(false);
        setNavbarCircles(['active', '', '' , '']);
        webcamInit();
        break;

      case 'stop':
        setShowIntroPage(false);
        setShowCollectPage(false);
        setShowDataPage(true);
        setShowParamPage(false);
        setShowTrainingPage(false);
        setShowTestPage(false);
        setShowCollectStop(true);
        // setIsPredicting(false);
        isPredicting = false;
        setDataName('stop');
        break;

      case 'data':
        setShowIntroPage(false);
        setShowCollectPage(false);
        setShowDataPage(true);
        setShowParamPage(false);
        setShowTrainingPage(false);
        setShowTestPage(false);
        setShowCollectStop(false);
        break;

      case 'param':
        setShowIntroPage(false);
        setShowCollectPage(false);
        setShowDataPage(false);
        setShowParamPage(true);
        setShowTrainingPage(false);
        setShowTestPage(false);
        setShowCollectStop(false);
        setNavbarCircles(['done', 'active', '' , '']);
        break;

      case 'training':
        setShowIntroPage(false);
        setShowCollectPage(false);
        setShowDataPage(false);
        setShowParamPage(false);
        setShowTrainingPage(true);
        setShowTestPage(false);
        setShowCollectStop(false);
        setNavbarCircles(['done', 'done', 'active' , '']);
        let newTrainingTimeout = setTimeout(()=>{
          setNeedToReload(true);
          clearTimeout(trainingTimeout);
        }, 45000);
        setTrainingTimeout(newTrainingTimeout);
        train();
        break;

      case 'test':
        setShowIntroPage(false);
        setShowCollectPage(false);
        setShowDataPage(false);
        setShowParamPage(false);
        setShowTrainingPage(false);
        setShowTestPage(true);
        setShowCollectStop(false);
        setNavbarCircles(['done', 'done', 'done' , 'active']);
        break;

      default:
    }
  }

  const startGestureDemo = () => {
    if (canvasList.length === 0) {
      drawCanvasOutline();
    }

    changePages('collect');
  }

  const openDataPage = async (labelName) => {
    setShowCollectPage(false);
    setShowDataPage(true);
    setDataName(labelName);

    if (labelName === 'forward') {
      setCollectPageInfo({name: 'Go forward', emoji: '👆'});
    } else if (labelName === 'stop') {
    } else if (labelName === 'left') {
      setCollectPageInfo({name: 'Turn left', emoji: '👈'});
    } else if (labelName === 'right') {
      setCollectPageInfo({name: 'Turn right', emoji: '👉'});
    } else {
      console.log('error');
    }
  }

  const changeLearningRate = (e) => {
    let changedParamValue = [...paramValue];
    changedParamValue[0] = e.target.value;
    setParamValue(changedParamValue);

    let changedLearningRate = 0.0001;
    switch(changedParamValue[0]) {
      case 0:
        changedLearningRate = 0.00001;
        break;

      case 1:
        changedLearningRate = 0.0001;
        break;

      case 2:
        changedLearningRate = 0.001;
        break;

      case 3: 
        changedLearningRate = 0.003;
        break;

      default:
    }
    setLearningRate(parseFloat(changedLearningRate));
  }

  const changeBatchSizeFraction = (e) => {
    let changedParamValue = [...paramValue];
    changedParamValue[1] = e.target.value;
    setParamValue(changedParamValue);

    let changedBatchSizeFraction = 0.4;
    switch(changedParamValue[1]) {
      case 0:
        changedBatchSizeFraction = 0;
        break;

      case 1:
        changedBatchSizeFraction = 0.1;
        break;

      case 2:
        changedBatchSizeFraction = 0.4;
        break;

      case 3: 
        changedBatchSizeFraction = 1;
        break;

      default:
    }
    setBatchSizeFraction(parseFloat(changedBatchSizeFraction));
  }

  const changeEpochs = (e) => {
    let changedParamValue = [...paramValue];
    changedParamValue[2] = e.target.value;
    setParamValue(changedParamValue);

    let changedEpochs = 20;
    switch(changedParamValue[2]) {
      case 0:
        changedEpochs = 10;
        break;

      case 1:
        changedEpochs = 20;
        break;

      case 2:
        changedEpochs = 40;
        break;

      default:
    }
    setEpochs(parseInt(changedEpochs));
  }

  const changeHiddenUnits = (e) => {
    let changedParamValue = [...paramValue];
    changedParamValue[3] = e.target.value;
    setParamValue(changedParamValue);

    let changedHiddenUnits = 100;
    switch(changedParamValue[3]) {
      case 0:
        changedHiddenUnits = 10;
        break;

      case 1:
        changedHiddenUnits = 100;
        break;

      case 2:
        changedHiddenUnits = 200;
        break;

      default:
    }
    setHiddenUnits(parseInt(changedHiddenUnits));
  }

  const setupDefaultParam = () => {
    setParamValue([1, 2, 1, 1]);
    setLearningRate(0.0001);
    setBatchSizeFraction(0.4);
    setEpochs(20);
    setHiddenUnits(100);
  }

  const startMotor = () => {
    setIsDriving(true);
    _isDriving = true;
  }

  const stopMotor = () => {
    socket.emit('zumi_stop');
    setIsDriving(false);
    _isDriving = false;
  }

  const goBackToParam = () => {
    socket.emit('stop_streaming');
    changePages('param');
    // setIsPredicting(false);
    isPredicting = false;
    stopMotor();
  }

  const resetDemo = () => {
    socket.emit('zumi_stop');
    socket.emit('stop_streaming');
    // setIsPredicting(false);
    isPredicting = false;
    window.location.reload();
  }

  const goToExplore = () => {
    socket.emit('zumi_stop');
    socket.emit('stop_streaming');
    isPredicting = false;
    let explorePage =
      "http://" +
      window.location.hostname +
      "/explore";
    window.location.href = explorePage;
  }

  return (
    <div className="Gesture">
      <div className='container'>
        <div className="gesture-nav row mx-auto" style={{display: showIntroPage? "none":""}}>
          <div className="gesture-current-page col">
            <span className={["circle"].concat(navbarCircles[0]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            
            <div className="gesture-nav-txt">{text.demo_gesture_nav_collect}</div>
          </div>

          <div className="gesture-arrow col">
            <div className="arrow-line"></div>
            <div className="arrow-triangle"></div>
          </div>

          <div className="gesture-current-page col">
            <span className={["circle"].concat(navbarCircles[1]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="gesture-nav-txt">{text.demo_gesture_nav_adjust}</div>
          </div>

          <div className="gesture-arrow col">
            <div className="arrow-line"></div>
            <div className="arrow-triangle"></div>
          </div>

          <div className="gesture-current-page col">
            <span className={["circle"].concat(navbarCircles[2]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="gesture-nav-txt">{text.demo_gesture_nav_train}</div>
          </div>

          <div className="gesture-arrow col">
            <div className="arrow-line"></div>
            <div className="arrow-triangle"></div>
          </div>

          <div className="gesture-current-page col">
            <span className={["circle"].concat(navbarCircles[3]).join(" ")}>
              <img src={checkIcon} alt="check" className="check" />
            </span>
            <div className="gesture-nav-txt">{text.demo_gesture_nav_play}</div>
          </div>
        </div>

        <div className="gesture-intro-nav mx-auto" style={{display: showIntroPage? "":"none"}}>
          <Button className='close-btn' onClick={goToExplore}>
            {text.demo_btn_close}
          </Button>
        </div>

        <div className="gesture-div" style={{display:  showIntroPage ? '' : 'none'}}>
          <div className="gesture-intro-header">{text.demo_gesture_intro_header}</div>
          <div className="row">
            <div className="col-5 gesture-intro-content">
              {text.demo_gesture_intro_body}
            </div>
            <div className="col-7">
              <img className="gesture-intro-illustration" src={gestureIllustration} alt="gesture-illustration"/>
            </div>
          </div>
          <Button
            className="gesture-intro-play-btn"
            onClick={startGestureDemo}
          >
            {text.demo_btn_play}
          </Button>
        </div>

        <div className="gesture-div gesture-collect-div" style={{display:  showCollectPage ? '' : 'none'}}>
          <div className="gesture-title">{text.demo_gesture_collect_header}</div>
          <div className="gesture-content mx-auto">{text.demo_gesture_collect_body}</div>
          <div className='collect-body-div'>
            <div className="row collect-top-div">
              <div className="col-5">
                <span className="thumb-name-top">{text.demo_gesture_collect_label_forward}</span>
              </div>

              <div className="col-2 small-canvas">
                <canvas className="thumb mx-auto" width="224" height="224" id="forward-thumb"></canvas>
              </div>

              <div className="col-5">
                <Button className="collect-btn collect-btn-top" onClick={() => openDataPage("forward")}>{text.demo_gesture_collect_btn}</Button>
              </div>
            </div>

            <div className="row collect-mid-div">
              <div className="col small-canvas">
                <div className="thumb-name-mid">{text.demo_gesture_collect_label_left}</div>
                <canvas className="thumb" width="224" height="224" id="left-thumb"></canvas>
                <Button className="collect-btn" onClick={() => openDataPage("left")}>{text.demo_gesture_collect_btn}</Button>
              </div>

              <div className="col-5">
                <img src={zumiImg} alt="zumi-img"/>
              </div>

              <div className="col small-canvas">
                <div className="thumb-name-mid">{text.demo_gesture_collect_label_right}</div>
                <canvas className="thumb" width="224" height="224" id="right-thumb"></canvas>
                <Button className="collect-btn" onClick={() => openDataPage("right")}>{text.demo_gesture_collect_btn}</Button>
              </div>
            </div>
          </div>
          <div className="btn-div">
            <Button
              className="back"
              onClick={() => changePages("intro")}
            >
              {text.btn_back}
            </Button>

            {activateNextButton && (
              <Button
                className="next"
                onClick={() => changePages("stop")}
              >
                {text.btn_next}
              </Button>
            )}
            
            {!activateNextButton && (
              <Button className="next deactivate">
                {text.btn_next}
              </Button>
            )}
          </div>
        </div>

        <div className="gesture-adjust-div gesture-div" style={{display:  showParamPage ? '' : 'none'}}>
          <div className="gesture-title">{text.demo_gesture_param_header}</div>
          <div className="gesture-content mx-auto">
            {text.demo_gesture_param_body}
          </div>

          <div className="row">
            <div className="col-6">
              <div className="param-name">
                {text.demo_gesture_param_label_learning_rate}
                <Dropdown
                  className="param-info"
                  onMouseEnter={() => setShowLRInfo(true)}
                  onMouseLeave={() => setShowLRInfo(false)}
                  show={ showLRInfo}
                >
                  <Dropdown.Toggle>
                    <img alt="info" src={infoIcon} />
                  </Dropdown.Toggle>
                  <Dropdown.Menu>
                    <div className="dropdown-tooltip"></div>
                    <div className="param-explanation">{text.demo_gesture_param_description_learning_rate}</div>
                  </Dropdown.Menu>
                </Dropdown>
              </div>

              <div className="param-slide">
                <input
                  type="range"
                  min="0"
                  max="3"
                  value={paramValue[0]}
                  className="slider"
                  id="learning-rate"
                  onChange={e => changeLearningRate(e)}
                />
                <div className="param-value row">
                  <div className="col-3">0.00001</div>
                  <div className="col-3">0.0001</div>
                  <div className="col-3">0.001</div>
                  <div className="col-3">0.003</div>
                </div>
              </div>
            </div>

            <div className="col-6">
              <div className="param-name">
                {text.demo_gesture_param_label_batch_size}
                <Dropdown
                  className="param-info"
                  onMouseEnter={() => setShowBSInfo(true)}
                  onMouseLeave={() => setShowBSInfo(false)}
                  show={showBSInfo}
                >
                  <Dropdown.Toggle>
                    <img alt="info" src={infoIcon} />
                  </Dropdown.Toggle>
                  <Dropdown.Menu>
                    <div className="dropdown-tooltip"></div>
                    <div className="param-explanation">{text.demo_gesture_param_description_batch_size}</div>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
              <div className="param-slide">
                <input
                  type="range"
                  min="0"
                  max="3"
                  value={paramValue[1]}
                  className="slider"
                  id="batch-size"
                  onChange={e => changeBatchSizeFraction(e)}
                />
                <div className="param-value row">
                  <div className="col-3">5%</div>
                  <div className="col-3">10%</div>
                  <div className="col-3">40%</div>
                  <div className="col-3">100%</div>
                </div>
              </div>
            </div>
          </div>

          <div className="row space-div"></div>

          <div className="row">
            <div className="col-6">
              <div className="param-name">
                {text.demo_gesture_param_label_epochs}
                <Dropdown
                  className="param-info"
                  onMouseEnter={() => setShowEpochsInfo(true)}
                  onMouseLeave={() => setShowEpochsInfo(false)}
                  show={showEpochsInfo}
                >
                  <Dropdown.Toggle>
                    <img alt="info" src={infoIcon} />
                  </Dropdown.Toggle>
                  <Dropdown.Menu>
                    <div className="dropdown-tooltip"></div>
                    <div className="param-explanation">
                      {text.demo_gesture_param_description_epochs}
                    </div>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
              <div className="param-slide">
                <input
                  type="range"
                  min="0"
                  max="2"
                  value={paramValue[2]}
                  className="slider"
                  id="epochs"
                  onChange={e => changeEpochs(e)}
                />
                <div className="param-value row">
                  <div className="col-4">10</div>
                  <div className="col-4">20</div>
                  <div className="col-4">40</div>
                </div>
              </div>
            </div>

            <div className="col-6">
              <div className="param-name">
                {text.demo_gesture_param_label_hidden_units}
                <Dropdown
                  className="param-info"
                  onMouseEnter={() => setShowHUInfo(true)}
                  onMouseLeave={() => setShowHUInfo(false)}
                  show={showHUInfo}
                >
                  <Dropdown.Toggle>
                    <img alt="info" src={infoIcon} />
                  </Dropdown.Toggle>
                  <Dropdown.Menu>
                    <div className="dropdown-tooltip"></div>
                    <div className="param-explanation">{text.demo_gesture_param_description_hidden_units}</div>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
              <div className="param-slide">
                <input
                  type="range"
                  min="0"
                  max="2"
                  value={paramValue[3]}
                  className="slider"
                  id="hidden-units"
                  onChange={e => changeHiddenUnits(e)}
                />
                <div className="param-value row">
                  <div className="col-4">10</div>
                  <div className="col-4">100</div>
                  <div className="col-4">200</div>
                </div>
              </div>
            </div>
          </div>
          
          <Button
            onClick={setupDefaultParam}
            className="param-default-btn"
          >
            {text.demo_gesture_param_default_btn}
          </Button>

          <div className="btn-div">
            <Button
                className="back"
                onClick={() => changePages('collect')}
              >
                {text.btn_back}
              </Button>
            <Button
              className="next"
              onClick={() => changePages("training")}
            >
              {text.btn_next}
            </Button>
          </div>
        </div>

        <div className="gesture-training-div gesture-div" style={{display: showTrainingPage ? '' : 'none'}}>
          <div className="gesture-title">
            {trainStatus !== "Done!" && (
              <p>{text.demo_gesture_train_training_header}</p>
            )}
            {trainStatus === "Done!" && (
              <p>{text.demo_gesture_train_done_header}</p>
            )}
          </div>
          <div className="gesture-loading mx-auto">
            {trainStatus !== "Done!" && (
              <LoadingScreen />
            )}
            {trainStatus === "Done!" && (
              <div className="happy-face">
                <img src={happyFace} alt="happy face"/>
              </div>
            )}
          </div>
          <div>
            {trainStatus !== "Done!" && (
              <p>{text.demo_gesture_train_training_body}</p>
            )}
            {needToReload && (
              <div>
                <p>{text.demo_gesture_train_timeout_msg_1}</p>
                <p>{text.demo_gesture_train_timeout_msg_2}</p>
              </div>
            )}
            {trainStatus === "Done!" && (
              <p>{text.demo_gesture_train_done_body}</p>
            )}
          </div>
        </div>

        <div className="gesture-test-div gesture-div" style={{display: showTestPage ? '' : 'none'}}>
          <div className="gesture-title">
          <p className='test-header-text'>{text.demo_gesture_play_header}</p>
            <Button className="back" onClick={goBackToParam}>
              {text.btn_back}
            </Button>
            
          </div>

          <div className="gesture-content">
            {text.demo_gesture_play_body}
          </div>

          <div className="row">
            <div className="col-1"></div>
            <div className="col-7 zumi-cam-div">
              {/* {isZumiCamConnected && isZumiCamRunning && (
                <iframe className="zumi-cam" title="zumi-camera" key={random} src={"https://" + window.location.hostname + ":3456"}></iframe>
              )}
              {isZumiCamConnected && !isZumiCamRunning && !isZumiCamLoading && (
                <div className="turn-off">
                  <img alt="closed eyes" src={closedEyes} />
                  <p>
                    {text.zumi_cam_turned_off}
                  </p>
                </div>
              )}
              {isZumiCamLoading && (
                <div className="loading">
                  <LoadingScreen />
                  <p>{text.zumi_cam_loading}</p>
                </div>
              )}
              {!isZumiCamConnected && (
                <div className="disconnected">
                  <img alt="xx eyes" src={xxEyes} />
                  <div>
                    {text.zumi_cam_disconnected && text.zumi_cam_disconnected.split('\\n').map((item, i) => {
                      return <p key={i}>{item}</p>;
                    })}
                  </div>
                </div>
              )} */}
              <PiCamera />
              <video
                autoPlay playsInline muted
                id="webcam2"
                className="test-webcam"
                width="224"
                height="224"
              >
              </video>
            </div>
            <div className="col-4">
              <div className="test-label">{text.demo_gesture_play_label_txt}</div>
              <div className="test-value mx-auto">{label}</div>
              <div className="test-label">{text.demo_gesture_play_confidence_txt}</div>
              <div className="test-value mx-auto">{confidence}%</div>
              { isDriving && (
                <Button className="motor-control-btn stop" onClick={stopMotor}>{text.demo_gesture_play_stop_btn}</Button>
              )}
              { !isDriving && (
                <Button className="motor-control-btn" onClick={startMotor}>{text.demo_gesture_play_start_btn}</Button>
              )}
            </div>
          </div>

          <div className="test-btn-div">
            <Button
              className="test-start-over-btn"
              onClick={resetDemo}
            >
              {text.demo_btn_start_over}
            </Button>

            <Button
              className="test-close-btn"
              onClick={goToExplore}
            >
              {text.demo_btn_close}
            </Button>
          </div>
        </div>

        <div className="gesture-data-div gesture-div" style={{display: showDataPage ? '' : 'none'}}>
          {showCollectStop && (
            <div className="gesture-title">{text.demo_gesture_collect_stop_header}</div>
          )}
          {!showCollectStop && (
            <div className="gesture-title">
              '{collectPageInfo.name}'
              <span>
                {collectPageInfo.emoji}
              </span>
            </div>
          )}
          {showCollectStop && (
            <div className="gesture-content">{text.demo_gesture_collect_stop_body}</div>
          )}
          {!showCollectStop && (
            <div className="gesture-content">
              {text.demo_gesture_collect_gesture_body_1} '<b>{collectPageInfo.name.toLowerCase()}</b>'. <br/>
              {text.demo_gesture_collect_gesture_body_2}
            </div>
          )}
          <div className="row">
            <div className="col-4"></div>
            <div className="col-4">
              <video
                autoPlay playsInline muted
                id="webcam"
                className="collect-webcam"
                width="224"
                height="224"
              >
              </video>
              {showCollectStop && (
                <img alt="stop-outline" src={stopExampleImg} className="stop-gesture"/>
              )}
            </div>
            <div className="col-4">
              <div>{text.demo_gesture_take_photo_btn}</div>
              <div
                className="mx-auto take-photo-btn"
                onMouseDown={loadedModel ? takePhotoHandler : null}
                onMouseUp={() => clearInterval(photoInt)}
                onMouseLeave={() => clearInterval(photoInt)}
              >
                <img src={cameraIcon} alt="camera-icon" className=""/>
              </div>
            </div>
          </div>
          <div className="data-img-div mx-auto">
            <div>
              { displayCanvasList }
            </div>
          </div>
          { showCollectStop && (
            <div className="collect-stop-btn-div btn-div">
              <Button
                className="back"
                onClick={() => changePages('collect')}
              >
                {text.btn_back}
              </Button>

              {isEnoughData && (
                <Button
                  className="next"
                  onClick={() => changePages("param")}
                >
                  {text.btn_next}
                </Button>
              )}
              {!isEnoughData && (
                <Button 
                  className="next deactivate">
                  {text.btn_next}
                </Button>
              )}
            </div>
          )}

          { !showCollectStop && (
            <Button
              className="gesture-data-done-btn"
              onClick={() => changePages("collect")}
            >
              {text.btn_done}
            </Button>
          )}
        </div>
      </div>
    </div>
  )
}

export default Gesture;

