import React, { useState, useContext, useEffect } from 'react';
import '../styles/SelectNetwork.scss';
import Modal from "react-bootstrap/Modal";
import Button from './lib/Button';

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';

import ZumiFaceNeutral from '../assets/zumiface_neutral.svg';
import spinnerIcon from '../assets/spinner.svg';
import lockIcon from "../assets/lock.svg";
import hidePassword from "../assets/connect_network_no_pw.svg";
import showPassword from "../assets/connect_network_show_pw.svg";

const SELECT_LABEL = "select a WiFi network";

const SelectNetwork = () => {
  const { zumiName, text } = useContext(DefaultContext);
  const { showSelectNetwork, setShowSelectNetwork, wifiList, setWifiList,
    selectedWifi, setSelectedWifi, pwd, setPwd, needPwd, setNeedPwd, connectWifi,
    clearSelectNetworkInfo } = useContext(NetworkContext);
  // const { socket } = useContext(socket);

  const [showWifiDropdown, setShowWifiDropdown] = useState(false);
  const [showPwdText, setShowPwdText] = useState(false);
  const [pwdIcon, setPwdIcon] = useState(hidePassword);

  const toggleWifiDropdown = () => {
    setShowWifiDropdown(!showWifiDropdown);
  }

  const onKeyPressPwd = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      connectWifi();
    }
  }

  const togglePwdType = () => {
    if(showPwdText) setPwdIcon(hidePassword);
    else setPwdIcon(showPassword);
    setShowPwdText(!showPwdText);
  }

  const close = () => {
    setShowSelectNetwork(false);
    clearSelectNetworkInfo();
  }


  
  return (
    <Modal className='SelectNetwork' show={showSelectNetwork} onHide={close}>
      <Modal.Header closeButton onClick={close}></Modal.Header>
      <Modal.Body>
        <div>
          <img alt='zumi face' className='zumi' src={ZumiFaceNeutral} />
          <div className='info'>
            <p>{text.network_login_hello}{' '}<strong>{zumiName}!</strong></p>
            <p>{text.network_login_helpme}</p>
            <p>{text.network_login_notice}</p>
          </div>
          <div className='list'>
            <div>
              <div className={
                  'select ' +  
                  (wifiList.length > 0 ? '': 'hide-arrow ') +
                  (showWifiDropdown? 'show-dropdown ' : '') 
                }
                onClick={toggleWifiDropdown}
              >
                {selectedWifi}
                <div className='spinner'>
                  <img alt='spinner-icon' src={spinnerIcon} />
                </div>
                <div className='arrow'></div>
              </div>
              <div
                className={showWifiDropdown? 'dropdown' : 'dropdown hide'}
                onClick={toggleWifiDropdown}
              >
                {wifiList.map((item, i) => {
                  return (
                    <div
                      className='item'
                      key={i.toString()}
                      onClick={() => {
                        setSelectedWifi(item.value)
                        setNeedPwd(item.pwd)
                      }}
                    >
                      {item.value}
                      {item.pwd && <img src={lockIcon} alt="pwd" />}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
          {needPwd && (
            <div className='password'>
              <input
                value={pwd}
                type={showPwdText? 'text': 'password'}
                placeholder={text.network_login_pw}
                onChange={(e) => setPwd(e.target.value)}
                onKeyPress={onKeyPressPwd}
              />
              <img
                alt="password-icon"
                src={pwdIcon}
                onClick={togglePwdType}
              />
            </div>
          )}
          <div>
          <Button className={selectedWifi === SELECT_LABEL ? 'disabled': ''} onClick={connectWifi}>
            {text.network_login_btn_connect}
          </Button>
          </div>
        </div>
      </Modal.Body>
    </Modal>
  );
}

export default SelectNetwork;