import React, { useState, useContext, useEffect } from 'react';

import { useHistory } from 'react-router-dom';

import '../styles/Learn.scss';

import Modal from 'react-bootstrap/Modal';

import Button from './lib/Button';

import Header from './Header';
import Footer from './Footer';
import Explanation from './Explanation';

import { DefaultContext } from '../contexts/DefaultContext';
import { SocketContext } from '../contexts/SocketContext';

import ZumiSadFace from "../assets/zumiface_sad.svg";

const Learn = (props) => {
  let history = useHistory();
  const { text, currentUser, language } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);

  const [lessonList, setLessonList] = useState([]);
  const [cannotLoadLessons, setCannotLoadLessons] = useState(false);

  useEffect(() => {
    document.body.style = 'background-color: #cce9ff';
    document.querySelector('.background').style = 'background-color: #cce9ff';

    if (currentUser === '') {
      history.push('/login');
      return;
    }


    fetch("LessonList.json")
    .then(response => response.json())
    .then((data) => {
      setLessonList([...data.LessonList]);
      if (data.LessonList.length === 1) {
        setCannotLoadLessons(true);
      }
    })
    .catch(error => console.log(error));

    return (() => {
      document.body.style = 'background-color: #ccf5f1'
      document.querySelector('.background').style = 'background-color: #ccf5f1';
    })
  }, []);

  const goToMainPage = () => {
    history.push('./main');
  }

  const goToJupyterHome = () => {
    let jupyterHome =
     window.location.protocol +
     "//" +
     window.location.hostname +
     ":5555/tree/";
    window.open(jupyterHome, "_blank");
  }

  const lessonClicked = (lessonTitle) => {
    let jupyterLesson =
     window.location.protocol +
     "//" +
     window.location.hostname +
     ":5555/notebooks/Zumi_Content_" + language + "/Lesson/" +
     lessonTitle +
     ".ipynb";
    window.open(jupyterLesson, "_blank");
  }

  const openLoggedLessons = () => {
    let loggedLessons =
      window.location.protocol +
      "//" +
      window.location.hostname +
      ":5555/tree/content_history";
    window.open(loggedLessons, "_blank");
  }

  const reboot = () => {
    window.sessionStorage.clear();
    window.location.replace(window.location.protocol + "//" + window.location.hostname);
    // document.body.classList.add("fade-out");
    // setTimeout(() => {
    //    history.push('/shutting-down');
    //    socket.emit("reboot");
    // },1500); // TODO
  }

  return (
    <div className='Learn'>
      <Header/>

      <Modal 
        className="cannot-load-modal" 
        show={cannotLoadLessons} 
        onHide={() => setCannotLoadLessons(false)}
      >
        <div className="cannot-load-content">
          <Modal.Header/>

          <Modal.Body>
            <div className='sad-zumi'>
              <img alt="sad face" src={ZumiSadFace} />
            </div>

            <div className='cannot-load-text'>
              <p className="msg-1">{text.learn_error_title}</p>
              <p className="msg-2">{text.learn_error_body}</p>
            </div>
          </Modal.Body>

          <Modal.Footer>
            <Button 
              className='reboot-btn' 
              onClick={reboot}
            >
              {text.learn_error_btn_reboot}
            </Button>
          </Modal.Footer>
        </div>
      </Modal>
      
      <div className="learn-fixed">
        <Button
          className="back"
          onClick={goToMainPage}
        >
          <p>{text.btn_back}</p>
        </Button>

        <Button 
          className="go-to-jupyter-home" 
          onClick={goToJupyterHome}
        >
          {text.learn_btn_my_folder}
        </Button>

        <div className='learn-header'>
          <div className="title">{text.lesson_header}</div>
          <div className="description">{text.lessons_body}</div>
        </div>
      </div>
      
      <div className="container">
        <div className="row learn-list mx-auto">
          {lessonList.map((item,i) => {
            return (
              <div className="col-xl-4 col-lg-6 col-md-12 learn-card-overlay" key={i}>
                <div
                  className="learn-card"
                  onClick={() => item.title === "Lessons not found"? null : lessonClicked(item.title)}
                >
                  { item.title === "Lessons not found" && (
                    <div className="title">
                      { language === "ko" && (
                        "레슨을 찾을 수 없습니다."
                      )}
                      { language !== "ko" && (
                        item.title
                      )}
                    </div>
                  )}
                  { item.title !== "Lessons not found" && (
                    <div className="title">
                      {item.title && item.title.length > 30 && (
                        item.title.substring(0, 30) + "..."
                      )}
                      {item.title && item.title.length <= 30 && (
                        item.title
                      )}
                    </div>
                  )}

                  { item.title === "Lessons not found" && (
                    <div className="description">
                      { language === "ko" && (
                        "레슨을 불러오는데 문제가 생겼습니다. 재부팅이 필요합니다."
                      )}
                      { language !== "ko" && (
                        item.description
                      )}
                    </div>
                  )}
                  { item.title !== "Lessons not found" && (
                    <div className="description">
                      {item.description}
                    </div>
                  )}
                    {item.title !== "Lessons not found" && (
                      <Button className='launch-btn'>{text.lessons_btn_launch}</Button>
                    )}
                    {item.title === "Lessons not found" && (
                      <Button className='launch-btn' onClick={reboot}>
                        { language === "ko" && "재부팅"}
                        { language !== "ko" && "Reboot"}
                      </Button>
                    )}
                </div>
              </div>)
          })}
          <div className="col-xl-4 col-lg-6 col-md-12 learn-card-overlay" key="100">
            <div
              className="logged-learn-card learn-card"
            >
              <div className="title">
                {text.learn_logged_title}
              </div>
              <div className="description">
                {text.learn_logged_description && (
                  text.learn_logged_description.split('\\n').map((item, i) => {
                    return <p key={i}>{item}</p>;
                  })
                )}
              </div>
              <Button 
                className='launch-btn' 
                onClick={openLoggedLessons}
              >
                Open Logged Lessons
              </Button>
            </div>
          </div>
        </div>
      </div>
      <Footer />

      <Explanation />
    </div>
  )
}

export default Learn;