import React, { createContext, useState, useEffect } from 'react';
import socketIOClient from "socket.io-client";

export const SocketContext = createContext();

const dashboardUrl = `${window.location.protocol}//${window.location.hostname}`;
// const dashboardUrl = 'http://192.168.219.106';
// const dashboardUrl = 'http://zumidashboard.ai';

const SocketContextProvider = (props) => {
  const [socket, setSocket] = useState(socketIOClient(dashboardUrl));
  const [connected, setConnected] = useState(true);

  useEffect(() => {
    socket.on('disconnect', () => {
      setConnected(false);
      console.log('disconnected at: ', new Date().toString());
    });
    socket.on('reconnect', () => {
      setConnected(true);
      console.log('reconnected at: ', new Date().toString());
    });
  }, []);

  return (
    <SocketContext.Provider value={{ socket, connected, setSocket }}>
      {props.children}
    </SocketContext.Provider>
  )
}

export default SocketContextProvider;