import React, { useState, useContext, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

import '../styles/Explore.scss';

import Button from './lib/Button';

import Header from './Header';
import Footer from './Footer';

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';

import backButton from "../assets/back_button.svg";

const Explore = (props) => {
  let history = useHistory();

  const { text, language, currentUser } = useContext(DefaultContext);
  const { online, networkName, onlineStatus, ipAddress } = useContext(NetworkContext);

  useEffect(() => {
    document.body.style = 'background-color: #f4f1ff';
    document.querySelector('.background').style = 'background-color: #f4f1ff';

    return ( () => {
      document.body.style = 'background-color: #ccf5f1';
    })
  },[])

  const goToMainPage = () => {
    history.push('./main');
  }

  const saveInformation = () => {
    sessionStorage.setItem('currentUser', currentUser);
    sessionStorage.setItem('online', online);
    sessionStorage.setItem('networkName', networkName);
    sessionStorage.setItem('onlineStatus', onlineStatus);
    sessionStorage.setItem('ipAddress', ipAddress);
  }

  const goToGesture = () => {
    saveInformation();
    let gestureDemo =
      "https://" + 
      window.location.hostname +
      ":8443/gesture?language=" + language;
    window.location.href = gestureDemo;
  }

  const goToRegression = () => {
    history.push('/learning-drive-distance'); // TODO
  }

  const goToLearningColors = () => {
    history.push('/learning-colors') // TODO
  }

  return (
    <div className='Explore'>
      <Header/>

      <div className="explore-fixed">
        <Button 
          className="back" 
          onClick={goToMainPage}
        >
          <p>{text.btn_back}</p>
        </Button>
        
        <div className="explore-header">
          <div className="title">{text.demo_header}</div>
          <div className="description">
            {text.demo_body}
          </div>
        </div>
      </div>

      <div className="container">
        <div className="explore-card col-xl-4 col-lg-4 col-md-12">
          <div className="title">
            {text.demo_gesture_title}
          </div>
          <div className="description">
            {text.demo_gesture_description}
          </div>
          <Button 
            className="open-btn" 
            onClick={goToGesture}
          >
            {text.demo_btn_open}
          </Button>
        </div>

        <div className="explore-card col-xl-4 col-lg-4 col-md-12">
          <div className="title">
            {text.demo_regression_title}
          </div>
          <div className="description">
            {text.demo_regression_description && (
              text.demo_regression_description.split("<b>").map((item,i) => {
                if(i !== 0) {
                  let temp = item.split("</b>");
                  return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}
          </div>
          <Button 
            className="open-btn"
            onClick={goToRegression}
          >
            {text.demo_btn_open}
          </Button>
        </div>

        <div className="explore-card col-xl-4 col-lg-4 col-md-12">
          <div className="title">
            {text.demo_colors_title}
          </div>
          <div className="description">
            {text.demo_colors_description && (
              text.demo_colors_description.split("<b>").map((item,i) => {
                if(i !== 0) {
                  let temp = item.split("</b>");
                  return <span key={i}><b>{temp[0]}</b>{temp[1]}</span>
                } else {
                  return <span key={i}>{item}</span>
                }
              })
            )}
          </div>
          <Button 
            className="open-btn"
            onClick={goToLearningColors}
          >
            {text.demo_btn_open}
          </Button>
        </div>
      </div>
      <Footer />
    </div>
  )
}

export default Explore;