import React from 'react';
import { Route } from 'react-router-dom';

import './App.scss';

import LostConnection from './components/LostConnection';

import Home from './components/Home';
import Login from './components/Login';
import MainPage from './components/MainPage';
import Explore from './components/Explore';
import Learn from './components/Learn';
import DriveMode from './components/DriveMode';
import CodeMode from './components/CodeMode';
import Gesture from './components/Demo/Gesture/Gesture';
import LinearRegression from './components/Demo/LinearRegression';
import Knn from './components/Demo/Knn/Knn';

import MeetsFamily from './components/Demo/Video/MeetsFamily';
import SmileDrive from './components/Demo/Video/SmileDrive';

const App = (props) => {
  return (
    <div className="App">
      <LostConnection />
      
      <Route exact path='/' component={Home} />
      <Route path='/login' component={Login} />
      <Route path='/main' component={MainPage} />
      <Route path="/explore" component={Explore} />
      <Route path="/learn" component={Learn} />
      <Route path='/drive-mode' component={DriveMode} />
      <Route path='/code-mode' component={CodeMode}/>
      <Route path="/gesture" component={Gesture} />
      <Route path='/learning-drive-distance' component={LinearRegression} />
      <Route path='/learning-colors' component={Knn} />

      <Route path='/zumi-meets-your-family' component={MeetsFamily} />
      <Route path='/smile-and-drive' component={SmileDrive} />
    </div>
  );
}

export default App;
