import React, { useState, useContext, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

import '../styles/Explanation.scss';

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';
import { SocketContext } from '../contexts/SocketContext';

import loggedLessonArrow from '../assets/overlay_logged_lesson_arrow.svg';

const Explanation = (props) => {
  let history = useHistory();

  const { text, currentUser } = useContext(DefaultContext);
  const { online } = useContext(NetworkContext);
  const { socket } = useContext(SocketContext);

  const [ isIntroductoryShowing, setIsIntroductoryShowing ] = useState({"main":false, "learn":false});
  const [ lessonError, setLessonError ] = useState(false);
  const [ layoutName, setLayoutName ] = useState('');

  useEffect(() => {
    if (currentUser === '') history.push('/');

    setLayoutName(window.location.pathname.slice(1));

    if(checkFirstVisit()) {
      socket.emit("check_overlay", currentUser);
      socket.on("check_overlay", checkOverlay);
    } else {
      let _isIntroductoryShowing = JSON.parse(window.sessionStorage.getItem("explanation"));
      setIsIntroductoryShowing(_isIntroductoryShowing);
    }
    if (layoutName === "learn") {
      checkLessonError();
    }
    return ( () => {
      socket.removeAllListeners("check_overlay");
    })
  },[])

  const checkLessonError = () => {
    fetch("LessonList.json")
      .then(response => response.json())
      .then((data) => {
        // this.setState({ lessonList: data.LessonList });
        if (data.LessonList.length === 1) {
          setLessonError(true);
        }
      })
      .catch(error => console.log(error));
  }

  const checkFirstVisit = () => {
    let explanation =
      window.sessionStorage.getItem("explanation") && window.sessionStorage.getItem("explanation") !== ""
        ? JSON.parse(window.sessionStorage.getItem("explanation"))
        : "";
    if (explanation === "") {
      window.sessionStorage.setItem("explanation", JSON.stringify({"main": false, "learn": true}));
      return true;
    } else {
      if (layoutName === "learn" && explanation["learn"]) {
        window.sessionStorage.setItem("explanation", JSON.stringify({"main": false, "learn": false}));
        return true;
      }
      return false;
    }
  }

  const checkOverlay = (data) => {
    setIsIntroductoryShowing(data);
    socket.removeAllListeners("check_overlay");
  }



  const dontShowHelpAnymore = () => {
    socket.emit("overlay_change", currentUser, layoutName);
    setIsIntroductoryShowing(false);
  }

  const closeOverlay = () => {
    setIsIntroductoryShowing(false);
    let explanation =
      window.sessionStorage.getItem("explanation") && window.sessionStorage.getItem("explanation") !== ""
        ? JSON.parse(window.sessionStorage.getItem("explanation"))
        : "";

    if(layoutName === 'main') {
      window.sessionStorage.setItem("explanation", JSON.stringify({"main": false, "learn": explanation.learn}));
    } else if (layoutName === 'learn') {
      window.sessionStorage.setItem("explanation", JSON.stringify({"main": explanation.main, "learn": false}));
    }
  }


  return (
    <div
      className='Explanation'
      style={{display: isIntroductoryShowing[layoutName] && !lessonError ? "": "none"}}
      onClick={closeOverlay}
    >
      {layoutName === "main" && (
        <div className="main-overlay">
          <header className="Header explanation">
            <div className="zumi-name">
            </div>

            <div className="battery">
            </div>

            <div className="settings">
              <div className="dotted-line"></div>
              <div className="explanation">{text.explanation_main_settings}</div>
            </div>

            {online && (
              <div className="nav-bar">
                <div className="version">
                  <div className="dotted-line"></div>
                  <div className="explanation">{text.explanation_main_version}</div>
                </div>
                <div className="wifi">
                  <div className="dotted-line"></div>
                  <div className="explanation">{text.explanation_main_wifi}</div>
                </div>
              </div>
            )}
            <div className="user-icon">
              <div className="dotted-line"></div>
              <div className="explanation">{text.explanation_main_user}</div>
            </div>
          </header>

          <div className="MainPage">
            <div className="container">
              <div className="content">
                <div className="row">
                  <div className="col-sm-6 col-xs-12">
                    <div className="card explore">
                    </div>
                  </div>
                  <div className="col-sm-6 col-xs-12">
                    <div className="card learn">
                      <div className="dotted-line"></div>
                      <div className="explanation">{text.explanation_main_learn}</div>
                    </div>
                  </div>
                </div>
                <div className="row">
                  <div className="col-sm-6 col-xs-12">
                    <div className="drive-mode">
                      <div className="dotted-line"></div>
                      <div className="explanation">{text.explanation_main_drive}</div>
                    </div>
                  </div>
                  <div className="col-sm-6 col-xs-12">
                    <div className="code-mode">
                      <div className="dotted-line"></div>
                      <div className="explanation">
                        {text.explanation_main_code && (
                          text.explanation_main_code.split('\\n').map((item, i) => {
                            return <p key={i}>{item}</p>;
                          })
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <footer className="dashboard-footer">
            <div className="dotted-line"></div>
            <div className="explanation">{text.explanation_main_shut_down}</div>
          </footer>

          <div className="dont-show-help mx-auto">
            <div
              className="dont-show-checkbox d-inline-block"
              onClick={dontShowHelpAnymore}>
            </div>
            <div className="dont-show-txt d-inline-block">{text.explanation_dont_show_anymore}</div>
          </div>
        </div>
      )}
      {layoutName === "learn" && (
        <div className="learn-overlay">
          <div className="jupyter-dotted-line"></div>
          <div className="jupyter-introductory-txt">{text.explanation_learn_my_folder}</div>

          <div className="dont-show-help mx-auto">
            <div
              className="dont-show-checkbox d-inline-block"
              onClick={dontShowHelpAnymore}>
            </div>
            <div className="dont-show-txt d-inline-block">{text.explanation_dont_show_anymore}</div>
          </div>
          
          <div className="logged-lesson-explanation">
            <div>
              {text.explanation_learn_logged_lessons && (
                text.explanation_learn_logged_lessons.split('\\n').map((item, i) => {
                  return <p key={i}>{item}</p>;
                })
              )}
            </div>
            <img alt="logged lesson arrow" src={loggedLessonArrow} />
          </div>
        </div>
      )}
    </div>
  )
}

export default Explanation;