import React, { useContext, useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

import '../styles/MainPage.scss';

import { DefaultContext } from '../contexts/DefaultContext';
import { SocketContext } from '../contexts/SocketContext';
// import { NetworkContext } from './contexts/NetworkContext';

import Header from './Header';
import Footer from './Footer';
import Explanation from './Explanation';

import exploreBG from '../assets/main_explore_bg.svg';
import learnBG from '../assets/main_learn_bg.svg';
import driveIcon from '../assets/main_steeringwheel.svg';
import codeIcon from '../assets/main_code_24px.svg';
import learnIcon from '../assets/main_school_24px.svg';
import exploreIcon from '../assets/main_explore_24px.svg';
import spinnerIcon from '../assets/spinner_2.svg';

let checkJupyterInterval;

const MainPage = (props) => {
  let history = useHistory();

  const { text, currentUser, isJupyterRunning, setIsJupyterRunning } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);

  useEffect(() => {
    if (currentUser === '') history.push('/');
    setIsJupyterRunning(false);

    checkJupyterInterval = setInterval(() => {
      socket.emit('check_jupyter_server');
    }, 3000);
    socket.emit('check_jupyter_server');
    socket.on('check_jupyter_server', checkJupyterServer);
    setTimeout(() => {
      socket.removeAllListeners('check_jupyter_server');
      clearInterval(checkJupyterInterval);
      setIsJupyterRunning(true);
    }, 45000);
    return () => {
      socket.removeAllListeners('check_jupyter_server');
      clearInterval(checkJupyterInterval);
    }
  }, []);

  const checkJupyterServer = (data) => {
    if(data) {
      socket.removeAllListeners("check_jupyter_server");
      clearInterval(checkJupyterInterval);
      setIsJupyterRunning(true);
    }
  }

  const goToExplore = () => {
     history.push('/explore');
   }

  const goToLearn = () => {
    socket.emit('update_lessonlist_file', currentUser);
    history.push('/learn');
  }

  const goToDriveMode = () => {
    history.push('/drive-mode');
  }
  
  const goToCodeMode = () => {
    history.push('/code-mode');
  }

  return (
      <div className="MainPage">
        <Header/>
        <div className="container">
          <div className="content">
            <div className="row">
              <div className="col-sm-6 col-xs-12">
                <div
                  className="card explore"
                  onClick={goToExplore}
                >
                  <img
                    className="card-img"
                    alt="exploare_bg"
                    src={exploreBG}
                  />
                  <div className="card-img-overlay">
                    <img
                      src={exploreIcon}
                      alt="explore_icon"
                    />
                    <p>{text.dashboard_home_explore}</p>
                  </div>
                </div>
              </div>
              <div className="col-sm-6 col-xs-12">
                <div
                  className={isJupyterRunning? "card learn" : "card learn loading"}
                  onClick={isJupyterRunning? goToLearn : null}
                >
                  <img
                    className="card-img"
                    alt="learn_bg"
                    src={learnBG}
                  />
                  <div className="card-img-overlay">
                    <img
                      src={learnIcon}
                      alt="learn_icon"
                    />
                    <p>{text.dashboard_home_learn}</p>
                  </div>
                </div>
                {!isJupyterRunning && (
                  <div className="spinner">
                    <img alt="spinner icon" src={spinnerIcon} />
                  </div>
                )}
              </div>
            </div>
            <div className="row">
              <div className="col-sm-6 col-xs-12">
                <div
                  className="card drive-mode"
                  onClick={goToDriveMode}
                >
                  <div className='card-img-overlay'>
                    <img
                      src={driveIcon}
                      alt="drive_icon"
                    />
                    <p>{text.dashboard_home_drive_mode}</p>
                  </div>
                </div>
              </div>
              <div className="col-sm-6 col-xs-12">
                <div
                  className={isJupyterRunning? "card code-mode": "card code-mode loading"}
                  onClick={isJupyterRunning? goToCodeMode : null}
                >
                  <div className='card-img-overlay'>
                    <img
                      src={codeIcon}
                      alt="code_icon"
                    />
                    <p>{text.dashboard_home_code_mode}</p>
                  </div>
                </div>
                {!isJupyterRunning && (
                  <div className="spinner">
                    <img alt="spinner Icon" src={spinnerIcon} />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        <Explanation />

        <Footer />
      </div>
  );
}

export default MainPage;
