import React, { useState, useContext } from 'react';
import { useHistory } from 'react-router-dom';

import '../styles/Footer.scss';

import Modal from 'react-bootstrap/Modal';

import Button from './lib/Button';

import { DefaultContext } from '../contexts/DefaultContext';
import { SocketContext } from '../contexts/SocketContext';

import powerIcon from "../assets/footer_power_icon.svg";

const Footer = (props) => {
  let history = useHistory();

  const { text, setShowOverlay } = useContext(DefaultContext);
  const { socket } = useContext(SocketContext);

  const [shutdownModalShow, setShutdownModalShow] = useState(false);

  const handleShutdown = () => {
    setShutdownModalShow(false);
    setShowOverlay(true);
    document.body.classList.add("fade-out");
    //if (!document.getElementsByClassName("global-overlay")[0].classList.contains("user-shutdown")) {
		//	document.getElementsByClassName("global-overlay")[0].classList.add('user-shutdown');
		//} // TODO
    setTimeout( () => {
      //history.push({
      //  pathname: "/shutting-down",
      //}); // TODO
      socket.emit("shutdown");
    }, 1500);
  }

  return (
    <div>
        <Modal
          centered 
          className='footer-modal'
          show={shutdownModalShow}
          onHide={() => setShutdownModalShow(false)}
        >
          <div className="footer-container modal-content kickstarter-modal modal-text text-center">
            <Modal.Header closeButton>
              <div className="mx-auto text modal-header-txt">{text.shutdown_modal_header}</div>
            </Modal.Header>

            <Modal.Body>
              {text.shutdown_modal_msg}
            </Modal.Body>

            <Modal.Footer>
              <Button
                className='btn no-button rounded-pill text-white mx-auto shut-down-no'
                onClick={() => setShutdownModalShow(false)}
              >
                {text.shutdown_modal_btn_no}
              </Button>
              <Button
                className='btn yes-button rounded-pill text-white mx-auto shut-down-yes'
                onClick={handleShutdown}
              >
                {text.shutdown_modal_btn_yes}
              </Button>
            </Modal.Footer>
          </div>
        </Modal>

        <div className="dashboard-footer">
          <div
            className="zumi-power-btn rounded-circle"
            onClick={() => setShutdownModalShow(true)}
          >
            <img className="power-icon" src={powerIcon} alt="power_icon.svg" />
          </div>
        </div>
      </div>
  )
}

export default Footer;