import React from 'react';
import "./LoadingScreen.scss";

import blankFace from "../../assets/zumiface_blank.svg";
import thinkingIcon from "../../assets/thinking_icon.svg";


const LoadingScreen = () => {
  return (
    <div className="LoadingScreen">
      <img className="background-img" src={blankFace} alt="zumi face"/>
      <div className="overlay">
        <img className="overlay-img" src={thinkingIcon} alt="loading" />
      </div>
    </div>
  );
}

export default LoadingScreen;