import React, { useState, useContext, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

import '../styles/Header.scss';

import Tooltip from './lib/Tooltip';
import SelectNetwork from './SelectNetwork';
import ConnectNetwork from './ConnectNetwork';
import Update from './Update';
import OfflineContentMissing from './OfflineContentMissing';
import Navbar from 'react-bootstrap/Navbar';
import Nav from 'react-bootstrap/Nav';
import NavDropdown from 'react-bootstrap/NavDropdown';
import NavItem from 'react-bootstrap/NavItem';
import Dropdown from 'react-bootstrap/Dropdown';
import Modal from "react-bootstrap/Modal";

import { DefaultContext } from '../contexts/DefaultContext';
import { NetworkContext } from '../contexts/NetworkContext';
import { SocketContext } from '../contexts/SocketContext';
import { UpdateContext } from '../contexts/UpdateContext';

import ZumiFaceBlank from '../assets/zumiface_blank.svg';
import ZumiFaceNeutral from '../assets/zumiface_neutral.svg';
import battery25 from '../assets/battery/25.svg';
import battery50 from '../assets/battery/50.svg';
import battery75 from '../assets/battery/75.svg';
import battery100 from '../assets/battery/full.svg';
import batteryChargingIcon from '../assets/battery/charging.svg';
import settingsIcon from '../assets/header_settings_icon.svg';
import checkingWifiIcon from '../assets/wifi_checking.svg';
import onlineIcon from '../assets/wifi_online.svg';
import noNetwork from '../assets/wifi_onnetwork_notonline.svg';
import offlineIcon from '../assets/wifi_offline.svg';
import userIcon from "../assets/header_user_icon.svg";
import arrowIcon from '../assets/back_button.svg';
import spinnerIcon from '../assets/thinking_icon.svg';

let refreshBatteryInterval;

const Header = () => {
  let history = useHistory();

  const { text, zumiName, dashboardVersion, language, setLanguage, firstSetup, loading, currentUser, setCurrentUser} = useContext(DefaultContext);
  const { checkingInternet, online, networkName, onlineStatus, ipAddress, isLastNetwork, setIsLastNetwork, setShowSelectNetwork, 
    openUpdate, disconnectWiFi, wifiListSocket, checkInternet, setOnline, setNetworkName, setOnlineStatus, setIPAddress, setCheckingInternet, 
    setCanUpdateContent, setCanUpdateDashboard, setShowUpdate, fromSwitchingLanguage, setFromSwitchingLanguage } = useContext(NetworkContext);
  const { socket } = useContext(SocketContext);
  const { updateContent,  checkMissingContent, setCheckMissingContent } = useContext(UpdateContext);

  const [batteryIcon, setBatteryIcon] = useState(batteryChargingIcon);
  const [batteryLevel, setBatteryLevel] = useState(0);
  const [batteryPercentList, setBatteryPercentList] = useState([]);
  const [driveModeChargingDuration, setDriveModeChargingDuration] = useState(0);
  const [hardwareInfo, setHardwareInfo] = useState({ cpu_info: '', ram_info: '', mac_address: '', cpu_temp: '', content_version: '', board_version: ''});

  const [isLoginPage, setIsLoginPage] = useState(false);

  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [showLogTooltip, setShowLogTooltip] = useState(false);
  const [showVersionTooltip, setShowVersionTooltip] = useState(false);
  const [showUserDropdown, setShowUserDropdown] = useState(false);

  let hardwareInfoInterval = null;

  useEffect(() => {
    if (window.location.pathname === '/login') setIsLoginPage(true);
    else setIsLoginPage(false);
    if(loading) {
      firstSetup();
    }

    hardwareInfoInterval = setInterval( () => {
      socket.emit('hardware_info');
    }, 10000);
    socket.emit('hardware_info');
    socket.on('hardware_info', (data) => setHardwareInfo(data));
    refreshBatteryPercent();

    return function cleanup() {
      clearInterval(hardwareInfoInterval);
      clearInterval(refreshBatteryInterval);
      socket.removeAllListeners('hardware_info');
      socket.removeAllListeners('check_internet_result');
      socket.removeAllListeners('ssid_list');
      socket.removeAllListeners('connect_wifi_result');
      socket.removeAllListeners('battery_percent')
    }
  }, []);

  useEffect(() => {
    if(window.location.pathname === '/explore') {
      if(!loading && isLastNetwork) {
        setIsLastNetwork(false);
        setCheckingInternet(false);
        reloadInformation();
      }
    } else {
      if(!loading && isLastNetwork) {
        checkInternet(language);
      }
    }
  }, [loading]);

  useEffect(() => {
    if (batteryLevel === 0) {
      setBatteryIcon(batteryChargingIcon);
    } else if (batteryLevel === 1) {
      setBatteryIcon(battery25);
    } else if (batteryLevel === 2) {
      setBatteryIcon(battery50);
    } else if (batteryLevel === 3) {
      setBatteryIcon(battery75);
    } else if (batteryLevel === 4) {
      setBatteryIcon(battery100);
    }
  }, [batteryLevel]);

  const reloadInformation = async() => {
    let _online = sessionStorage.getItem('online') === 'true'? true: false;
    let _onlineStatus = sessionStorage.getItem('onlineStatus') === 'true' ? true: false;
    setCurrentUser(sessionStorage.getItem('currentUser'));
    setOnline(_online);
    setNetworkName(sessionStorage.getItem('networkName'));
    setOnlineStatus(_onlineStatus);
    setIPAddress(sessionStorage.getItem('ipAddress'));
    sessionStorage.clear();
  }

  const refreshBatteryPercent = () => {
    refreshBatteryInterval = setInterval(() => {
      socket.emit('battery_percent');
    }, 3000);
    socket.emit('battery_percent');
    socket.on('battery_percent', getBatteryPercent);
  }

  const getBatteryPercent = (data) => {
    let batteryPercent = parseInt(data);

    if ( batteryPercent === 0 ) {
      if (window.location.pathname === "/drive-mode") {
        if (driveModeChargingDuration < 5) {
          setDriveModeChargingDuration(driveModeChargingDuration + 1);
          return;
        }
      }
      setBatteryPercentList([]);
      convertBatteryLevel(batteryPercent);
      return;
    }

    if ( batteryPercentList.length === 0 ) {
      let newBatteryList = batteryPercentList;
      newBatteryList.push(batteryPercent);
      setBatteryPercentList(newBatteryList);
      setDriveModeChargingDuration(0);
      convertBatteryLevel(batteryPercent);
    } else if ( batteryPercentList.length > 0 && batteryPercentList.length < 10 ) {
      let newBatteryList = batteryPercentList;
      newBatteryList.push(batteryPercent);
      setBatteryPercentList(newBatteryList);
    } else if ( batteryPercentList.length % 10 === 0 ) {
      let newBatteryList = batteryPercentList;
      newBatteryList.push(batteryPercent);
      let sum = 0;
      for (let i=0; i<10; i++) {
        sum += parseInt(newBatteryList[i]);
      }
      batteryPercent = Math.ceil(sum / 10);
      for (let i=0; i<10; i++) {
        newBatteryList.shift();
      }
      setBatteryPercentList(newBatteryList);
      convertBatteryLevel(batteryPercent);
    }
  }

  const convertBatteryLevel = (p) => {
    if (p < 2) setBatteryLevel(0);
    else if (p < 25) setBatteryLevel(1);
    else if (p < 50) setBatteryLevel(2);
    else if (p < 75) setBatteryLevel(3);
    else if (p <= 100) setBatteryLevel(4);
    else setBatteryLevel(0);
  }

  const openSelectNetworkModal = () => {
    wifiListSocket();
    setShowSelectNetwork(true);
  }

  const signOut = () => {
    setCurrentUser('');
    // setExplanation('');
    history.push('/login');
  }

  const saveInformation = () => {
    sessionStorage.setItem('currentUser', currentUser);
    sessionStorage.setItem('online', online);
    sessionStorage.setItem('networkName', networkName);
    sessionStorage.setItem('onlineStatus', onlineStatus);
    sessionStorage.setItem('ipAddress', ipAddress);
  }

  const changeLanguage = (e) => {
    // saveInformation();
    let l = e.target.value;
    setLanguage(l);
    localStorage.setItem('language', l);
    // sessionStorage.setItem('checkMissingContent', true);
    socket.emit('change_language', l);
    setShowSettingsModal(false);
    setCheckMissingContent(true);

    if(window.location.pathname === '/learn') {
      history.push('/main');
    }
    // setTimeout(() => {
    //   window.location.reload();
    // }, 1500);
    
    // history.go(0);
  }

  const versionMenu = (
    <div className="menu">
      <p className="title">
        {text.navbar_version_num_label}
      </p>
      <p className="info">
        v{dashboardVersion}
      </p>
    </div>
  );

  const wifiMenu = (
    <div className="menu">
      <p className="title">
        {text.navbar_connected_to_label}
      </p>
      {checkingInternet && (
        <img alt="checking internet" src={checkingWifiIcon} />
      )}
      {online && onlineStatus && (
        <img alt="online" src={onlineIcon} />
      )}
      {online && !onlineStatus && (
        <Dropdown className="wifi-icon">
          <Dropdown.Toggle>
            <img alt="no network" src={noNetwork} />
          </Dropdown.Toggle>
          <Dropdown.Menu>
            <div className="dropdown-menu-triangle"></div>
            <div className="wifi-dropdown">
              <p>I'm on {networkName},</p>
              <p>I'm just having some trouble getting online.</p>
              <p>I will keep trying.</p>
            </div>
          </Dropdown.Menu>
        </Dropdown>
      )}
      {!online && !checkingInternet && (
        <img alt="wifi-icon" src={offlineIcon} />
      )}
      <p className="info">{networkName}</p>
    </div>
  )

  const settingsModal = (
    <Modal className='settings' show={showSettingsModal} onHide={() => setShowSettingsModal(false)}>
      <Modal.Header closeButton>
        <Modal.Title>{text.setting_modal_header}</Modal.Title>
      </Modal.Header>
      <Modal.Body className='row'>
        <div className='col-12 document'>
          <a target='_blank' href='http://docs.robolink.com/zumi-library'>{text.setting_modal_link_docs}</a>
        </div>
        <div className='col-md-2 col-sm-0'></div>
        <div className='col-md-4 col-sm-6 language'>
          <div className='title'>{text.setting_modal_language}</div>
          <select value={language} onChange={changeLanguage}>
            <option key="0" value="en">
              English
            </option>
            <option key="1" value="ko">
              Korean
            </option>
          </select>
        </div>
        <div className='col-md-4 col-sm-6 battery'>
          <div className='title'>
            {text.setting_modal_battery_percentage && text.setting_modal_battery_percentage.split('\\n').map((item, i) => {
                return <p key={i}>{item}</p>;
            })}
          </div>
          <img alt="battery" src={batteryIcon} id="batteryIcon" />
        </div>
        <div className='col-md-2 col-sm-0'></div>
        <div className='col-md-4 col-sm-6 version'>
          <div className='title'>
            {text.setting_modal_lib_version && text.setting_modal_lib_version
                .split("\\n")
                .map((item, i) => {
                  return <p key={i}>{item}</p>;
            })}
          </div>
          <Tooltip type='up' show={showVersionTooltip}>
            <div>
              <div><span>Zumi Version: </span>v{dashboardVersion}</div>
              <div><span>Library: </span>v</div>
              <div><span>Content: </span>v{hardwareInfo.content_version}</div>
              <div><span>Board firmware: </span>v{hardwareInfo.board_version}</div>
            </div>
          </Tooltip>
          <div
            className='info'
            onMouseOver={() => setShowVersionTooltip(true)}
            onMouseLeave={() => setShowVersionTooltip(false)}
          >v{dashboardVersion}</div>
          <a target='_blank' href='https://github.com/RobolinkInc/zumi-version/blob/master/update_log'>release notes</a>
        </div>
        <div className='col-md-4 col-sm-6'>
          <div className='title'>IP address</div>
          <div className='info'>{ipAddress}</div>
        </div>
        <div className='col-md-4 col-sm-6'>
          <div className='title'>{text.setting_modal_mac_addr}</div>
          <div className='info'>{hardwareInfo.mac_address}</div>
        </div>
        <div className='col-md-4 col-sm-6'>
          <div className='title'>{text.setting_modal_temp}</div>
          <div className='info'>
            {hardwareInfo.cpu_temp}° C /&nbsp;
              {(
                parseInt((parseInt(hardwareInfo.cpu_temp) * 9) / 5) + 32
              ).toString()}
              ° F
          </div>
        </div>
        <div className='col-md-4 col-sm-6'>
          <div className='title'>{text.setting_modal_ram}</div>
          <div className='info'>{hardwareInfo.ram_info}%</div>
        </div>
        <div className='col-md-4 col-sm-6'>
          <div className='title'>{text.setting_modal_cpu}</div>
          <div className='info'>{hardwareInfo.cpu_info}%</div>
        </div>
      </Modal.Body>
    </Modal>
  );  

  return (
    <div className='Header'>
      <div className='background'></div>
      { settingsModal }
      <SelectNetwork />
      <ConnectNetwork />
      <Update />
      <OfflineContentMissing />
      <div className="zumi-name">
        <img src={ZumiFaceBlank} alt="zumiface_blank" />
        <div className="overlay">
          <p>{text.navbar_zumi_name}</p>
          <p>{zumiName}</p>
        </div>
      </div>
      <div className="battery">
        <img alt="battery" src={batteryIcon} id="batteryIcon" />
      </div>
      <div className="settings" onClick={() => setShowSettingsModal(true)}>
        <img alt="settings" src={settingsIcon} />
      </div>
      <Navbar expand="lg">
        <Navbar.Toggle aria-controls="header-navbar-nav" />
        <Navbar.Collapse id="header-navbar-nav">
          <Nav>
            <NavDropdown title={versionMenu} as={NavItem}>
              <NavDropdown.Item onClick={openUpdate}>
                <div className="dropdown-tooltip" />
                {text.navbar_version_update}
              </NavDropdown.Item>
            </NavDropdown>
            <NavDropdown title={wifiMenu} as={NavItem}>
              <NavDropdown.Item onClick={openSelectNetworkModal}>
                <div
                  className="dropdown-tooltip"
                />
                {text.navbar_connect_another}
              </NavDropdown.Item>
              <NavDropdown.Item onClick={disconnectWiFi}>
                Disconnect from WiFi
              </NavDropdown.Item>
            </NavDropdown>
          </Nav>
        </Navbar.Collapse>
      </Navbar>
      <Dropdown
        onMouseEnter={() => setShowUserDropdown(true)}
        onMouseLeave={() => setShowUserDropdown(false)}
        show={showUserDropdown}
        className={
          isLoginPage
            ? "hidden user-icon"
            : "user-icon"
        }
      >
        <Dropdown.Toggle className="header-user-toggle">
          <img className="icon" alt="" src={userIcon} />
          <p className="text">
            {currentUser && currentUser.length > 8 &&
              currentUser.substring(0, 10) + "..."}
            {currentUser && currentUser.length <= 8 &&
              currentUser}
          </p>
        </Dropdown.Toggle>
        <Dropdown.Menu>
          <div className="dropdown-tooltip mx-auto"></div>
          <Dropdown.Item
            onClick={signOut}
            className="header-user-sign-out"
          >
            Sign out
          </Dropdown.Item>
        </Dropdown.Menu>
      </Dropdown>
  </div>
  );
}

export default Header;
