import React, { createContext, useState, useContext } from 'react';
import { useHistory } from 'react-router-dom';

import { SocketContext } from './SocketContext';

export const NetworkContext = createContext();

const SELECT_LABEL = "select a WiFi network";

let refreshWiFiListInterval = null;

const NetworkContextProvider = (props) => {
  let history = useHistory();

  const { socket } = useContext(SocketContext);

 /* Check internet */
  const [isLastNetwork, setIsLastNetwork] = useState(true);
  const [checkingInternet, setCheckingInternet] = useState(true);
  const [online, setOnline] = useState(false);
  const [networkName, setNetworkName] = useState('');
  const [onlineStatus, setOnlineStatus] = useState(false);
  const [ipAddress, setIPAddress] = useState('');

  const [canUpdateDashboard, setCanUpdateDashboard] = useState(false);
  const [canUpdateContent, setCanUpdateContent] = useState(false);
  const [latestDashboardVersion, setLatestDashboardVersion] = useState('');

  /* Select Network */
  const [showSelectNetwork, setShowSelectNetwork] = useState(false);
  const [showOtherNetwork, setShowOtherNetwork] = useState(false);

  const [wifiList, setWifiList] = useState([]);
  const [selectedWifi, setSelectedWifi] = useState(SELECT_LABEL);
  const [needPwd, setNeedPwd] = useState(false);
  const [pwd, setPwd] = useState('');

  /* Connect Network */
  const [showConnectNetwork, setShowConnectNetwork] = useState(false);
  const [tryingToConnectNetwork, setTryingToConnectNetwork] = useState(true);
  const [succeededConnectingNetwork, setSucceededConnectingNetwork] = useState(false);

  /* Update */
  const [showUpdate, setShowUpdate] = useState(false);
  const [updating, setUpdating] = useState(false);
  const [fromSwitchingLanguage, setFromSwitchingLanguage] = useState(false);
  const [offlineContentMissing, setOfflineContentMissing] = useState(false);

  let checkInternetTimeout = null;
  let checkInternetResultInterval = null;

  let connectWiFiTimeout = null;
  let connectWiFiResultInterval = null;


  const setDefault = () => {
    setOnline(false);
    setNetworkName('');
    setOnlineStatus(false);
    setIPAddress('');
    setCanUpdateDashboard(false);
    setCanUpdateContent(false);
    setLatestDashboardVersion('');
  }

  const checkInternet = (language) => {
    checkInternetTimeout = setTimeout( () => {
      setCheckingInternet(false);
      socket.emit('stop_check_internet');
      // socket.emit('stop_last_network');
      try {
        clearInterval(checkInternetResultInterval);
        socket.removeAllListeners('check_internet_result');
        // socket.removeAllListeners('last_network_result');
      } catch (e) {
        console.log(e);
      }
      if(isLastNetwork) {
        history.push('/login');
        setIsLastNetwork(false);
      }
    }, 90000);
    socket.emit('check_internet', language);
    socket.on('check_internet_result', oncheckInternetResult);
    checkInternetResultInterval = setInterval( () => {
      socket.emit('check_internet_result');
    }, 3000);
  }

  const oncheckInternetResult = (data) => {
    /*
      data
      - in_progress : running code
      - False : Zumi is not connected to internet
      - {} : Zumi is connected to internet, wifi information
      
    */
    clearTimeout(checkInternetTimeout);
    if (data === "in_progress") return;

    /* for testing */
    // data = false;

    setCheckingInternet(false);
    setTryingToConnectNetwork(false);
    clearInterval(checkInternetResultInterval);
    socket.removeAllListeners('check_internet_result');
    if(data) {
      setOnline(true);
      setNetworkName(data['network_name']);
      setOnlineStatus(data['online_status']);
      setIPAddress(data['ip_addr']);
      setCanUpdateDashboard(data['can_update_dashboard']);
      setCanUpdateContent(data['can_update_content']);
      setLatestDashboardVersion(data['latest_dashboard_version']);
      socket.emit('zumi_success');

      if(!isLastNetwork) {
        setSucceededConnectingNetwork(true);
        setTimeout(() => {
          setShowConnectNetwork(false);
          if(data['can_update_dashboard'] || data['can_update_content']) setShowUpdate(true);
        }, 3000);
      } else {
        if(data['can_update_dashboard'] || data['can_update_content']) setShowUpdate(true);
      }
    } else {
      /* failed to connect network */
      if(isLastNetwork) {
        wifiListSocket();
        setShowSelectNetwork(true);
        history.push('/login');
      }
      else {
        socket.emit('zumi_fail');
        setSucceededConnectingNetwork(false);
      }
      setDefault();
    }

    if(isLastNetwork) {
      history.push('/login');
      setIsLastNetwork(false);
    }
  }

  /* Select Network */

  const wifiListSocket = () => {
    socket.emit('ssid_list', '');
    refreshWiFiListInterval = setInterval(() => {
      socket.emit('ssid_list', '');
    }, 10000);
    socket.on('ssid_list', onGetWiFiList);
  }

  const onGetWiFiList = (data) => {
    let options = [];
    let wifiArray = Object.keys(data);
    for (let i = 0; i < wifiArray.length; i++) {
      if (wifiArray[i] !== "") {
        let option = {};
        option["value"] = wifiArray[i];
        option["pwd"] = data[wifiArray[i]];
        options.push(option);
      }
    }
    setWifiList(options);
  }

  const clearSelectNetworkInfo = () => {
    setWifiList([]);
    setSelectedWifi(SELECT_LABEL);
    setNeedPwd(false);
    setPwd('');
    clearInterval(refreshWiFiListInterval);
    socket.removeAllListeners('ssid_list');
  }

  /* Conenct Network */

  const connectWifi = () => {
    clearSelectNetworkInfo();
    setShowSelectNetwork(false);
    setShowConnectNetwork(true);

    setTryingToConnectNetwork(true);
    setSucceededConnectingNetwork(false);

    socket.emit('connect_wifi', selectedWifi, pwd, false);
    connectWiFiTimeout = setTimeout( () => {
      socket.emit('stop_connect_wifi');
    }, 100000);
    connectWiFiResultInterval = setInterval( () => {
      socket.emit('connect_wifi_result');
    }, 15000);
    socket.on('connect_wifi_result', onConnectWifiResult);
  }

  const onConnectWifiResult = (data) => {
    /*
      in_progress
      False : failed
      True: finished
    */
    if (data === 'in_progress') return;
    clearTimeout(connectWiFiTimeout);
    clearInterval(connectWiFiResultInterval);
    socket.removeAllListeners('connect_wifi_result');
    if (data) {
      setCheckingInternet(true);
      setDefault();
      checkInternet(localStorage.getItem('language'));
    } else {
      setTryingToConnectNetwork(false);
      setSucceededConnectingNetwork(false);
    }
  }

  const openUpdate = () => {
    if(!online) {
      setShowSelectNetwork(true);
      return;
    }

    setShowUpdate(true);
    if(!canUpdateDashboard && !canUpdateContent) {
      setTimeout(() => {
        setShowUpdate(false);
      }, 3000);
    }
  }

  const disconnectWiFi = () => {
    socket.emit("activate_offline_mode");
    setOnline(false);
    setNetworkName('');
    setOnlineStatus(false);
    setIPAddress('');

    setCanUpdateDashboard(false);
    setCanUpdateContent(false);
    setLatestDashboardVersion('');

    setShowConnectNetwork(false);
  }

  const tryAgain = () => {
    setIsLastNetwork(false);
    setCheckingInternet(false);
    setOnline(false);
    setNetworkName('');
    setIPAddress('');

    setCanUpdateDashboard(false);
    setCanUpdateContent(false);
    setLatestDashboardVersion('');
    
    setShowConnectNetwork(false);
    setTryingToConnectNetwork(false);
    setSucceededConnectingNetwork(false);

    wifiListSocket();
    setShowSelectNetwork(true);
  }
 
  return (
    <NetworkContext.Provider value={{ 
        checkingInternet, networkName, online, onlineStatus, ipAddress, isLastNetwork, setIsLastNetwork, 
        canUpdateDashboard, canUpdateContent, latestDashboardVersion, setCanUpdateDashboard, setCanUpdateContent, 
        wifiList, setWifiList, selectedWifi, setSelectedWifi, pwd, setPwd, needPwd, setNeedPwd,
        connectWifi, checkInternet, wifiListSocket, disconnectWiFi, 
        showSelectNetwork, setShowSelectNetwork, showOtherNetwork, setShowOtherNetwork,
        showConnectNetwork, tryingToConnectNetwork, succeededConnectingNetwork,
        clearSelectNetworkInfo, tryAgain, 
        showUpdate, setShowUpdate, updating, setUpdating, openUpdate,
        setOnline, setOnlineStatus, setNetworkName, setIPAddress, setCheckingInternet, 
        fromSwitchingLanguage, setFromSwitchingLanguage, offlineContentMissing, setOfflineContentMissing
      }}>
      {props.children}
    </NetworkContext.Provider>
  )
}

export default NetworkContextProvider;